$admin = [Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()
if (-not $admin.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    Start-Process powershell.exe "-NoProfile -Sta -NoExit -ExecutionPolicy Bypass -File `"$PSCommandPath`"" -Verb RunAs
    exit
}

Add-Type -AssemblyName PresentationFramework
Add-Type -AssemblyName PresentationCore
Add-Type -AssemblyName WindowsBase
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
Add-Type -AssemblyName Microsoft.VisualBasic

$ErrorActionPreference = "Stop"
try {

$ScriptVersion = "2.3.0"
$AutoCleanMode = (@($args) | Where-Object { "$_" -match '^[-/]autoclean$' }).Count -gt 0
$GitHubRepo = "adventdevinc/SCPclear"

# ---------- ตรวจสเปก ----------
$ramGB = [math]::Round((Get-CimInstance Win32_ComputerSystem).TotalPhysicalMemory / 1GB)
$isHDD = $false
try {
    $sysLetter = ($env:SystemDrive).TrimEnd(':')
    $part = Get-Partition -DriveLetter $sysLetter -ErrorAction Stop
    $pd = Get-PhysicalDisk | Where-Object { $_.DeviceId -eq (Get-Disk -Number $part.DiskNumber).Number }
    if ($pd.MediaType -eq 'HDD' -or $pd.MediaType -eq 'Unspecified') { $isHDD = $true }
} catch { $isHDD = $true }
$diskType = if ($isHDD) { "HDD" } else { "SSD" }

# ---------- โฟลเดอร์โปรแกรม (รองรับทั้ง .ps1 และ .exe จาก ps2exe) ----------
$ScriptDir = $null
$SelfExe = $null   # path ของ .exe เมื่อรันจากไฟล์ที่คอมไพล์ด้วย ps2exe
if($PSScriptRoot){ $ScriptDir = $PSScriptRoot }
else {
    try{
        $exePath = [System.Diagnostics.Process]::GetCurrentProcess().MainModule.FileName
        if($exePath -notmatch '\\(powershell|pwsh|powershell_ise)\.exe$'){ $ScriptDir = Split-Path -Parent $exePath; $SelfExe = $exePath }
    }catch{}
    if(-not $ScriptDir){ $ScriptDir = if($PSCommandPath){ Split-Path -Parent $PSCommandPath } else { (Get-Location).Path } }
}
$SettingsPath  = Join-Path $ScriptDir "SCPclear-settings.json"
$HistoryPath   = Join-Path $ScriptDir "SCPclear-history.json"
$AutoCleanPath = Join-Path $ScriptDir "SCPclear-autoclean.json"
$AutoCleanLog  = Join-Path $ScriptDir "SCPclear-autoclean.log"
$TempRoot      = Join-Path $env:TEMP "SCPclear"

# ---------- ไฟล์ประกอบที่ฝังในตัวโปรแกรม (ฟอนต์ / PdfSharp / ไอคอน) ----------
# ข้อมูลด้านล่างสร้างอัตโนมัติตอน build: @{ 'path' = @(ขนาดไฟล์, 'base64 ของ gzip') }
$EmbeddedResources = [ordered]@{
    'Fonts\Sarabun-Regular.ttf' = @(90220, '')
    'Fonts\Sarabun-SemiBold.ttf' = @(90200, '')
    'Fonts\Sarabun-Bold.ttf' = @(89804, '')
    'Fonts\OFL.txt' = @(4387, '')
    'Lib\PdfSharp.dll' = @(535040, '')
    'Lib\PDFsharp-LICENSE.txt' = @(1133, '')
    'SCPclear.ico' = @(118213, '')
}
function Expand-EmbeddedResources {
    $dir = Join-Path $env:LOCALAPPDATA "SCPclear\res-$ScriptVersion"
    foreach($kv in $EmbeddedResources.GetEnumerator()){
        $target = Join-Path $dir $kv.Key
        $len = [long]$kv.Value[0]
        if((Test-Path -LiteralPath $target) -and (Get-Item -LiteralPath $target).Length -eq $len){ continue }
        $tmp = "$target.$PID.tmp"
        try{
            New-Item -ItemType Directory -Path (Split-Path $target) -Force | Out-Null
            $src = New-Object System.IO.MemoryStream(,[Convert]::FromBase64String($kv.Value[1]))
            $gz = New-Object System.IO.Compression.GZipStream($src, [System.IO.Compression.CompressionMode]::Decompress)
            $fs = [System.IO.File]::Create($tmp); $gz.CopyTo($fs); $fs.Close(); $gz.Close()
            Move-Item -LiteralPath $tmp -Destination $target -Force
        }catch{ Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue }
    }
    return $dir
}
$ResDir = $ScriptDir
if($EmbeddedResources){ try{ $ResDir = Expand-EmbeddedResources }catch{} }
function Find-Res($rel){
    $local = Join-Path $ScriptDir $rel
    if(Test-Path -LiteralPath $local){ return $local }
    return (Join-Path $ResDir $rel)
}
$IconPath     = Find-Res "SCPclear.ico"
$PdfSharpPath = Find-Res "Lib\PdfSharp.dll"
$FontDir      = Split-Path (Find-Res "Fonts\Sarabun-Regular.ttf")
if(Test-Path (Join-Path $FontDir "Sarabun-Regular.ttf")){
    $FontUriPath = ($FontDir -replace '\\','/') -replace ' ','%20'
    $FontFamilyValue = "file:///$FontUriPath/#Sarabun, Segoe UI"
} else {
    $FontFamilyValue = "Sarabun, Segoe UI"
}

