# ---------- Windows 11 chrome (มุมโค้ง + title bar เข้ม) ----------
try{
    Add-Type -Name DwmHelper -Namespace Win32 -MemberDefinition @'
[DllImport("dwmapi.dll")]
public static extern int DwmSetWindowAttribute(IntPtr hwnd, int attr, ref int attrValue, int attrSize);
'@ -ErrorAction SilentlyContinue
}catch{}
function Set-ModernChrome($winObj){
    $winObj.Add_SourceInitialized({
        try{
            $hwnd = (New-Object System.Windows.Interop.WindowInteropHelper($this)).Handle
            $corner = 2
            [void][Win32.DwmHelper]::DwmSetWindowAttribute($hwnd, 33, [ref]$corner, 4)
            if($isDark){ $darkFlag = 1; [void][Win32.DwmHelper]::DwmSetWindowAttribute($hwnd, 20, [ref]$darkFlag, 4) }
        }catch{}
    })
}

