if(-not ('Scp.Sys' -as [type])){
Add-Type -ReferencedAssemblies System.Drawing, System.Core -TypeDefinition @'
using System;
using System.IO;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using System.Diagnostics;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using System.Text.RegularExpressions;
using System.Drawing;
using System.Drawing.Imaging;

namespace Scp
{
    public static class Sys
    {
        [StructLayout(LayoutKind.Sequential)]
        struct FT { public uint Lo; public uint Hi; }
        [DllImport("kernel32.dll")]
        static extern bool GetSystemTimes(out FT idle, out FT kernel, out FT user);
        [StructLayout(LayoutKind.Sequential)]
        class MemStat
        {
            public uint dwLength; public uint dwMemoryLoad;
            public ulong ullTotalPhys; public ulong ullAvailPhys; public ulong ullTotalPageFile; public ulong ullAvailPageFile;
            public ulong ullTotalVirtual; public ulong ullAvailVirtual; public ulong ullAvailExtendedVirtual;
            public MemStat() { dwLength = (uint)Marshal.SizeOf(typeof(MemStat)); }
        }
        [DllImport("kernel32.dll")]
        static extern bool GlobalMemoryStatusEx([In, Out] MemStat m);
        [DllImport("kernel32.dll")]
        public static extern uint GetOEMCP();

        static ulong lastIdle, lastTotal;
        static ulong V(FT f) { return ((ulong)f.Hi << 32) | f.Lo; }

        public static double CpuPercent()
        {
            FT i, k, u;
            if (!GetSystemTimes(out i, out k, out u)) return 0;
            ulong idle = V(i), total = V(k) + V(u);
            ulong di = idle - lastIdle, dt = total - lastTotal;
            lastIdle = idle; lastTotal = total;
            if (dt == 0) return 0;
            return Math.Max(0, Math.Min(100, (1.0 - (double)di / dt) * 100.0));
        }

        // [ total bytes, used bytes, load % ]
        public static double[] Memory()
        {
            var m = new MemStat();
            GlobalMemoryStatusEx(m);
            return new double[] { m.ullTotalPhys, m.ullTotalPhys - m.ullAvailPhys, m.dwMemoryLoad };
        }

        public static string Size(double b)
        {
            string[] u = { "B", "KB", "MB", "GB", "TB" };
            int i = 0;
            while (b >= 1024 && i < u.Length - 1) { b /= 1024; i++; }
            return (i >= 2 ? b.ToString("0.0") : b.ToString("0")) + " " + u[i];
        }
    }

    public class DirNode
    {
        public string Name { get; set; }
        public string Path { get; set; }
        public long Size { get; set; }
        public long Files { get; set; }
        public bool IsFileGroup { get; set; }
        public List<DirNode> Children = new List<DirNode>();
        public long OwnBytes;
        public long OwnCount;
    }

    public class StorageScan
    {
        public volatile string Current = "";
        public long FilesScanned;
        public long BytesScanned;
        public volatile bool Cancel;
        public DirNode Root;

        public Task Start(string path)
        {
            return Task.Factory.StartNew(() => { Root = Walk(new DirectoryInfo(path)); }, TaskCreationOptions.LongRunning);
        }

        DirNode Walk(DirectoryInfo d)
        {
            var n = new DirNode();
            n.Name = d.Name; n.Path = d.FullName;
            if (Cancel) return n;
            Current = d.FullName;
            try
            {
                foreach (var fi in d.EnumerateFileSystemInfos())
                {
                    if (Cancel) break;
                    if ((fi.Attributes & FileAttributes.ReparsePoint) != 0) continue;
                    var di = fi as DirectoryInfo;
                    if (di != null)
                    {
                        var c = Walk(di);
                        n.Children.Add(c); n.Size += c.Size; n.Files += c.Files;
                    }
                    else
                    {
                        long len = ((FileInfo)fi).Length;
                        n.OwnBytes += len; n.OwnCount++; n.Size += len; n.Files++;
                        Interlocked.Increment(ref FilesScanned);
                        Interlocked.Add(ref BytesScanned, len);
                    }
                }
            }
            catch { }
            return n;
        }

        // ลูกของโฟลเดอร์ เรียงจากใหญ่ไปเล็ก (รวมกลุ่ม "ไฟล์ในโฟลเดอร์นี้")
        public static List<DirNode> Items(DirNode n, string ownLabel)
        {
            var list = new List<DirNode>(n.Children);
            if (n.OwnCount > 0)
            {
                var g = new DirNode();
                g.Name = ownLabel; g.Path = n.Path; g.Size = n.OwnBytes; g.Files = n.OwnCount; g.IsFileGroup = true;
                list.Add(g);
            }
            list.Sort((a, b) => b.Size.CompareTo(a.Size));
            return list;
        }
    }

    public class FileItem
    {
        public string Name { get; set; }
        public string Folder { get; set; }
        public string FullPath { get; set; }
        public long Size { get; set; }
        public string SizeText { get; set; }
        public DateTime Modified { get; set; }
        public string ModifiedText { get; set; }
        public string Ext { get; set; }
        public int Group { get; set; }
        public string GroupText { get; set; }
        public bool Keep { get; set; }
    }

    public class AppItem
    {
        public string Name { get; set; }
        public string Publisher { get; set; }
        public string Version { get; set; }
        public long SizeBytes { get; set; }
        public string SizeText { get; set; }
        public DateTime Date { get; set; }
        public string DateText { get; set; }
        public string Kind { get; set; }
        public string Uninstall { get; set; }
        public string QuietUninstall { get; set; }
        public string Location { get; set; }
        public string Package { get; set; }
    }

    // หาไฟล์ซ้ำ: จับกลุ่มตามขนาด -> hash บางส่วน -> hash ทั้งไฟล์ (MD5)
    public class DupScan
    {
        public volatile string Current = "";
        public volatile string Phase = "";
        public long Scanned;
        public long ToHash;
        public long Hashed;
        public long Wasted;
        public int Groups;
        public volatile bool Cancel;
        public List<FileItem> Results = new List<FileItem>();
        HashSet<string> skip = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        long min;
        bool skipSystem;

        void AddSkip(Environment.SpecialFolder f)
        {
            try { string p = Environment.GetFolderPath(f); if (!string.IsNullOrEmpty(p)) skip.Add(p.TrimEnd('\\')); } catch { }
        }

        public Task Start(string root, long minBytes, bool skipSys)
        {
            min = Math.Max(1, minBytes); skipSystem = skipSys;
            if (skipSys)
            {
                AddSkip(Environment.SpecialFolder.Windows);
                AddSkip(Environment.SpecialFolder.ProgramFiles);
                AddSkip(Environment.SpecialFolder.ProgramFilesX86);
                AddSkip(Environment.SpecialFolder.CommonApplicationData);
            }
            return Task.Factory.StartNew(() =>
            {
                var bySize = new Dictionary<long, List<FileInfo>>();
                Phase = "scan";
                Walk(new DirectoryInfo(root), bySize);
                var cands = new List<List<FileInfo>>();
                foreach (var l in bySize.Values) if (l.Count > 1) { cands.Add(l); ToHash += l.Count; }
                Phase = "hash";
                var groups = new List<List<FileInfo>>();
                foreach (var l in cands)
                {
                    if (Cancel) break;
                    foreach (var part in Split(l, true))
                    {
                        if (part.Count < 2) continue;
                        foreach (var full in Split(part, false)) if (full.Count > 1) groups.Add(full);
                    }
                }
                groups.Sort((a, b) => (b[0].Length * (b.Count - 1)).CompareTo(a[0].Length * (a.Count - 1)));
                var res = new List<FileItem>();
                int gid = 0;
                foreach (var g in groups)
                {
                    gid++;
                    g.Sort((a, b) => a.LastWriteTime.CompareTo(b.LastWriteTime));
                    Wasted += g[0].Length * (g.Count - 1);
                    string gt = "กลุ่ม " + gid + " (" + g.Count + " ไฟล์)";
                    for (int i = 0; i < g.Count; i++)
                    {
                        var f = g[i];
                        var it = new FileItem();
                        it.Name = f.Name; it.Folder = f.DirectoryName; it.FullPath = f.FullName; it.Size = f.Length;
                        it.SizeText = Sys.Size(f.Length); it.Modified = f.LastWriteTime; it.ModifiedText = f.LastWriteTime.ToString("dd/MM/yyyy HH:mm");
                        it.Ext = f.Extension.TrimStart('.').ToUpperInvariant();
                        it.Group = gid; it.GroupText = gt; it.Keep = (i == 0);
                        res.Add(it);
                    }
                }
                Groups = gid;
                Results = res;
                Phase = "done";
            }, TaskCreationOptions.LongRunning);
        }

        List<List<FileInfo>> Split(List<FileInfo> files, bool partial)
        {
            var d = new Dictionary<string, List<FileInfo>>();
            foreach (var f in files)
            {
                if (Cancel) break;
                Current = f.FullName;
                string h = Hash(f, partial);
                if (!partial) Interlocked.Increment(ref Hashed);
                if (h == null) continue;
                List<FileInfo> l;
                if (!d.TryGetValue(h, out l)) { l = new List<FileInfo>(); d[h] = l; }
                l.Add(f);
            }
            return new List<List<FileInfo>>(d.Values);
        }

        static string Hash(FileInfo f, bool partial)
        {
            try
            {
                using (var md5 = System.Security.Cryptography.MD5.Create())
                using (var s = new FileStream(f.FullName, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete, 1 << 16))
                {
                    byte[] h;
                    if (partial)
                    {
                        const int chunk = 65536;
                        var buf = new byte[chunk * 2];
                        int n = s.Read(buf, 0, chunk);
                        if (s.Length > chunk * 2) { s.Seek(-chunk, SeekOrigin.End); n += s.Read(buf, n, chunk); }
                        h = md5.ComputeHash(buf, 0, n);
                    }
                    else h = md5.ComputeHash(s);
                    return BitConverter.ToString(h);
                }
            }
            catch { return null; }
        }

        void Walk(DirectoryInfo d, Dictionary<long, List<FileInfo>> bySize)
        {
            if (Cancel) return;
            Current = d.FullName;
            try
            {
                foreach (var fi in d.EnumerateFileSystemInfos())
                {
                    if (Cancel) return;
                    if ((fi.Attributes & FileAttributes.ReparsePoint) != 0) continue;
                    var di = fi as DirectoryInfo;
                    if (di != null)
                    {
                        if (skip.Contains(di.FullName.TrimEnd('\\'))) continue;
                        string dn = di.Name;
                        if (skipSystem && (dn.Equals("$Recycle.Bin", StringComparison.OrdinalIgnoreCase) ||
                            dn.Equals("System Volume Information", StringComparison.OrdinalIgnoreCase) ||
                            dn.Equals("Recovery", StringComparison.OrdinalIgnoreCase) ||
                            dn.Equals("Config.Msi", StringComparison.OrdinalIgnoreCase) ||
                            dn.Equals("node_modules", StringComparison.OrdinalIgnoreCase) ||
                            dn.Equals(".git", StringComparison.OrdinalIgnoreCase))) continue;
                        Walk(di, bySize);
                        continue;
                    }
                    var f = (FileInfo)fi;
                    Interlocked.Increment(ref Scanned);
                    if (f.Length < min) continue;
                    if ((f.Attributes & FileAttributes.System) != 0) continue;
                    List<FileInfo> l;
                    if (!bySize.TryGetValue(f.Length, out l)) { l = new List<FileInfo>(); bySize[f.Length] = l; }
                    l.Add(f);
                }
            }
            catch { }
        }
    }

    // จัดวางสี่เหลี่ยมแบบ squarified treemap  คืนค่า [x, y, w, h] ต่อรายการ (values ต้องเรียงมากไปน้อย)
    public static class Treemap
    {
        public static double[] Layout(double[] values, double x, double y, double w, double h)
        {
            int n = values.Length;
            var r = new double[n * 4];
            double total = 0;
            foreach (var v in values) total += Math.Max(0, v);
            if (n == 0 || total <= 0 || w <= 0 || h <= 0) return r;
            var a = new double[n];
            for (int k = 0; k < n; k++) a[k] = Math.Max(0, values[k]) * w * h / total;
            int i = 0;
            while (i < n)
            {
                double side = Math.Min(w, h);
                int j = i; double sum = 0; double best = double.MaxValue;
                while (j < n)
                {
                    double ns = sum + a[j];
                    double worst = Worst(a, i, j + 1, ns, side);
                    if (j > i && worst > best) break;
                    best = worst; sum = ns; j++;
                }
                if (sum <= 0) { i = j; continue; }
                if (w >= h)
                {
                    double cw = sum / h, cy = y;
                    for (int k = i; k < j; k++) { double ch = a[k] / cw; r[4 * k] = x; r[4 * k + 1] = cy; r[4 * k + 2] = cw; r[4 * k + 3] = ch; cy += ch; }
                    x += cw; w -= cw;
                }
                else
                {
                    double rh = sum / w, cx = x;
                    for (int k = i; k < j; k++) { double kw = a[k] / rh; r[4 * k] = cx; r[4 * k + 1] = y; r[4 * k + 2] = kw; r[4 * k + 3] = rh; cx += kw; }
                    y += rh; h -= rh;
                }
                i = j;
            }
            return r;
        }

        static double Worst(double[] a, int s, int e, double sum, double side)
        {
            double mx = 0, mn = double.MaxValue;
            for (int k = s; k < e; k++) { if (a[k] > mx) mx = a[k]; if (a[k] < mn) mn = a[k]; }
            if (mn <= 0 || sum <= 0) return double.MaxValue;
            double s2 = side * side, sum2 = sum * sum;
            return Math.Max(s2 * mx / sum2, sum2 / (s2 * mn));
        }
    }

    public class LargeFileScan
    {
        public volatile string Current = "";
        public long Scanned;
        public volatile bool Cancel;
        public List<FileItem> Results = new List<FileItem>();
        HashSet<string> skip = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        long min;
        bool skipSystem;

        void AddSkip(Environment.SpecialFolder f)
        {
            try { string p = Environment.GetFolderPath(f); if (!string.IsNullOrEmpty(p)) skip.Add(p.TrimEnd('\\')); } catch { }
        }

        public Task Start(string root, long minBytes, bool skipSys, int maxResults)
        {
            min = minBytes; skipSystem = skipSys;
            if (skipSys)
            {
                AddSkip(Environment.SpecialFolder.Windows);
                AddSkip(Environment.SpecialFolder.ProgramFiles);
                AddSkip(Environment.SpecialFolder.ProgramFilesX86);
                AddSkip(Environment.SpecialFolder.CommonApplicationData);
            }
            return Task.Factory.StartNew(() =>
            {
                var all = new List<FileItem>();
                Walk(new DirectoryInfo(root), all);
                all.Sort((a, b) => b.Size.CompareTo(a.Size));
                if (all.Count > maxResults) all.RemoveRange(maxResults, all.Count - maxResults);
                Results = all;
            }, TaskCreationOptions.LongRunning);
        }

        void Walk(DirectoryInfo d, List<FileItem> all)
        {
            if (Cancel) return;
            Current = d.FullName;
            try
            {
                foreach (var fi in d.EnumerateFileSystemInfos())
                {
                    if (Cancel) return;
                    if ((fi.Attributes & FileAttributes.ReparsePoint) != 0) continue;
                    var di = fi as DirectoryInfo;
                    if (di != null)
                    {
                        if (skip.Contains(di.FullName.TrimEnd('\\'))) continue;
                        string dn = di.Name;
                        if (skipSystem && (dn.Equals("$Recycle.Bin", StringComparison.OrdinalIgnoreCase) ||
                            dn.Equals("System Volume Information", StringComparison.OrdinalIgnoreCase) ||
                            dn.Equals("Recovery", StringComparison.OrdinalIgnoreCase) ||
                            dn.Equals("Config.Msi", StringComparison.OrdinalIgnoreCase))) continue;
                        Walk(di, all);
                        continue;
                    }
                    var f = (FileInfo)fi;
                    Interlocked.Increment(ref Scanned);
                    if (f.Length < min) continue;
                    string ln = f.Name.ToLowerInvariant();
                    if (ln == "pagefile.sys" || ln == "hiberfil.sys" || ln == "swapfile.sys") continue;
                    var it = new FileItem();
                    it.Name = f.Name; it.Folder = f.DirectoryName; it.FullPath = f.FullName; it.Size = f.Length;
                    it.SizeText = Sys.Size(f.Length); it.Modified = f.LastWriteTime; it.ModifiedText = f.LastWriteTime.ToString("dd/MM/yyyy HH:mm");
                    it.Ext = f.Extension.TrimStart('.').ToUpperInvariant();
                    all.Add(it);
                }
            }
            catch { }
        }
    }

    // spec: "D|โฟลเดอร์" = ทุกไฟล์ในโฟลเดอร์ (รวมโฟลเดอร์ย่อย) | "F|โฟลเดอร์|pattern" = ไฟล์ที่ตรง pattern ชั้นเดียว
    public static class Cleaner
    {
        static void Collect(DirectoryInfo d, List<FileInfo> list)
        {
            try
            {
                foreach (var fi in d.EnumerateFileSystemInfos())
                {
                    if ((fi.Attributes & FileAttributes.ReparsePoint) != 0) continue;
                    var sub = fi as DirectoryInfo;
                    if (sub != null) Collect(sub, list); else list.Add((FileInfo)fi);
                }
            }
            catch { }
        }

        static List<FileInfo> Files(string spec)
        {
            var list = new List<FileInfo>();
            try
            {
                var p = spec.Split('|');
                var d = new DirectoryInfo(p[1]);
                if (!d.Exists) return list;
                if (p[0] == "D") Collect(d, list);
                else if (p[0] == "F") foreach (var f in d.EnumerateFiles(p[2])) list.Add(f);
            }
            catch { }
            return list;
        }

        static void RemoveEmptyDirs(DirectoryInfo d)
        {
            try
            {
                foreach (var sub in d.GetDirectories())
                {
                    if ((sub.Attributes & FileAttributes.ReparsePoint) != 0) continue;
                    RemoveEmptyDirs(sub);
                    try { if (sub.GetFileSystemInfos().Length == 0) sub.Delete(); } catch { }
                }
            }
            catch { }
        }

        // คืนค่า [bytes0, count0, bytes1, count1, ...]
        public static Task<long[]> Measure(string[][] targets)
        {
            return Task.Factory.StartNew(() =>
            {
                var r = new long[targets.Length * 2];
                for (int i = 0; i < targets.Length; i++)
                    foreach (var s in targets[i])
                        foreach (var f in Files(s)) { try { r[2 * i] += f.Length; r[2 * i + 1]++; } catch { } }
                return r;
            }, TaskCreationOptions.LongRunning);
        }

        // คืนค่า [freed0, failed0, freed1, failed1, ...]
        public static Task<long[]> Clean(string[][] targets)
        {
            return Task.Factory.StartNew(() =>
            {
                var r = new long[targets.Length * 2];
                for (int i = 0; i < targets.Length; i++)
                {
                    foreach (var s in targets[i])
                    {
                        foreach (var f in Files(s))
                        {
                            try
                            {
                                long len = f.Length;
                                if ((f.Attributes & FileAttributes.ReadOnly) != 0) f.Attributes = FileAttributes.Normal;
                                f.Delete();
                                r[2 * i] += len;
                            }
                            catch { r[2 * i + 1]++; }
                        }
                        if (s.StartsWith("D|")) RemoveEmptyDirs(new DirectoryInfo(s.Substring(2)));
                    }
                }
                return r;
            }, TaskCreationOptions.LongRunning);
        }
    }

    // รันคำสั่ง (sfc / DISM) แบบเบื้องหลัง พร้อมเก็บข้อความออกมาแสดงสด
    public class ProcRun
    {
        readonly StringBuilder sb = new StringBuilder();
        readonly object lk = new object();
        Process p;
        int lastStart = -1;
        bool lastProgress;
        public volatile bool Done;
        public int ExitCode = -1;
        static readonly Regex Pct = new Regex(@"\d+(\.\d+)?\s*%");

        public void Start(string file, string args, bool unicodeOutput)
        {
            StartCp(file, args, unicodeOutput ? 1200 : (int)Sys.GetOEMCP());
        }

        // codepage: 1200 = UTF-16, 65001 = UTF-8 (winget), อื่น ๆ = code page ของคอนโซล
        public void StartCp(string file, string args, int codepage)
        {
            var psi = new ProcessStartInfo(file, args);
            psi.UseShellExecute = false; psi.CreateNoWindow = true;
            psi.RedirectStandardOutput = true; psi.RedirectStandardError = true;
            Encoding enc = codepage == 65001 ? new UTF8Encoding(false) : Encoding.GetEncoding(codepage);
            psi.StandardOutputEncoding = enc; psi.StandardErrorEncoding = enc;
            p = new Process();
            p.StartInfo = psi; p.EnableRaisingEvents = true;
            p.OutputDataReceived += (s, e) => Add(e.Data);
            p.ErrorDataReceived += (s, e) => Add(e.Data);
            p.Exited += (s, e) => { try { p.WaitForExit(); ExitCode = p.ExitCode; } catch { } Done = true; };
            p.Start();
            p.BeginOutputReadLine(); p.BeginErrorReadLine();
        }

        void Add(string line)
        {
            if (line == null) return;
            line = line.Replace("\0", "").TrimEnd();
            if (line.Trim().Length <= 1) return;   // ข้ามบรรทัดว่าง / ตัวหมุน -\|/
            bool prog = line.Length < 140 && (Pct.IsMatch(line) || line.IndexOf('█') >= 0 || line.IndexOf('▒') >= 0);
            lock (lk)
            {
                if (prog && lastProgress && lastStart >= 0) sb.Length = lastStart;
                lastStart = sb.Length;
                sb.AppendLine(line);
                lastProgress = prog;
            }
        }

        public string Text { get { lock (lk) { return sb.ToString(); } } }
        public void Kill() { try { if (p != null && !p.HasExited) p.Kill(); } catch { } }
    }

    // ---------- อ่านไฟล์ minidump (จอฟ้า): รหัส error + ไดรเวอร์ที่เป็นตัวการ ----------
    public class DumpInfo
    {
        public string File { get; set; }
        public DateTime Time { get; set; }
        public uint Code { get; set; }
        public ulong P1 { get; set; }
        public ulong P2 { get; set; }
        public ulong P3 { get; set; }
        public ulong P4 { get; set; }
        public string Driver { get; set; }
    }

    public static class MiniDump
    {
        public static DumpInfo Read(string path)
        {
            var d = new DumpInfo();
            d.File = path; d.Driver = "";
            try { d.Time = System.IO.File.GetLastWriteTime(path); } catch { }
            try
            {
                var fi = new FileInfo(path);
                if (fi.Length > 64L * 1024 * 1024 || fi.Length < 0x2100) return d;
                byte[] b = System.IO.File.ReadAllBytes(path);
                if (Encoding.ASCII.GetString(b, 0, 8) != "PAGEDU64") return d;
                d.Code = BitConverter.ToUInt32(b, 0x38);
                d.P1 = BitConverter.ToUInt64(b, 0x40); d.P2 = BitConverter.ToUInt64(b, 0x48);
                d.P3 = BitConverter.ToUInt64(b, 0x50); d.P4 = BitConverter.ToUInt64(b, 0x58);
                int t = 0x2000;
                uint drvOff = BitConverter.ToUInt32(b, t + 0x30), cnt = BitConverter.ToUInt32(b, t + 0x34);
                uint spOff = BitConverter.ToUInt32(b, t + 0x38), spSize = BitConverter.ToUInt32(b, t + 0x3C);
                if (cnt == 0 || cnt > 4000 || drvOff >= b.Length || spOff >= b.Length) return d;
                int size = 0;
                for (int cand = 0x80; cand <= 0x200; cand += 8)
                {
                    bool ok = true;
                    for (int k = 0; k < Math.Min(6, (int)cnt); k++)
                    {
                        long pos = drvOff + (long)k * cand;
                        if (pos + 4 > b.Length) { ok = false; break; }
                        uint no = BitConverter.ToUInt32(b, (int)pos);
                        if (no < spOff || no >= spOff + spSize) { ok = false; break; }
                    }
                    if (ok) { size = cand; break; }
                }
                if (size == 0) return d;
                ulong[] addrs = { d.P4, d.P3, d.P2, d.P1 };
                string fallback = "";
                for (int k = 0; k < cnt; k++)
                {
                    long e = drvOff + (long)k * size;
                    if (e + 0x4C > b.Length) break;
                    uint no = BitConverter.ToUInt32(b, (int)e);
                    if (no + 4 > b.Length) continue;
                    int len = (int)Math.Min(BitConverter.ToUInt32(b, (int)no), 260);
                    if (no + 4 + 2 * len > b.Length) continue;
                    string name = Encoding.Unicode.GetString(b, (int)no + 4, 2 * len);
                    ulong bas = BitConverter.ToUInt64(b, (int)e + 0x38);
                    uint sz = BitConverter.ToUInt32(b, (int)e + 0x48);
                    foreach (var a in addrs)
                    {
                        if (a >= bas && a < bas + sz)
                        {
                            string ln = name.ToLowerInvariant();
                            if (ln == "ntoskrnl.exe" || ln == "hal.dll") { if (fallback == "") fallback = name; }
                            else { d.Driver = name; return d; }
                        }
                    }
                }
                d.Driver = fallback;
            }
            catch { }
            return d;
        }
    }

    // ---------- ทดสอบความเร็วดิสก์ (ไม่ผ่าน cache ของ Windows) ----------
    public class DiskBench
    {
        [DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
        static extern Microsoft.Win32.SafeHandles.SafeFileHandle CreateFile(string name, uint access, uint share, IntPtr sec, uint disp, uint flags, IntPtr tmpl);
        [DllImport("kernel32.dll", SetLastError = true)]
        static extern bool WriteFile(Microsoft.Win32.SafeHandles.SafeFileHandle h, IntPtr buf, uint n, out uint written, IntPtr ovl);
        [DllImport("kernel32.dll", SetLastError = true)]
        static extern bool ReadFile(Microsoft.Win32.SafeHandles.SafeFileHandle h, IntPtr buf, uint n, out uint read, IntPtr ovl);
        [DllImport("kernel32.dll", SetLastError = true)]
        static extern bool SetFilePointerEx(Microsoft.Win32.SafeHandles.SafeFileHandle h, long dist, out long newPos, uint method);
        [DllImport("kernel32.dll", SetLastError = true)]
        static extern IntPtr VirtualAlloc(IntPtr addr, UIntPtr size, uint type, uint protect);
        [DllImport("kernel32.dll", SetLastError = true)]
        static extern bool VirtualFree(IntPtr addr, UIntPtr size, uint type);

        const uint GR = 0x80000000, GW = 0x40000000, NOBUF = 0x20000000, WTHRU = 0x80000000;
        public volatile string Phase = "";
        public double Progress;
        public double SeqWrite, SeqRead, RandRead, RandIops;
        public volatile bool Cancel;

        static Microsoft.Win32.SafeHandles.SafeFileHandle Open(string path, uint access, uint disp, uint flags)
        {
            var h = CreateFile(path, access, 0, IntPtr.Zero, disp, flags, IntPtr.Zero);
            if (h.IsInvalid) throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());
            return h;
        }

        public Task Start(string dir, long sizeBytes)
        {
            return Task.Factory.StartNew(() =>
            {
                string path = Path.Combine(dir, "SCPclear-speedtest.tmp");
                const int block = 4 * 1024 * 1024;
                long size = (sizeBytes / block) * block;
                IntPtr buf = VirtualAlloc(IntPtr.Zero, (UIntPtr)block, 0x3000, 4);
                if (buf == IntPtr.Zero) throw new OutOfMemoryException();
                try
                {
                    var rnd = new Random();
                    var tmp = new byte[block]; rnd.NextBytes(tmp); Marshal.Copy(tmp, 0, buf, block);
                    uint n;
                    Phase = "write";
                    using (var h = Open(path, GW, 2, NOBUF | WTHRU))
                    {
                        var sw = Stopwatch.StartNew(); long done = 0;
                        while (done < size && !Cancel)
                        {
                            if (!WriteFile(h, buf, block, out n, IntPtr.Zero)) throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());
                            done += n; Progress = 0.4 * done / size;
                        }
                        SeqWrite = done / 1048576.0 / Math.Max(0.001, sw.Elapsed.TotalSeconds);
                    }
                    if (Cancel) return;
                    Phase = "read";
                    using (var h = Open(path, GR, 3, NOBUF))
                    {
                        var sw = Stopwatch.StartNew(); long done = 0;
                        while (done < size && !Cancel)
                        {
                            if (!ReadFile(h, buf, block, out n, IntPtr.Zero) || n == 0) break;
                            done += n; Progress = 0.4 + 0.4 * done / size;
                        }
                        SeqRead = done / 1048576.0 / Math.Max(0.001, sw.Elapsed.TotalSeconds);
                    }
                    if (Cancel) return;
                    Phase = "random";
                    using (var h = Open(path, GR, 3, NOBUF))
                    {
                        int blocks = (int)Math.Min(int.MaxValue, size / 4096);
                        var sw = Stopwatch.StartNew(); long ops = 0; long np;
                        while (sw.Elapsed.TotalSeconds < 6 && !Cancel)
                        {
                            long off = (long)rnd.Next(blocks) * 4096;
                            SetFilePointerEx(h, off, out np, 0);
                            if (!ReadFile(h, buf, 4096, out n, IntPtr.Zero)) break;
                            ops++; Progress = 0.8 + 0.2 * Math.Min(1, sw.Elapsed.TotalSeconds / 6);
                        }
                        double sec = Math.Max(0.001, sw.Elapsed.TotalSeconds);
                        RandIops = ops / sec; RandRead = ops * 4096 / 1048576.0 / sec;
                    }
                    Progress = 1; Phase = "done";
                }
                finally
                {
                    VirtualFree(buf, UIntPtr.Zero, 0x8000);
                    try { System.IO.File.Delete(path); } catch { }
                }
            }, TaskCreationOptions.LongRunning);
        }
    }

    // ---------- ทดสอบ CPU ให้ทำงานเต็มทุกคอร์ ----------
    public class CpuStress
    {
        public volatile bool Stop;
        Thread[] ts;
        public static double Sink;
        public void Start(int seconds)
        {
            Stop = false;
            int n = Environment.ProcessorCount;
            ts = new Thread[n];
            DateTime end = DateTime.UtcNow.AddSeconds(seconds);
            for (int i = 0; i < n; i++)
            {
                ts[i] = new Thread(() =>
                {
                    double x = 1.0001;
                    while (!Stop && DateTime.UtcNow < end)
                    {
                        for (int k = 0; k < 200000; k++) { x = Math.Sqrt(x * x + k) * 1.0000001; if (x > 1e12) x = 1.0001; }
                    }
                    Sink = x;
                });
                ts[i].IsBackground = true; ts[i].Priority = ThreadPriority.BelowNormal;
                ts[i].Start();
            }
        }
        public bool Running
        {
            get { if (ts == null) return false; foreach (var t in ts) if (t.IsAlive) return true; return false; }
        }
    }

    // ---------- สแกนอุปกรณ์ในวง LAN ----------
    public class LanHost
    {
        public string IP { get; set; }
        public string Name { get; set; }
        public string MAC { get; set; }
        public string Kind { get; set; }
        public string Ports { get; set; }
        public long Ms { get; set; }
        public string MsText { get; set; }
        public int Sort { get; set; }
    }

    public class LanScan
    {
        public int Done;
        public int Total;
        public volatile bool Cancel;
        public volatile string Phase = "";
        public List<LanHost> Results = new List<LanHost>();
        static readonly int[] PortList = { 80, 443, 9100, 631, 515, 554, 445, 3389, 22 };

        public Task Start(string prefix3, string selfIp, string gateway, string selfMac)
        {
            return Task.Factory.StartNew(() =>
            {
                var hosts = new System.Collections.Concurrent.ConcurrentDictionary<string, LanHost>();
                var ips = new List<string>();
                for (int i = 1; i < 255; i++) ips.Add(prefix3 + "." + i);
                Total = ips.Count; Done = 0; Phase = "ping";
                var po = new ParallelOptions(); po.MaxDegreeOfParallelism = 64;
                Parallel.ForEach(ips, po, ip =>
                {
                    if (Cancel) return;
                    try
                    {
                        using (var p = new System.Net.NetworkInformation.Ping())
                        {
                            var r = p.Send(ip, 700);
                            if (r.Status == System.Net.NetworkInformation.IPStatus.Success)
                            {
                                var h = new LanHost(); h.IP = ip; h.Ms = r.RoundtripTime; hosts[ip] = h;
                            }
                        }
                    }
                    catch { }
                    Interlocked.Increment(ref Done);
                });
                Phase = "arp";
                foreach (var kv in ReadArp())
                {
                    if (!kv.Key.StartsWith(prefix3 + ".")) continue;
                    string mac = kv.Value.ToUpperInvariant();
                    if (mac.StartsWith("FF-FF") || mac.StartsWith("01-00-5E") || mac == "00-00-00-00-00-00") continue;
                    LanHost h;
                    if (!hosts.TryGetValue(kv.Key, out h)) { h = new LanHost(); h.IP = kv.Key; h.Ms = -1; hosts[kv.Key] = h; }
                    h.MAC = mac;
                }
                if (hosts.ContainsKey(selfIp)) hosts[selfIp].MAC = selfMac;
                var list = new List<LanHost>(hosts.Values);
                Phase = "probe"; Done = 0; Total = list.Count;
                Parallel.ForEach(list, po, h =>
                {
                    if (Cancel) return;
                    h.Ports = Probe(h.IP);
                    h.Name = Resolve(h.IP);
                    h.Kind = Classify(h, selfIp, gateway);
                    h.MsText = h.Ms >= 0 ? (h.Ms + " ms") : "ไม่ตอบ ping";
                    if (h.MAC == null) h.MAC = "";
                    int last; int.TryParse(h.IP.Substring(h.IP.LastIndexOf('.') + 1), out last); h.Sort = last;
                    Interlocked.Increment(ref Done);
                });
                list.Sort((a, b) => a.Sort.CompareTo(b.Sort));
                Results = list; Phase = "done";
            }, TaskCreationOptions.LongRunning);
        }

        static string Probe(string ip)
        {
            var open = new List<string>();
            foreach (int port in PortList)
            {
                try
                {
                    using (var c = new System.Net.Sockets.TcpClient())
                    {
                        var ar = c.BeginConnect(ip, port, null, null);
                        if (ar.AsyncWaitHandle.WaitOne(250) && c.Connected) open.Add(port.ToString());
                    }
                }
                catch { }
            }
            return string.Join(", ", open.ToArray());
        }

        static string Resolve(string ip)
        {
            try
            {
                var t = System.Net.Dns.GetHostEntryAsync(ip);
                if (t.Wait(900) && t.Result.HostName != ip) return t.Result.HostName;
            }
            catch { }
            return "";
        }

        static string Classify(LanHost h, string selfIp, string gateway)
        {
            var p = "," + (h.Ports ?? "").Replace(" ", "") + ",";
            if (h.IP == selfIp) return "เครื่องนี้";
            if (h.IP == gateway) return "เราเตอร์ (Gateway)";
            if (p.Contains(",9100,") || p.Contains(",631,") || p.Contains(",515,")) return "เครื่องพิมพ์";
            if (p.Contains(",554,")) return "กล้อง / เครื่องบันทึก";
            if (p.Contains(",3389,") || p.Contains(",445,")) return "คอมพิวเตอร์ Windows";
            if (p.Contains(",22,")) return "Linux / NAS / อุปกรณ์เครือข่าย";
            if (p.Contains(",80,") || p.Contains(",443,")) return "อุปกรณ์มีหน้าเว็บ";
            if (!string.IsNullOrEmpty(h.MAC) && h.MAC.Length > 1 && "26AE".IndexOf(h.MAC[1]) >= 0) return "มือถือ / แท็บเล็ต (MAC สุ่ม)";
            return "อุปกรณ์ทั่วไป";
        }

        static Dictionary<string, string> ReadArp()
        {
            var d = new Dictionary<string, string>();
            try
            {
                var psi = new ProcessStartInfo("arp.exe", "-a");
                psi.UseShellExecute = false; psi.CreateNoWindow = true; psi.RedirectStandardOutput = true;
                using (var pr = Process.Start(psi))
                {
                    string all = pr.StandardOutput.ReadToEnd(); pr.WaitForExit(5000);
                    foreach (Match m in Regex.Matches(all, @"(\d+\.\d+\.\d+\.\d+)\s+([0-9a-fA-F]{2}(?:-[0-9a-fA-F]{2}){5})"))
                        d[m.Groups[1].Value] = m.Groups[2].Value;
                }
            }
            catch { }
            return d;
        }
    }

    // ---------- คัดลอกไฟล์สำหรับสำรอง/กู้คืนข้อมูล (นับความคืบหน้าได้) ----------
    public class BackupCopier
    {
        public long CopiedBytes;
        public int Files;
        public int Failed;
        public volatile string Current = "";
        public volatile bool Cancel;
        public List<string> Errors = new List<string>();
        bool keepNewer;

        // keepNewerTarget = true: ถ้าไฟล์ปลายทางใหม่กว่า จะไม่เขียนทับ (ใช้ตอนกู้คืน)
        public Task Start(string[] sources, string[] targets, bool keepNewerTarget)
        {
            keepNewer = keepNewerTarget;
            return Task.Factory.StartNew(() =>
            {
                for (int i = 0; i < sources.Length && !Cancel; i++)
                {
                    try
                    {
                        if (System.IO.File.Exists(sources[i]))
                        {
                            Directory.CreateDirectory(Path.GetDirectoryName(targets[i]));
                            CopyOne(new FileInfo(sources[i]), targets[i]);
                        }
                        else if (Directory.Exists(sources[i])) CopyDir(new DirectoryInfo(sources[i]), targets[i]);
                    }
                    catch (Exception ex) { Note(sources[i] + ": " + ex.Message); }
                }
            }, TaskCreationOptions.LongRunning);
        }

        void Note(string s) { lock (Errors) { if (Errors.Count < 1000) Errors.Add(s); } }

        void CopyDir(DirectoryInfo s, string dst)
        {
            if (Cancel) return;
            try { Directory.CreateDirectory(dst); } catch (Exception ex) { Note(dst + ": " + ex.Message); return; }
            try
            {
                foreach (var fi in s.EnumerateFileSystemInfos())
                {
                    if (Cancel) return;
                    if ((fi.Attributes & FileAttributes.ReparsePoint) != 0) continue;
                    var sub = fi as DirectoryInfo;
                    if (sub != null) CopyDir(sub, Path.Combine(dst, sub.Name));
                    else CopyOne((FileInfo)fi, Path.Combine(dst, fi.Name));
                }
            }
            catch (Exception ex) { Note(s.FullName + ": " + ex.Message); }
        }

        void CopyOne(FileInfo f, string dst)
        {
            Current = f.FullName;
            try
            {
                long len = f.Length;
                if (System.IO.File.Exists(dst))
                {
                    var t = new FileInfo(dst);
                    bool same = t.Length == len && t.LastWriteTimeUtc == f.LastWriteTimeUtc;
                    if (same || (keepNewer && t.LastWriteTimeUtc > f.LastWriteTimeUtc)) { CopiedBytes += len; Files++; return; }
                    if ((t.Attributes & FileAttributes.ReadOnly) != 0) t.Attributes = FileAttributes.Normal;
                }
                System.IO.File.Copy(f.FullName, dst, true);
                CopiedBytes += len; Files++;
            }
            catch (Exception ex) { Failed++; Note(f.FullName + ": " + ex.Message); }
        }
    }

    public static class Img
    {
        // บันทึกภาพจาก PNG bytes เป็น png/jpg  คืนค่า [กว้าง, สูง]
        public static int[] Save(byte[] data, string outPath, string fmt, long quality)
        {
            using (var ms = new MemoryStream(data))
            using (var src = Image.FromStream(ms))
            {
                if (fmt == "png") { File.WriteAllBytes(outPath, data); return new int[] { src.Width, src.Height }; }
                using (var bmp = new Bitmap(src.Width, src.Height))
                {
                    using (var g = Graphics.FromImage(bmp)) { g.Clear(Color.White); g.DrawImage(src, 0, 0, src.Width, src.Height); }
                    ImageCodecInfo enc = null;
                    foreach (var c in ImageCodecInfo.GetImageEncoders()) if (c.MimeType == "image/jpeg") enc = c;
                    var ep = new EncoderParameters(1);
                    ep.Param[0] = new EncoderParameter(System.Drawing.Imaging.Encoder.Quality, quality);
                    bmp.Save(outPath, enc, ep);
                }
                return new int[] { src.Width, src.Height };
            }
        }
    }
}
'@
}

# ---------- PDF (ต้องมี Lib\PdfSharp.dll) ----------
$PdfReady = $false
if(Test-Path $PdfSharpPath){
  try{
    Add-Type -Path $PdfSharpPath
    if(-not ('Scp.Pdf' -as [type])){
    Add-Type -ReferencedAssemblies $PdfSharpPath, System.Drawing, System.Core -TypeDefinition @'
using System;
using System.IO;
using System.Threading.Tasks;
using System.Drawing;
using PdfSharp.Pdf;
using PdfSharp.Pdf.IO;
using PdfSharp.Drawing;

namespace Scp
{
    public static class Pdf
    {
        static PdfDocument Imp(string f) { return PdfReader.Open(f, PdfDocumentOpenMode.Import); }

        public static int PageCount(string f) { return Imp(f).PageCount; }

        public static Task<int> Merge(string[] files, string outPath)
        {
            return Task.Factory.StartNew(() =>
            {
                var o = new PdfDocument();
                foreach (var f in files)
                {
                    var s = Imp(f);
                    for (int i = 0; i < s.PageCount; i++) o.AddPage(s.Pages[i]);
                }
                o.Save(outPath);
                return o.PageCount;
            });
        }

        // groups = กลุ่มของเลขหน้า (เริ่ม 0) แต่ละกลุ่มได้ 1 ไฟล์
        public static Task<int> Split(string file, string outDir, string baseName, int[][] groups)
        {
            return Task.Factory.StartNew(() =>
            {
                var s = Imp(file);
                int k = 0;
                foreach (var g in groups)
                {
                    if (g.Length == 0) continue;
                    var o = new PdfDocument();
                    foreach (var idx in g) o.AddPage(s.Pages[idx]);
                    string name = baseName + "_p" + (g[0] + 1) + (g.Length > 1 ? "-" + (g[g.Length - 1] + 1) : "");
                    o.Save(Path.Combine(outDir, name + ".pdf"));
                    k++;
                }
                return k;
            });
        }

        // order = ลำดับหน้าใหม่ (เลขหน้าเดิม เริ่ม 0), rot = องศาที่หมุนเพิ่มของแต่ละหน้า
        public static Task<int> Organize(string file, string outPath, int[] order, int[] rot)
        {
            return Task.Factory.StartNew(() =>
            {
                var s = Imp(file);
                var o = new PdfDocument();
                for (int i = 0; i < order.Length; i++)
                {
                    var p = o.AddPage(s.Pages[order[i]]);
                    if (rot[i] != 0) p.Rotate = (((p.Rotate + rot[i]) % 360) + 360) % 360;
                }
                o.Save(outPath);
                return o.PageCount;
            });
        }

        static bool FixOrientation(Image img)
        {
            const int id = 0x0112;
            if (Array.IndexOf(img.PropertyIdList, id) < 0) return false;
            int v = img.GetPropertyItem(id).Value[0];
            RotateFlipType t;
            switch (v)
            {
                case 2: t = RotateFlipType.RotateNoneFlipX; break;
                case 3: t = RotateFlipType.Rotate180FlipNone; break;
                case 4: t = RotateFlipType.Rotate180FlipX; break;
                case 5: t = RotateFlipType.Rotate90FlipX; break;
                case 6: t = RotateFlipType.Rotate90FlipNone; break;
                case 7: t = RotateFlipType.Rotate270FlipX; break;
                case 8: t = RotateFlipType.Rotate270FlipNone; break;
                default: return false;
            }
            img.RotateFlip(t);
            img.RemovePropertyItem(id);
            return true;
        }

        static double Res(float r) { return r < 30 ? 96.0 : r; }

        // รวมรูปเป็น PDF: a4 = จัดลงหน้า A4 (หมุนแนวตามรูป), ไม่งั้นหน้าเท่าขนาดรูป
        public static Task<int> ImagesToPdf(string[] images, string outPath, bool a4)
        {
            return Task.Factory.StartNew(() =>
            {
                var o = new PdfDocument();
                var keep = new System.Collections.Generic.List<IDisposable>();
                foreach (var path in images)
                {
                    using (var gdi = Image.FromFile(path))
                    {
                        bool rotated = FixOrientation(gdi);
                        double wPt = gdi.Width * 72.0 / Res(gdi.HorizontalResolution);
                        double hPt = gdi.Height * 72.0 / Res(gdi.VerticalResolution);
                        XImage xi;
                        if (rotated)
                        {
                            var ms = new MemoryStream();
                            bool isJpg = gdi.RawFormat.Guid == System.Drawing.Imaging.ImageFormat.Jpeg.Guid;
                            gdi.Save(ms, isJpg ? System.Drawing.Imaging.ImageFormat.Jpeg : System.Drawing.Imaging.ImageFormat.Png);
                            ms.Position = 0; keep.Add(ms);
                            xi = XImage.FromStream(ms);
                        }
                        else xi = XImage.FromFile(path);
                        keep.Add(xi);
                        {
                            var page = o.AddPage();
                            if (a4)
                            {
                                double pw = 595.276, ph = 841.89, m = 24;
                                if (wPt > hPt) { double t = pw; pw = ph; ph = t; }
                                page.Width = XUnit.FromPoint(pw); page.Height = XUnit.FromPoint(ph);
                                double sc = Math.Min((pw - 2 * m) / wPt, (ph - 2 * m) / hPt);
                                double dw = wPt * sc, dh = hPt * sc;
                                using (var g = XGraphics.FromPdfPage(page)) g.DrawImage(xi, (pw - dw) / 2, (ph - dh) / 2, dw, dh);
                            }
                            else
                            {
                                double sc = 1;
                                if (Math.Max(wPt, hPt) > 14000) sc = 14000 / Math.Max(wPt, hPt);
                                if (Math.Max(wPt, hPt) < 200) sc = 200 / Math.Max(wPt, hPt);
                                page.Width = XUnit.FromPoint(wPt * sc); page.Height = XUnit.FromPoint(hPt * sc);
                                using (var g = XGraphics.FromPdfPage(page)) g.DrawImage(xi, 0, 0, wPt * sc, hPt * sc);
                            }
                        }
                    }
                }
                o.Save(outPath);
                foreach (var d in keep) { try { d.Dispose(); } catch { } }
                return o.PageCount;
            });
        }

        // บีบอัดแบบไม่ลดคุณภาพ (บีบ content stream ใหม่)
        public static Task<long> CompressLossless(string file, string outPath)
        {
            return Task.Factory.StartNew(() =>
            {
                var d = PdfReader.Open(file, PdfDocumentOpenMode.Modify);
                d.Options.NoCompression = false;
                d.Options.CompressContentStreams = true;
                d.Options.FlateEncodeMode = PdfFlateEncodeMode.BestCompression;
                d.Save(outPath);
                return new FileInfo(outPath).Length;
            });
        }

        // สร้าง PDF จากภาพ JPG ที่เรนเดอร์ไว้ (ใช้กับโหมดลดขนาดมาก) ขนาดหน้า = พิกเซล * 72 / dpi
        public static long BuildFromImages(string[] images, double dpi, string outPath)
        {
            var o = new PdfDocument();
            foreach (var path in images)
            {
                using (XImage xi = XImage.FromFile(path))
                {
                    var page = o.AddPage();
                    double w = xi.PixelWidth * 72.0 / dpi, h = xi.PixelHeight * 72.0 / dpi;
                    page.Width = XUnit.FromPoint(w); page.Height = XUnit.FromPoint(h);
                    using (var g = XGraphics.FromPdfPage(page)) g.DrawImage(xi, 0, 0, w, h);
                }
            }
            o.Save(outPath);
            return new FileInfo(outPath).Length;
        }

        // ---------- ใส่ / ปลดรหัสผ่าน ----------
        public static bool IsProtected(string f)
        {
            try { PdfReader.Open(f, PdfDocumentOpenMode.InformationOnly); return false; }
            catch (Exception ex) { string m = ex.Message.ToLowerInvariant(); return m.Contains("password") || m.Contains("encrypt"); }
        }

        public static Task<int> Protect(string file, string outPath, string userPw, bool allowPrint, bool allowCopy)
        {
            return Task.Factory.StartNew(() =>
            {
                var d = PdfReader.Open(file, PdfDocumentOpenMode.Modify);
                var s = d.SecuritySettings;
                s.DocumentSecurityLevel = PdfSharp.Pdf.Security.PdfDocumentSecurityLevel.Encrypted128Bit;
                s.UserPassword = userPw;
                s.OwnerPassword = userPw + "\u0001scp";
                s.PermitPrint = allowPrint; s.PermitFullQualityPrint = allowPrint;
                s.PermitExtractContent = allowCopy; s.PermitAccessibilityExtractContent = true;
                s.PermitModifyDocument = false; s.PermitAnnotations = false; s.PermitAssembleDocument = false; s.PermitFormsFill = true;
                d.Save(outPath);
                return d.PageCount;
            });
        }

        public static Task<int> Unprotect(string file, string outPath, string pw)
        {
            return Task.Factory.StartNew(() =>
            {
                PdfDocument d;
                try { d = PdfReader.Open(file, pw + "\u0001scp", PdfDocumentOpenMode.Modify); }
                catch { d = PdfReader.Open(file, pw, PdfDocumentOpenMode.Modify); }
                d.SecuritySettings.DocumentSecurityLevel = PdfSharp.Pdf.Security.PdfDocumentSecurityLevel.None;
                d.Save(outPath);
                return d.PageCount;
            });
        }

        // ---------- วาดบนหน้าตามมุมที่ผู้ใช้มองเห็น (รองรับหน้าที่หมุน /Rotate) ----------
        static XGraphics Visual(PdfPage p, out double vw, out double vh)
        {
            int rot = ((p.Rotate % 360) + 360) % 360;
            double w = p.MediaBox.Width, h = p.MediaBox.Height;
            double off = h - p.Height.Point;   // PDFsharp พลิกแกน y ด้วยความสูงที่สลับแล้วในหน้าแนวนอน
            var g = XGraphics.FromPdfPage(p, XGraphicsPdfPageOptions.Append);
            vw = w; vh = h;
            if (rot == 90)  { g.MultiplyTransform(new XMatrix(0, -1, 1, 0, 0, h - off)); vw = h; vh = w; }
            if (rot == 180) { g.MultiplyTransform(new XMatrix(-1, 0, 0, -1, w, h - off)); }
            if (rot == 270) { g.MultiplyTransform(new XMatrix(0, 1, -1, 0, w, -off)); vw = h; vh = w; }
            return g;
        }

        static XFont ThaiFont(double size, XFontStyle style)
        {
            var opt = new XPdfFontOptions(PdfFontEncoding.Unicode);
            foreach (var fam in new string[] { "Leelawadee UI", "Leelawadee", "Tahoma" })
            {
                try { using (new System.Drawing.FontFamily(fam)) { } return new XFont(fam, size, style, opt); } catch { }
            }
            return new XFont("Arial", size, style, opt);
        }

        // ลายน้ำ: ข้อความกลางหน้า (ทแยงหรือแนวนอน) ความทึบ 0-1
        public static Task<int> Watermark(string file, string outPath, string text, double opacity, bool diagonal, int r, int gr, int b)
        {
            return Task.Factory.StartNew(() =>
            {
                var d = PdfReader.Open(file, PdfDocumentOpenMode.Modify);
                var brush = new XSolidBrush(XColor.FromArgb((int)(Math.Max(0.05, Math.Min(1, opacity)) * 255), r, gr, b));
                foreach (PdfPage p in d.Pages)
                {
                    double vw, vh;
                    using (var g = Visual(p, out vw, out vh))
                    {
                        double angle = diagonal ? -Math.Atan2(vh, vw) * 180 / Math.PI : 0;
                        double avail = diagonal ? Math.Sqrt(vw * vw + vh * vh) * 0.7 : vw * 0.8;
                        var probe = ThaiFont(100, XFontStyle.Bold);
                        double tw = g.MeasureString(text, probe).Width;
                        double size = Math.Max(10, Math.Min(150, 100 * avail / Math.Max(1, tw)));
                        var font = ThaiFont(size, XFontStyle.Bold);
                        g.TranslateTransform(vw / 2, vh / 2);
                        g.RotateTransform(angle);
                        g.DrawString(text, font, brush, new XRect(-vw, -size, vw * 2, size * 2), XStringFormats.Center);
                    }
                }
                d.Save(outPath);
                return d.PageCount;
            });
        }

        // เลขหน้า: position 0=ล่างกลาง 1=ล่างขวา 2=บนขวา, pattern ใช้ {n} และ {total}
        public static Task<int> PageNumbers(string file, string outPath, int position, string pattern, int start, bool skipFirst, double fontSize)
        {
            return Task.Factory.StartNew(() =>
            {
                var d = PdfReader.Open(file, PdfDocumentOpenMode.Modify);
                int numbered = d.PageCount - (skipFirst ? 1 : 0);
                int total = numbered + start - 1;
                var font = ThaiFont(fontSize, XFontStyle.Regular);
                int k = 0;
                for (int i = 0; i < d.PageCount; i++)
                {
                    if (skipFirst && i == 0) continue;
                    string s = pattern.Replace("{n}", (start + k).ToString()).Replace("{total}", total.ToString());
                    k++;
                    double vw, vh;
                    using (var g = Visual(d.Pages[i], out vw, out vh))
                    {
                        double m = 28, bh = fontSize * 1.6;
                        XRect rect; XStringFormat fmt;
                        if (position == 1) { rect = new XRect(m, vh - m - bh, vw - 2 * m, bh); fmt = XStringFormats.CenterRight; }
                        else if (position == 2) { rect = new XRect(m, m, vw - 2 * m, bh); fmt = XStringFormats.CenterRight; }
                        else { rect = new XRect(m, vh - m - bh, vw - 2 * m, bh); fmt = XStringFormats.Center; }
                        g.DrawString(s, font, XBrushes.Black, rect, fmt);
                    }
                }
                d.Save(outPath);
                return d.PageCount;
            });
        }
    }
}
'@
    }
    $PdfReady = $true
  }catch{ $PdfReady = $false; $PdfLoadError = $_.Exception.Message }
}

# ---------- เรนเดอร์หน้า PDF เป็นภาพ (ใช้ Windows.Data.Pdf ในตัว Windows 10/11) ----------
# ฟังก์ชันนี้ถูกส่งไปรันใน runspace เบื้องหลัง
function Invoke-PdfRender {
    param($Sync, [string]$Path, [string]$OutDir, [string]$Prefix, [int]$Dpi, [int]$Width, [string]$Fmt, [long]$Quality, $Pages)
    $Path = [System.IO.Path]::GetFullPath($Path); $OutDir = [System.IO.Path]::GetFullPath($OutDir)
    Add-Type -AssemblyName System.Runtime.WindowsRuntime
    $m = [System.WindowsRuntimeSystemExtensions].GetMethods()
    $asOp  = ($m | Where-Object { $_.Name -eq 'AsTask' -and $_.GetParameters().Count -eq 1 -and $_.GetParameters()[0].ParameterType.Name -eq 'IAsyncOperation`1' })[0]
    $asAct = ($m | Where-Object { $_.Name -eq 'AsTask' -and $_.GetParameters().Count -eq 1 -and $_.GetParameters()[0].ParameterType.Name -eq 'IAsyncAction' })[0]
    $null = [Windows.Storage.StorageFile,Windows.Storage,ContentType=WindowsRuntime]
    $null = [Windows.Data.Pdf.PdfDocument,Windows.Data.Pdf,ContentType=WindowsRuntime]
    $null = [Windows.Storage.Streams.InMemoryRandomAccessStream,Windows.Storage.Streams,ContentType=WindowsRuntime]
    $t = $asOp.MakeGenericMethod([Windows.Storage.StorageFile]).Invoke($null, @([Windows.Storage.StorageFile]::GetFileFromPathAsync($Path)))
    $t.Wait(-1) | Out-Null; $sf = $t.Result
    $t = $asOp.MakeGenericMethod([Windows.Data.Pdf.PdfDocument]).Invoke($null, @([Windows.Data.Pdf.PdfDocument]::LoadFromFileAsync($sf)))
    $t.Wait(-1) | Out-Null; $doc = $t.Result
    $n = [int]$doc.PageCount
    if(-not $Pages){ $Pages = 0..($n-1) }
    if(-not (Test-Path $OutDir)){ New-Item -ItemType Directory -Path $OutDir -Force | Out-Null }
    $ext = if($Fmt -eq 'png'){ 'png' } else { 'jpg' }
    $digits = ([string]$n).Length
    $out = New-Object System.Collections.Generic.List[string]
    $k = 0
    foreach($i in $Pages){
        if($Sync.Cancel){ break }
        $k++; $Sync.Status = "$k/$(@($Pages).Count)"
        $page = $doc.GetPage([uint32]$i)
        $opt = New-Object Windows.Data.Pdf.PdfPageRenderOptions
        if($Width -gt 0){ $opt.DestinationWidth = [uint32]$Width }
        else { $opt.DestinationWidth = [uint32][math]::Max(1, [math]::Round($page.Size.Width * $Dpi / 96)) }
        $ms = New-Object Windows.Storage.Streams.InMemoryRandomAccessStream
        $a = $asAct.Invoke($null, @($page.RenderToStreamAsync($ms, $opt))); $a.Wait(-1) | Out-Null
        $ns = [System.IO.WindowsRuntimeStreamExtensions]::AsStreamForRead($ms.GetInputStreamAt(0))
        $buf = New-Object System.IO.MemoryStream
        $ns.CopyTo($buf); $ns.Dispose(); $ms.Dispose(); $page.Dispose()
        $file = Join-Path $OutDir ("{0}{1}.{2}" -f $Prefix, ([string]($i+1)).PadLeft($digits,'0'), $ext)
        [void][Scp.Img]::Save($buf.ToArray(), $file, $Fmt, $Quality)
        $out.Add($file)
    }
    $doc = $null
    return $out.ToArray()
}

# ============================================================
#   รายการไฟล์ขยะ (ใช้ทั้งหน้า Smart Cleanup และโหมดล้างอัตโนมัติ)
# ============================================================
function Get-CleanTargets {
    $L = $env:LOCALAPPDATA; $W = $env:SystemRoot
    $t = New-Object System.Collections.Generic.List[object]
    $t.Add(@{ Key='utemp'; Name='ไฟล์ชั่วคราวของผู้ใช้ (Temp)'; Desc='ไฟล์ที่โปรแกรมสร้างทิ้งไว้ — ปลอดภัย ไฟล์ที่กำลังใช้งานจะถูกข้ามให้อัตโนมัติ'; Specs=@("D|$env:TEMP"); Def=$true; Open=$env:TEMP })
    $t.Add(@{ Key='wtemp'; Name='ไฟล์ชั่วคราวของ Windows'; Desc="โฟลเดอร์ $W\Temp — ปลอดภัย"; Specs=@("D|$W\Temp"); Def=$true; Open="$W\Temp" })
    $t.Add(@{ Key='wu'; Name='ไฟล์ดาวน์โหลด Windows Update'; Desc='ไฟล์อัปเดตที่ติดตั้งเสร็จแล้ว — ปลอดภัย (ระบบจะหยุดบริการ Update ชั่วคราวระหว่างลบ)'; Specs=@("D|$W\SoftwareDistribution\Download"); Def=$true; Open="$W\SoftwareDistribution\Download" })
    $doPath = "$W\ServiceProfiles\NetworkService\AppData\Local\Microsoft\Windows\DeliveryOptimization\Cache"
    $t.Add(@{ Key='do'; Name='Delivery Optimization cache'; Desc='แคชที่ใช้แชร์อัปเดตกับเครื่องอื่น — ปลอดภัย'; Specs=@("D|$doPath"); Def=$true; Open=$doPath })
    $t.Add(@{ Key='wer'; Name='รายงานข้อผิดพลาด (Error Reports)'; Desc='รายงานโปรแกรมค้าง/แครชที่ส่งให้ Microsoft แล้ว — ปลอดภัย'; Specs=@("D|$env:ProgramData\Microsoft\Windows\WER\ReportArchive","D|$env:ProgramData\Microsoft\Windows\WER\ReportQueue","D|$L\CrashDumps"); Def=$true; Open="$env:ProgramData\Microsoft\Windows\WER" })
    $br = New-Object System.Collections.Generic.List[string]
    foreach($root in @("$L\Google\Chrome\User Data","$L\Microsoft\Edge\User Data","$L\BraveSoftware\Brave-Browser\User Data")){
        if(-not (Test-Path $root)){ continue }
        foreach($prof in @(Get-ChildItem $root -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -eq 'Default' -or $_.Name -like 'Profile *' })){
            foreach($sub in 'Cache\Cache_Data','Code Cache','GPUCache','Service Worker\CacheStorage'){
                $p = Join-Path $prof.FullName $sub
                if(Test-Path $p){ $br.Add("D|$p") }
            }
        }
    }
    if(Test-Path "$L\Mozilla\Firefox\Profiles"){
        foreach($prof in @(Get-ChildItem "$L\Mozilla\Firefox\Profiles" -Directory -ErrorAction SilentlyContinue)){
            $p = Join-Path $prof.FullName 'cache2'; if(Test-Path $p){ $br.Add("D|$p") }
        }
    }
    $t.Add(@{ Key='browser'; Name='แคชเว็บเบราว์เซอร์'; Desc='Chrome / Edge / Brave / Firefox — ไม่ลบรหัสผ่าน ประวัติ หรือบุ๊กมาร์ก (ควรปิดเบราว์เซอร์ก่อน)'; Specs=$br.ToArray(); Def=$true; Open=$null })
    $t.Add(@{ Key='thumbs'; Name='แคชภาพตัวอย่าง (Thumbnail)'; Desc='ภาพย่อของไฟล์ใน Explorer — ระบบสร้างใหม่ให้อัตโนมัติ'; Specs=@("F|$L\Microsoft\Windows\Explorer|thumbcache_*.db","F|$L\Microsoft\Windows\Explorer|iconcache_*.db"); Def=$false; Open="$L\Microsoft\Windows\Explorer" })
    $t.Add(@{ Key='dumps'; Name='ไฟล์ดัมพ์ตอนจอฟ้า (Memory dump)'; Desc='ช่างอาจใช้วิเคราะห์สาเหตุเครื่องค้าง — ลบได้ถ้าไม่ต้องการตรวจแล้ว'; Specs=@("F|$W|MEMORY.DMP","D|$W\Minidump","D|$W\LiveKernelReports"); Def=$false; Open="$W\Minidump" })
    $sid = [System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value
    $rb = @(foreach($d in [System.IO.DriveInfo]::GetDrives()){ if($d.IsReady -and $d.DriveType -eq 'Fixed'){ "D|$($d.RootDirectory.FullName)`$Recycle.Bin\$sid" } })
    $t.Add(@{ Key='recycle'; Name='ถังขยะ (Recycle Bin)'; Desc='ระวัง: ไฟล์ในถังขยะจะถูกลบถาวร กู้คืนไม่ได้'; Specs=$rb; Def=$false; Open='shell:RecycleBinFolder' })
    return $t
}

function To-Jagged($targets){
    $jag = New-Object 'string[][]' $targets.Count
    for($i = 0; $i -lt $targets.Count; $i++){ $jag[$i] = [string[]]@($targets[$i].Specs) }
    return ,$jag
}


# ============================================================
#   ล้างขยะอัตโนมัติตามเวลา (Task Scheduler)
#   Task จะเรียก  SCPclear.exe -AutoClean  -> ล้างเงียบ ๆ ไม่เปิดหน้าจอ แล้วปิดตัว
# ============================================================
$AutoTaskName = "SCPclear AutoClean"
$AutoCleanDefault = @('utemp','wtemp','wu','do','wer','browser')
$AutoFreqText = @{ daily="ทุกวัน เวลา 12:30"; weekly="ทุกวันจันทร์ เวลา 12:30"; biweekly="วันจันทร์ เว้นสัปดาห์ เวลา 12:30" }

function Get-AutoCleanConfig {
    $cfg = [ordered]@{ Enabled=$false; Freq='weekly'; Items=$AutoCleanDefault; LastRun=''; LastFreed=0; LastSkipped=0; LastError='' }
    if(Test-Path $AutoCleanPath){
        try{
            $j = Get-Content $AutoCleanPath -Raw -Encoding UTF8 | ConvertFrom-Json
            foreach($p in $j.PSObject.Properties){ $cfg[$p.Name] = $p.Value }
            $cfg.Items = @($cfg.Items)
        }catch{}
    }
    return $cfg
}
function Save-AutoCleanConfig($cfg){
    try{ ($cfg | ConvertTo-Json -Depth 4) | Set-Content -Path $AutoCleanPath -Encoding UTF8 }catch{}
}

function Invoke-AutoClean {
    $cfg = Get-AutoCleanConfig
    $items = @($cfg.Items | Where-Object { $_ -and $_ -ne 'recycle' })   # ถังขยะไม่ลบอัตโนมัติเด็ดขาด
    $targets = @(Get-CleanTargets | Where-Object { $items -contains $_.Key })
    $before = (New-Object System.IO.DriveInfo($env:SystemDrive)).TotalFreeSpace
    if($items -contains 'wu'){ Stop-Service wuauserv, bits -Force -ErrorAction SilentlyContinue }
    $res = $null; $err = ''
    try{ $res = [Scp.Cleaner]::Clean((To-Jagged $targets)).GetAwaiter().GetResult() }catch{ $err = $_.Exception.Message }
    if($items -contains 'wu'){ Start-Service wuauserv, bits -ErrorAction SilentlyContinue }
    $freed = [math]::Max([double]0, (New-Object System.IO.DriveInfo($env:SystemDrive)).TotalFreeSpace - $before)
    $skipped = 0
    if($res){ for($i = 1; $i -lt $res.Count; $i += 2){ $skipped += $res[$i] } }
    $now = (Get-Date).ToString("dd/MM/yyyy HH:mm")
    $cfg.LastRun = $now; $cfg.LastFreed = [long]$freed; $cfg.LastSkipped = [long]$skipped; $cfg.LastError = $err
    Save-AutoCleanConfig $cfg
    $line = "$now  ล้างอัตโนมัติ: คืนพื้นที่ $([Scp.Sys]::Size($freed))  ข้าม $skipped ไฟล์ที่ใช้งานอยู่  [$($items -join ',')]"
    if($err){ $line += "  ERROR: $err" }
    try{ Add-Content -Path $AutoCleanLog -Value $line -Encoding UTF8 }catch{}
}

function Get-AutoCleanTask { return (Get-ScheduledTask -TaskName $AutoTaskName -ErrorAction SilentlyContinue) }

function Register-AutoCleanTask($freq){
    if($SelfExe){ $exe = $SelfExe; $arg = "-AutoClean" }
    else { $exe = Join-Path $env:SystemRoot "System32\WindowsPowerShell\v1.0\powershell.exe"; $arg = "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$PSCommandPath`" -AutoClean" }
    $at = [datetime]::Today.AddHours(12).AddMinutes(30)
    $trigger = switch($freq){
        'daily'    { New-ScheduledTaskTrigger -Daily -At $at }
        'biweekly' { New-ScheduledTaskTrigger -Weekly -WeeksInterval 2 -DaysOfWeek Monday -At $at }
        default    { New-ScheduledTaskTrigger -Weekly -WeeksInterval 1 -DaysOfWeek Monday -At $at }
    }
    $action = New-ScheduledTaskAction -Execute $exe -Argument $arg -WorkingDirectory $ScriptDir
    $settings = New-ScheduledTaskSettingsSet -StartWhenAvailable -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -ExecutionTimeLimit (New-TimeSpan -Hours 1) -MultipleInstances IgnoreNew
    $principal = New-ScheduledTaskPrincipal -UserId ([Security.Principal.WindowsIdentity]::GetCurrent().Name) -LogonType Interactive -RunLevel Highest
    Register-ScheduledTask -TaskName $AutoTaskName -Action $action -Trigger $trigger -Settings $settings -Principal $principal -Description "SCPclear: ล้างไฟล์ขยะอัตโนมัติ (ตั้งค่าได้ในหน้า Smart Cleanup)" -Force | Out-Null
}
function Unregister-AutoCleanTask {
    if(Get-AutoCleanTask){ Unregister-ScheduledTask -TaskName $AutoTaskName -Confirm:$false -ErrorAction SilentlyContinue }
}

# โหมดล้างอัตโนมัติ: ไม่เปิดหน้าจอ ทำงานเสร็จแล้วปิดทันที
if($AutoCleanMode){
    try{ Invoke-AutoClean }catch{ try{ Add-Content -Path $AutoCleanLog -Value "$(Get-Date)  ERROR: $($_.Exception.Message)" -Encoding UTF8 }catch{} }
    exit
}

