          <Grid Width="40" Height="40">
            <Border x:Name="LogoBox" CornerRadius="12" Background="#EE6C2B"><TextBlock Text="S" FontSize="21" FontWeight="Bold" Foreground="White" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border>
            <Image x:Name="LogoImg" Visibility="Collapsed" RenderOptions.BitmapScalingMode="HighQuality"/>
          </Grid>
          <StackPanel Margin="11,0,0,0" VerticalAlignment="Center">
            <TextBlock Text="SCPclear" FontSize="19" FontWeight="Bold" Foreground="##TITLEFG##"/>
            <TextBlock x:Name="VersionText" FontSize="11" Foreground="##MUTEDFG##"/>
          </StackPanel>
        </StackPanel>
        <Border DockPanel.Dock="Bottom" Background="##ACCENTSOFT##" CornerRadius="12" Padding="12,10" Margin="0,10,0,0">
          <StackPanel>
            <TextBlock x:Name="SideSpec" FontSize="11.5" FontWeight="SemiBold" Foreground="#EE6C2B" TextWrapping="Wrap"/>
            <TextBlock x:Name="SideSpec2" FontSize="11" Foreground="##MUTEDFG##" Margin="0,2,0,0" TextWrapping="Wrap"/>
          </StackPanel>
        </Border>
        <ScrollViewer VerticalScrollBarVisibility="Auto">
          <StackPanel>
            <TextBlock Text="เมนูหลัก" Style="{StaticResource NavHdr}"/>
            <RadioButton x:Name="Nav_dash" Style="{StaticResource Nav}"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE80F;"/><TextBlock Text="หน้าหลัก" Margin="12,0,0,0"/></StackPanel></RadioButton>
            <RadioButton x:Name="Nav_opt" Style="{StaticResource Nav}"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE945;"/><TextBlock Text="ปรับแต่งเครื่อง" Margin="12,0,0,0"/></StackPanel></RadioButton>
            <RadioButton x:Name="Nav_clean" Style="{StaticResource Nav}"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE74D;"/><TextBlock Text="Smart Cleanup" Margin="12,0,0,0"/></StackPanel></RadioButton>
            <RadioButton x:Name="Nav_storage" Style="{StaticResource Nav}"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xEDA2;"/><TextBlock Text="Storage Analyzer" Margin="12,0,0,0"/></StackPanel></RadioButton>
            <RadioButton x:Name="Nav_large" Style="{StaticResource Nav}"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE721;"/><TextBlock Text="Large File Finder" Margin="12,0,0,0"/></StackPanel></RadioButton>
            <RadioButton x:Name="Nav_health" Style="{StaticResource Nav}"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE95E;"/><TextBlock Text="PC Health Check" Margin="12,0,0,0"/></StackPanel></RadioButton>
            <TextBlock Text="งานช่าง" Style="{StaticResource NavHdr}"/>
            <RadioButton x:Name="Nav_hw" Style="{StaticResource Nav}"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE950;"/><TextBlock Text="ตรวจฮาร์ดแวร์" Margin="12,0,0,0"/></StackPanel></RadioButton>
            <RadioButton x:Name="Nav_backup" Style="{StaticResource Nav}"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE8F7;"/><TextBlock Text="ย้าย / สำรองข้อมูล" Margin="12,0,0,0"/></StackPanel></RadioButton>
            <RadioButton x:Name="Nav_install" Style="{StaticResource Nav}"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE896;"/><TextBlock Text="ลงโปรแกรม" Margin="12,0,0,0"/></StackPanel></RadioButton>
            <TextBlock Text="เครื่องมือ" Style="{StaticResource NavHdr}"/>
            <RadioButton x:Name="Nav_apps" Style="{StaticResource Nav}"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE71D;"/><TextBlock Text="โปรแกรมในเครื่อง" Margin="12,0,0,0"/></StackPanel></RadioButton>
            <RadioButton x:Name="Nav_net" Style="{StaticResource Nav}"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE839;"/><TextBlock Text="เครือข่าย" Margin="12,0,0,0"/></StackPanel></RadioButton>
            <RadioButton x:Name="Nav_pdf" Style="{StaticResource Nav}"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE8A5;"/><TextBlock Text="PDF Tools" Margin="12,0,0,0"/></StackPanel></RadioButton>
            <RadioButton x:Name="Nav_win" Style="{StaticResource Nav}"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE90F;"/><TextBlock Text="Windows Tools" Margin="12,0,0,0"/></StackPanel></RadioButton>
            <TextBlock Text="อื่น ๆ" Style="{StaticResource NavHdr}"/>
            <RadioButton x:Name="Nav_about" Style="{StaticResource Nav}"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE946;"/><TextBlock Text="เกี่ยวกับ" Margin="12,0,0,0"/></StackPanel></RadioButton>
          </StackPanel>
        </ScrollViewer>
      </DockPanel>
    </Border>

    <!-- ===================== พื้นที่เนื้อหา ===================== -->
    <Grid Grid.Column="1" Margin="30,24,24,20">

      <!-- ============ 1) หน้าหลัก ============ -->
      <ScrollViewer x:Name="Page_dash" VerticalScrollBarVisibility="Auto">
        <StackPanel Margin="0,0,6,0">
          <TextBlock x:Name="DashHello" Text="ภาพรวมเครื่อง" Style="{StaticResource PageTitle}"/>
          <TextBlock x:Name="DashSub" Style="{StaticResource PageSub}"/>
          <UniformGrid Columns="4">
            <Border Style="{StaticResource Panel}" Margin="0,0,12,12">
              <StackPanel>
                <StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE950;" Foreground="#EE6C2B" FontSize="15"/><TextBlock Text="  CPU" Style="{StaticResource StatLabel}"/></StackPanel>
                <TextBlock x:Name="DashCpuVal" Text="–" Style="{StaticResource StatValue}"/>
                <ProgressBar x:Name="DashCpuBar" Style="{StaticResource MiniBar}" Maximum="100"/>
                <TextBlock x:Name="DashCpuSub" Style="{StaticResource Muted}" FontSize="11" Margin="0,8,0,0" TextTrimming="CharacterEllipsis" TextWrapping="NoWrap"/>
              </StackPanel>
            </Border>
            <Border Style="{StaticResource Panel}" Margin="0,0,12,12">
              <StackPanel>
                <StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE964;" Foreground="#EE6C2B" FontSize="15"/><TextBlock Text="  RAM" Style="{StaticResource StatLabel}"/></StackPanel>
                <TextBlock x:Name="DashRamVal" Text="–" Style="{StaticResource StatValue}"/>
                <ProgressBar x:Name="DashRamBar" Style="{StaticResource MiniBar}" Maximum="100"/>
                <TextBlock x:Name="DashRamSub" Style="{StaticResource Muted}" FontSize="11" Margin="0,8,0,0"/>
              </StackPanel>
            </Border>
            <Border Style="{StaticResource Panel}" Margin="0,0,12,12">
              <StackPanel>
                <StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xEDA2;" Foreground="#EE6C2B" FontSize="15"/><TextBlock x:Name="DashDiskLabel" Text="  ไดรฟ์ C:" Style="{StaticResource StatLabel}"/></StackPanel>
                <TextBlock x:Name="DashDiskVal" Text="–" Style="{StaticResource StatValue}"/>
                <ProgressBar x:Name="DashDiskBar" Style="{StaticResource MiniBar}" Maximum="100"/>
                <TextBlock x:Name="DashDiskSub" Style="{StaticResource Muted}" FontSize="11" Margin="0,8,0,0"/>
              </StackPanel>
            </Border>
            <Border Style="{StaticResource Panel}" Margin="0,0,12,12">
              <StackPanel>
                <StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE95E;" Foreground="#EE6C2B" FontSize="15"/><TextBlock Text="  สุขภาพเครื่อง" Style="{StaticResource StatLabel}"/></StackPanel>
                <TextBlock x:Name="DashHealthVal" Text="–" Style="{StaticResource StatValue}"/>
                <ProgressBar x:Name="DashHealthBar" Style="{StaticResource MiniBar}" Maximum="100" Foreground="#22A06B"/>
                <TextBlock x:Name="DashHealthSub" Text="ยังไม่ได้ตรวจ — กดที่ PC Health Check" Style="{StaticResource Muted}" FontSize="11" Margin="0,8,0,0"/>
              </StackPanel>
            </Border>
          </UniformGrid>
          <Grid>
            <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
            <Border Grid.Column="0" Style="{StaticResource Panel}" Margin="0,0,12,12">
              <StackPanel>
                <TextBlock Text="ไดรฟ์ทั้งหมด" Style="{StaticResource RowTitle}" FontSize="14.5"/>
                <StackPanel x:Name="DashDrives" Margin="0,10,0,0"/>
              </StackPanel>
            </Border>
            <Border Grid.Column="1" Style="{StaticResource Panel}" Margin="0,0,12,12">
              <StackPanel>
                <TextBlock Text="ข้อมูลเครื่อง" Style="{StaticResource RowTitle}" FontSize="14.5"/>
                <Grid x:Name="DashInfo" Margin="0,10,0,0">
                  <Grid.ColumnDefinitions><ColumnDefinition Width="110"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                </Grid>
              </StackPanel>
            </Border>
          </Grid>
          <TextBlock Text="ทางลัด" Style="{StaticResource Section}"/>
          <UniformGrid x:Name="DashQuick" Columns="4">
            <Button Style="{StaticResource QuickTile}" Tag="clean"><StackPanel><TextBlock Style="{StaticResource Ico}" Text="&#xE74D;" Foreground="#EE6C2B" FontSize="20" HorizontalAlignment="Left"/><TextBlock Text="ล้างไฟล์ขยะ" Style="{StaticResource RowTitle}" Margin="0,8,0,0"/><TextBlock Text="สแกนไฟล์ชั่วคราวที่ลบได้" Style="{StaticResource RowDesc}"/></StackPanel></Button>
            <Button Style="{StaticResource QuickTile}" Tag="opt"><StackPanel><TextBlock Style="{StaticResource Ico}" Text="&#xE945;" Foreground="#EE6C2B" FontSize="20" HorizontalAlignment="Left"/><TextBlock Text="ปรับแต่งเครื่อง" Style="{StaticResource RowTitle}" Margin="0,8,0,0"/><TextBlock Text="เร่งความเร็ว ปิดโฆษณา ลบ Bloatware" Style="{StaticResource RowDesc}"/></StackPanel></Button>
            <Button Style="{StaticResource QuickTile}" Tag="health"><StackPanel><TextBlock Style="{StaticResource Ico}" Text="&#xE95E;" Foreground="#EE6C2B" FontSize="20" HorizontalAlignment="Left"/><TextBlock Text="ตรวจสุขภาพเครื่อง" Style="{StaticResource RowTitle}" Margin="0,8,0,0"/><TextBlock Text="เช็คระบบ ฮาร์ดแวร์ เครือข่าย" Style="{StaticResource RowDesc}"/></StackPanel></Button>
            <Button Style="{StaticResource QuickTile}" Tag="large"><StackPanel><TextBlock Style="{StaticResource Ico}" Text="&#xE721;" Foreground="#EE6C2B" FontSize="20" HorizontalAlignment="Left"/><TextBlock Text="หาไฟล์ขนาดใหญ่" Style="{StaticResource RowTitle}" Margin="0,8,0,0"/><TextBlock Text="ดูว่าไฟล์ไหนกินพื้นที่" Style="{StaticResource RowDesc}"/></StackPanel></Button>
          </UniformGrid>
        </StackPanel>
      </ScrollViewer>

      <!-- ============ 2) ปรับแต่งเครื่อง (ฟีเจอร์เดิมของ SCPclear) ============ -->
      <Grid x:Name="Page_opt" Visibility="Collapsed">
        <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
        <StackPanel Grid.Row="0">
          <TextBlock Text="ปรับแต่งเครื่อง" Style="{StaticResource PageTitle}"/>
          <TextBlock Text="เร่งความเร็ว ล้างขยะ ปิดโฆษณา/Telemetry และลบ AI/Bloatware — เลือกรายการ แล้วกด เริ่มทำงาน (ชี้ที่การ์ดเพื่อดูคำอธิบาย)" Style="{StaticResource PageSub}"/>
        </StackPanel>
        <WrapPanel Grid.Row="1">
          <Button x:Name="BtnRec"  Content="แนะนำ" Style="{StaticResource Chip}"/>
          <Button x:Name="BtnAll"  Content="เลือกทั้งหมด" Style="{StaticResource Chip}"/>
          <Button x:Name="BtnNone" Content="ล้างทั้งหมด" Style="{StaticResource Chip}"/>
          <Button x:Name="BtnDiag" Content="🔍  วิเคราะห์ว่าทำไมเครื่องช้า" Style="{StaticResource Outline}" Margin="6,0,0,8" Padding="14,7"/>
        </WrapPanel>
        <ScrollViewer Grid.Row="2" VerticalScrollBarVisibility="Auto">
          <StackPanel Margin="0,0,6,0">
            <Button x:Name="hdrSpeed" Style="{StaticResource SectionHdr}" Content="▾  ปรับความเร็ว / ล้างขยะ"/>
            <UniformGrid x:Name="secSpeed" Columns="2">
        <Border Style="{StaticResource Card}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel VerticalAlignment="Center"><TextBlock Text="สร้าง Restore Point ก่อน" Style="{StaticResource RowTitle}"/><TextBlock Text="จุดสำรองไว้ย้อนกลับได้ถ้ามีปัญหา" Style="{StaticResource RowDesc}"/></StackPanel><CheckBox x:Name="cb_restore" Grid.Column="1" Style="{StaticResource Toggle}" VerticalAlignment="Center" IsChecked="True"/></Grid></Border>
        <Border Style="{StaticResource Card}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel VerticalAlignment="Center"><TextBlock Text="ตั้ง Virtual Memory ให้เหมาะกับแรม" Style="{StaticResource RowTitle}"/><TextBlock Text="ระบบคำนวณค่าให้อัตโนมัติตามแรม" Style="{StaticResource RowDesc}"/></StackPanel><CheckBox x:Name="cb_pagefile" Grid.Column="1" Style="{StaticResource Toggle}" VerticalAlignment="Center" IsChecked="True"/></Grid></Border>
        <Border Style="{StaticResource Card}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel VerticalAlignment="Center"><TextBlock Text="ปรับ Visual Effects เน้นความเร็ว" Style="{StaticResource RowTitle}"/><TextBlock Text="ปิดเอฟเฟกต์ที่กินทรัพยากร" Style="{StaticResource RowDesc}"/></StackPanel><CheckBox x:Name="cb_visual" Grid.Column="1" Style="{StaticResource Toggle}" VerticalAlignment="Center" IsChecked="True"/></Grid></Border>
        <Border Style="{StaticResource Card}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel VerticalAlignment="Center"><TextBlock Text="ปิด Transparency (ความโปร่งใส)" Style="{StaticResource RowTitle}"/><TextBlock Text="ลดภาระการ์ดจอ" Style="{StaticResource RowDesc}"/></StackPanel><CheckBox x:Name="cb_transp" Grid.Column="1" Style="{StaticResource Toggle}" VerticalAlignment="Center" IsChecked="True"/></Grid></Border>
        <Border Style="{StaticResource Card}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel VerticalAlignment="Center"><TextBlock Text="ปิด SysMain (SuperFetch)" Style="{StaticResource RowTitle}"/><TextBlock Text="ตัวการทำให้ HDD ทำงาน 100%" Style="{StaticResource RowDesc}"/></StackPanel><CheckBox x:Name="cb_sysmain" Grid.Column="1" Style="{StaticResource Toggle}" VerticalAlignment="Center"/></Grid></Border>
        <Border Style="{StaticResource Card}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel VerticalAlignment="Center"><TextBlock Text="ล้างไฟล์ Temp / ขยะ" Style="{StaticResource RowTitle}"/><TextBlock Text="ลบไฟล์ชั่วคราว ปลอดภัย" Style="{StaticResource RowDesc}"/></StackPanel><CheckBox x:Name="cb_temp" Grid.Column="1" Style="{StaticResource Toggle}" VerticalAlignment="Center" IsChecked="True"/></Grid></Border>
        <Border Style="{StaticResource Card}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel VerticalAlignment="Center"><TextBlock Text="ล้าง Windows Update cache" Style="{StaticResource RowTitle}"/><TextBlock Text="คืนพื้นที่ดิสก์" Style="{StaticResource RowDesc}"/></StackPanel><CheckBox x:Name="cb_wucache" Grid.Column="1" Style="{StaticResource Toggle}" VerticalAlignment="Center" IsChecked="True"/></Grid></Border>
        <Border Style="{StaticResource Card}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel VerticalAlignment="Center"><TextBlock Text="ล้าง Recycle Bin + Flush DNS" Style="{StaticResource RowTitle}"/><TextBlock Text="ล้างถังขยะและแคช DNS" Style="{StaticResource RowDesc}"/></StackPanel><CheckBox x:Name="cb_recycledns" Grid.Column="1" Style="{StaticResource Toggle}" VerticalAlignment="Center" IsChecked="True"/></Grid></Border>
        <Border Style="{StaticResource Card}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel VerticalAlignment="Center"><TextBlock Text="ปิด Hibernation (คืนพื้นที่ดิสก์)" Style="{StaticResource RowTitle}"/><TextBlock Text="ลบไฟล์ hiberfil.sys (มักกิน 3-8 GB)" Style="{StaticResource RowDesc}"/></StackPanel><CheckBox x:Name="cb_hibernate" Grid.Column="1" Style="{StaticResource Toggle}" VerticalAlignment="Center"/></Grid></Border>
        <Border Style="{StaticResource Card}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel VerticalAlignment="Center"><TextBlock Text="Power Plan = High Performance" Style="{StaticResource RowTitle}"/><TextBlock Text="โน้ตบุ๊กจะเปลืองแบตขึ้น" Style="{StaticResource RowDesc}"/></StackPanel><CheckBox x:Name="cb_power" Grid.Column="1" Style="{StaticResource Toggle}" VerticalAlignment="Center" IsChecked="True"/></Grid></Border>
        <Border Style="{StaticResource Card}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel VerticalAlignment="Center"><TextBlock Text="Defrag ไดรฟ์ C (เฉพาะ HDD)" Style="{StaticResource RowTitle}"/><TextBlock Text="ข้ามอัตโนมัติถ้าเป็น SSD" Style="{StaticResource RowDesc}"/></StackPanel><CheckBox x:Name="cb_defrag" Grid.Column="1" Style="{StaticResource Toggle}" VerticalAlignment="Center"/></Grid></Border>
        <Border Style="{StaticResource Card}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel VerticalAlignment="Center"><TextBlock Text="เปิดหน้าจัดการ Startup ตอนจบ" Style="{StaticResource RowTitle}"/><TextBlock Text="เปิด Task Manager แท็บ Startup (หรือใช้ปุ่มจัดการในตัวด้านล่าง)" Style="{StaticResource RowDesc}"/></StackPanel><CheckBox x:Name="cb_startup" Grid.Column="1" Style="{StaticResource Toggle}" VerticalAlignment="Center"/></Grid></Border>
            </UniformGrid>
            <Button x:Name="hdrWin" Style="{StaticResource SectionHdr}" Content="▾  ปรับแต่ง WINDOWS"/>
            <UniformGrid x:Name="secWin" Columns="2">
        <Border Style="{StaticResource Card}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel VerticalAlignment="Center"><TextBlock Text="ปิดโฆษณา/คำแนะนำใน Windows" Style="{StaticResource RowTitle}"/><TextBlock Text="ปิดโฆษณาใน Start, Lock screen, การแนะนำแอป" Style="{StaticResource RowDesc}"/></StackPanel><CheckBox x:Name="cb_ads" Grid.Column="1" Style="{StaticResource Toggle}" VerticalAlignment="Center" IsChecked="True"/></Grid></Border>
        <Border Style="{StaticResource Card}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel VerticalAlignment="Center"><TextBlock Text="คืนเมนูคลิกขวาแบบเก่า (Win11)" Style="{StaticResource RowTitle}"/><TextBlock Text="ไม่ต้องกด Show more options" Style="{StaticResource RowDesc}"/></StackPanel><CheckBox x:Name="cb_rightclick" Grid.Column="1" Style="{StaticResource Toggle}" VerticalAlignment="Center"/></Grid></Border>
        <Border Style="{StaticResource Card}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel VerticalAlignment="Center"><TextBlock Text="ปิด Widgets + Chat บน taskbar" Style="{StaticResource RowTitle}"/><TextBlock Text="เอาไอคอน Widgets/Chat ออกจากแถบงาน" Style="{StaticResource RowDesc}"/></StackPanel><CheckBox x:Name="cb_widgets" Grid.Column="1" Style="{StaticResource Toggle}" VerticalAlignment="Center"/></Grid></Border>
            </UniformGrid>
            <Button x:Name="hdrAI" Style="{StaticResource SectionHdr}" Content="▾  ลบ AI / BLOATWARE / ความเป็นส่วนตัว"/>
            <UniformGrid x:Name="secAI" Columns="2">
        <Border Style="{StaticResource Card}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel VerticalAlignment="Center"><TextBlock Text="ถามยืนยันก่อนลบแต่ละอย่าง" Style="{StaticResource RowTitle}"/><TextBlock Text="เด้งถาม Yes/No ก่อนลบทีละตัว (ปลอดภัย)" Style="{StaticResource RowDesc}"/></StackPanel><CheckBox x:Name="cb_confirm" Grid.Column="1" Style="{StaticResource Toggle}" VerticalAlignment="Center" IsChecked="True"/></Grid></Border>
        <Border Style="{StaticResource Card}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel VerticalAlignment="Center"><TextBlock Text="ลบ Windows AI (Copilot + Recall)" Style="{StaticResource RowTitle}"/><TextBlock Text="ปิด/ลบ Copilot และ Recall ออกจากเครื่อง" Style="{StaticResource RowDesc}"/></StackPanel><CheckBox x:Name="cb_removeai" Grid.Column="1" Style="{StaticResource Toggle}" VerticalAlignment="Center" IsChecked="True"/></Grid></Border>
        <Border Style="{StaticResource Card}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel VerticalAlignment="Center"><TextBlock Text="ลบ Bloatware (Xbox, News ฯลฯ)" Style="{StaticResource RowTitle}"/><TextBlock Text="ลบแอปที่ไม่จำเป็น (ไม่มีในเครื่องจะข้ามให้)" Style="{StaticResource RowDesc}"/></StackPanel><CheckBox x:Name="cb_bloat" Grid.Column="1" Style="{StaticResource Toggle}" VerticalAlignment="Center" IsChecked="True"/></Grid></Border>
        <Border Style="{StaticResource Card}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel VerticalAlignment="Center"><TextBlock Text="ปิด Telemetry (ส่งข้อมูลกลับ MS)" Style="{StaticResource RowTitle}"/><TextBlock Text="ปิดการเก็บ/ส่งข้อมูลการใช้งาน" Style="{StaticResource RowDesc}"/></StackPanel><CheckBox x:Name="cb_telemetry" Grid.Column="1" Style="{StaticResource Toggle}" VerticalAlignment="Center" IsChecked="True"/></Grid></Border>
        <Border Style="{StaticResource Card}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel VerticalAlignment="Center"><TextBlock Text="ถอนการติดตั้ง OneDrive" Style="{StaticResource RowTitle}"/><TextBlock Text="ปิด+ถอน OneDrive (ไฟล์ยังอยู่ ลงกลับได้)" Style="{StaticResource RowDesc}"/></StackPanel><CheckBox x:Name="cb_onedrive" Grid.Column="1" Style="{StaticResource Toggle}" VerticalAlignment="Center"/></Grid></Border>
            </UniformGrid>
            <Button x:Name="hdrSys" Style="{StaticResource SectionHdr}" Content="▾  จัดการระบบ"/>
            <UniformGrid x:Name="secSys" Columns="2">
        <Border Style="{StaticResource Card}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel VerticalAlignment="Center"><TextBlock Text="ตรวจสอบ &amp; ติดตั้ง Windows Update" Style="{StaticResource RowTitle}"/><TextBlock Text="เช็คอัปเดตระบบปฏิบัติการล่าสุดและติดตั้งให้ (อาจใช้เวลานาน)" Style="{StaticResource RowDesc}"/></StackPanel><CheckBox x:Name="cb_winupdate" Grid.Column="1" Style="{StaticResource Toggle}" VerticalAlignment="Center"/></Grid></Border>
        <Border Style="{StaticResource Card}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel VerticalAlignment="Center"><TextBlock Text="ซ่อมไฟล์ระบบ (SFC + DISM)" Style="{StaticResource RowTitle}"/><TextBlock Text="ตรวจสอบและซ่อมไฟล์ระบบที่เสียหาย (อาจใช้เวลานาน)" Style="{StaticResource RowDesc}"/></StackPanel><CheckBox x:Name="cb_sfcdism" Grid.Column="1" Style="{StaticResource Toggle}" VerticalAlignment="Center"/></Grid></Border>
            </UniformGrid>
          </StackPanel>
        </ScrollViewer>
        <StackPanel Grid.Row="3" Margin="0,10,0,10">
          <Grid>
            <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
            <TextBlock x:Name="StatusText" Grid.Column="0" Text="พร้อมทำงาน" FontSize="12.5" FontWeight="SemiBold" Foreground="##LOGFG##" VerticalAlignment="Center" TextTrimming="CharacterEllipsis"/>
            <TextBlock x:Name="StepText" Grid.Column="1" Text="" FontSize="11" Foreground="##MUTEDFG##" VerticalAlignment="Center" Margin="8,0,0,0"/>
          </Grid>
          <ProgressBar x:Name="Pb" Style="{StaticResource MiniBar}" Minimum="0" Maximum="20" Value="0" Margin="0,6,0,0"/>
          <Button x:Name="BtnToggleLog" Content="ดูรายละเอียด ▾" Style="{StaticResource Link}" HorizontalAlignment="Left" Margin="-8,2,0,0"/>
          <Border x:Name="LogBox" Background="##LOGBG##" BorderBrush="##LOGBORDER##" BorderThickness="1" CornerRadius="9" Margin="0,4,0,0" Visibility="Collapsed">
            <TextBox x:Name="Log" IsReadOnly="True" BorderThickness="0" Background="Transparent" Foreground="##LOGFG##" FontFamily="Consolas" FontSize="11" Height="96" VerticalScrollBarVisibility="Auto" TextWrapping="Wrap" Padding="10,8"/>
          </Border>
        </StackPanel>
        <Grid Grid.Row="4">
          <Grid.ColumnDefinitions><ColumnDefinition Width="320"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
          <Button x:Name="BtnRun" Content="เริ่มทำงาน" Style="{StaticResource Primary}" Padding="0,13"/>
          <Button x:Name="BtnRevert" Grid.Column="1" Content="ย้อนกลับการปรับแต่ง" Style="{StaticResource Link}" HorizontalAlignment="Left" Margin="14,0,0,0"/>
        </Grid>
      </Grid>

      <!-- ============ 3) Smart Cleanup ============ -->
      <Grid x:Name="Page_clean" Visibility="Collapsed">
        <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
        <StackPanel Grid.Row="0">
          <TextBlock Text="Smart Cleanup" Style="{StaticResource PageTitle}"/>
          <TextBlock Text="สแกนไฟล์ชั่วคราวและไฟล์ขยะที่ไม่จำเป็น เลือกเฉพาะรายการที่ต้องการลบ — ควรตรวจสอบรายการก่อนลบทุกครั้ง" Style="{StaticResource PageSub}"/>
        </StackPanel>
        <Border Grid.Row="1" Style="{StaticResource Panel}" Margin="0,0,6,14">
          <Grid>
            <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
            <Border Width="54" Height="54" CornerRadius="27" Background="##ACCENTSOFT##"><TextBlock Style="{StaticResource Ico}" Text="&#xE74D;" FontSize="22" Foreground="#EE6C2B" HorizontalAlignment="Center"/></Border>
            <StackPanel Grid.Column="1" Margin="16,0,0,0" VerticalAlignment="Center">
              <TextBlock x:Name="CleanTotal" Text="กำลังเตรียมสแกน..." FontSize="22" FontWeight="Bold" Foreground="##TITLEFG##"/>
              <TextBlock x:Name="CleanStatus" Style="{StaticResource Muted}" Margin="0,3,0,0"/>
            </StackPanel>
            <StackPanel Grid.Column="2" Orientation="Horizontal" VerticalAlignment="Center">
              <Button x:Name="BtnCleanScan" Content="สแกนใหม่" Style="{StaticResource Secondary}" Margin="0,0,10,0"/>
              <Button x:Name="BtnCleanRun" Content="ลบรายการที่เลือก" Style="{StaticResource Primary}" IsEnabled="False"/>
            </StackPanel>
          </Grid>
        </Border>
        <Border Grid.Row="2" Style="{StaticResource Panel}" Margin="0,0,6,14" Padding="18,12">
          <Grid>
            <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
            <CheckBox x:Name="AutoCleanOn" Style="{StaticResource Toggle}" VerticalAlignment="Center"/>
            <StackPanel Grid.Column="1" Margin="14,0,12,0" VerticalAlignment="Center">
              <StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE823;" Foreground="#EE6C2B" FontSize="14"/><TextBlock Text="  ล้างอัตโนมัติตามเวลา" Style="{StaticResource RowTitle}"/></StackPanel>
              <TextBlock x:Name="AutoCleanStatus" Style="{StaticResource RowDesc}"/>
            </StackPanel>
            <WrapPanel Grid.Column="2" VerticalAlignment="Center">
              <RadioButton x:Name="ac_daily" Content="ทุกวัน" Style="{StaticResource Seg}" GroupName="acfreq" Tag="daily" Margin="0,0,6,0"/>
              <RadioButton x:Name="ac_weekly" Content="ทุกสัปดาห์" Style="{StaticResource Seg}" GroupName="acfreq" Tag="weekly" IsChecked="True" Margin="0,0,6,0"/>
              <RadioButton x:Name="ac_biweekly" Content="ทุก 2 สัปดาห์" Style="{StaticResource Seg}" GroupName="acfreq" Tag="biweekly" Margin="0,0,6,0"/>
            </WrapPanel>
            <Button x:Name="BtnAutoSave" Grid.Column="3" Content="บันทึก" Style="{StaticResource Secondary}" Margin="6,0,0,0" VerticalAlignment="Center"/>
          </Grid>
        </Border>
        <ScrollViewer Grid.Row="3" VerticalScrollBarVisibility="Auto">
          <StackPanel x:Name="CleanList" Margin="0,0,6,0"/>
        </ScrollViewer>
      </Grid>

      <!-- ============ 4) Storage Analyzer ============ -->
      <Grid x:Name="Page_storage" Visibility="Collapsed">
        <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
        <StackPanel Grid.Row="0">
          <TextBlock Text="Storage Analyzer" Style="{StaticResource PageTitle}"/>
          <TextBlock Text="ดูว่าโฟลเดอร์ไหนใช้พื้นที่มากที่สุด — เลือกไดรฟ์หรือโฟลเดอร์ แล้วคลิกโฟลเดอร์ในรายการเพื่อเจาะลึกลงไป" Style="{StaticResource PageSub}"/>
        </StackPanel>
        <WrapPanel Grid.Row="1" x:Name="StorDrives"/>
        <Border Grid.Row="2" Style="{StaticResource Panel}" Padding="12,9" Margin="0,4,6,10">
          <Grid>
            <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
            <Button x:Name="BtnStorBack" Content="◀  ย้อนกลับ" Style="{StaticResource Secondary}" IsEnabled="False" Padding="12,7"/>
            <StackPanel Grid.Column="1" Margin="12,0" VerticalAlignment="Center">
              <TextBlock x:Name="StorPath" Text="ยังไม่ได้เลือกไดรฟ์" Style="{StaticResource RowTitle}" TextTrimming="CharacterEllipsis"/>
              <TextBlock x:Name="StorStatus" Style="{StaticResource Muted}" FontSize="11.5" TextTrimming="CharacterEllipsis" TextWrapping="NoWrap"/>
            </StackPanel>
            <StackPanel Grid.Column="2" Orientation="Horizontal">
              <RadioButton x:Name="stor_list" Content="รายการ" Style="{StaticResource Seg}" GroupName="storview" IsChecked="True" Margin="0,0,4,0" VerticalAlignment="Center"/>
              <RadioButton x:Name="stor_map" Content="แผนภาพ" Style="{StaticResource Seg}" GroupName="storview" Margin="0,0,12,0" VerticalAlignment="Center"/>
              <Button x:Name="BtnStorCancel" Content="หยุดสแกน" Style="{StaticResource Secondary}" Padding="12,7" Margin="0,0,8,0" Visibility="Collapsed"/>
              <Button x:Name="BtnStorFolder" Content="เลือกโฟลเดอร์..." Style="{StaticResource Secondary}" Padding="12,7" Margin="0,0,8,0"/>
              <Button x:Name="BtnStorOpen" Content="เปิดใน Explorer" Style="{StaticResource Secondary}" Padding="12,7" IsEnabled="False"/>
            </StackPanel>
          </Grid>
        </Border>
        <Border Grid.Row="3" Style="{StaticResource Panel}" Padding="6" Margin="0,0,6,0">
          <Grid>
            <ScrollViewer x:Name="StorListBox" VerticalScrollBarVisibility="Auto">
              <StackPanel x:Name="StorList"/>
            </ScrollViewer>
            <Canvas x:Name="StorMap" Visibility="Collapsed" ClipToBounds="True" Background="Transparent"/>
          </Grid>
        </Border>
      </Grid>

      <!-- ============ 5) Large File Finder ============ -->
      <Grid x:Name="Page_large" Visibility="Collapsed">
        <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
        <Grid Grid.Row="0">
          <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
          <StackPanel>
            <TextBlock x:Name="LfTitle" Text="Large File Finder" Style="{StaticResource PageTitle}"/>
            <TextBlock x:Name="LfSub" Text="ค้นหาไฟล์ขนาดใหญ่ พร้อมชื่อไฟล์ ขนาด และตำแหน่ง — ตรวจสอบก่อนตัดสินใจลบ (ลบแล้วไปอยู่ในถังขยะ กู้คืนได้)" Style="{StaticResource PageSub}"/>
          </StackPanel>
          <StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Top" Margin="0,6,6,0">
            <RadioButton x:Name="lfmode_large" Content="ไฟล์ขนาดใหญ่" Style="{StaticResource Seg}" GroupName="lfmode" IsChecked="True"/>
            <RadioButton x:Name="lfmode_dup" Content="ไฟล์ซ้ำ" Style="{StaticResource Seg}" GroupName="lfmode"/>
          </StackPanel>
        </Grid>
        <Border Grid.Row="1" Style="{StaticResource Panel}" Margin="0,0,6,10">
          <Grid>
            <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
            <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
            <TextBlock Text="ค้นหาใน" Style="{StaticResource RowTitle}" VerticalAlignment="Center" Margin="0,0,12,0"/>
            <TextBox x:Name="LfPath" Grid.Column="1" Style="{StaticResource Input}"/>
            <Button x:Name="BtnLfBrowse" Grid.Column="2" Content="เลือกโฟลเดอร์..." Style="{StaticResource Secondary}" Margin="8,0,0,0"/>
            <TextBlock Grid.Row="1" Text="ขนาดขั้นต่ำ" Style="{StaticResource RowTitle}" VerticalAlignment="Center" Margin="0,12,12,0"/>
            <WrapPanel Grid.Row="1" Grid.Column="1" Margin="0,12,0,0" VerticalAlignment="Center">
              <RadioButton x:Name="lf_50"  Content="50 MB"  Style="{StaticResource Seg}" GroupName="lfmin" Tag="50"/>
              <RadioButton x:Name="lf_100" Content="100 MB" Style="{StaticResource Seg}" GroupName="lfmin" Tag="100" IsChecked="True"/>
              <RadioButton x:Name="lf_500" Content="500 MB" Style="{StaticResource Seg}" GroupName="lfmin" Tag="500"/>
              <RadioButton x:Name="lf_1000" Content="1 GB"  Style="{StaticResource Seg}" GroupName="lfmin" Tag="1024"/>
              <CheckBox x:Name="LfSkipSys" Style="{StaticResource Toggle}" IsChecked="True" Margin="14,0,8,6" VerticalAlignment="Center"/>
              <TextBlock Text="ข้ามโฟลเดอร์ระบบ (Windows, Program Files)" Style="{StaticResource Muted}" VerticalAlignment="Center" Margin="0,0,0,6"/>
            </WrapPanel>
            <Button x:Name="BtnLfScan" Grid.Row="1" Grid.Column="2" Content="ค้นหา" Style="{StaticResource Primary}" Margin="8,12,0,0" Padding="28,9"/>
          </Grid>
        </Border>
        <TextBlock Grid.Row="2" x:Name="LfStatus" Text="เลือกตำแหน่งแล้วกด ค้นหา" Style="{StaticResource Muted}" Margin="2,0,0,8" TextTrimming="CharacterEllipsis" TextWrapping="NoWrap"/>
        <DataGrid Grid.Row="3" x:Name="LfGrid" Style="{StaticResource Grid}" Margin="0,0,6,0">
          <DataGrid.Columns>
            <DataGridTextColumn Header="กลุ่มไฟล์ซ้ำ" Binding="{Binding GroupText}" SortMemberPath="Group" Width="130" Visibility="Collapsed"/>
            <DataGridTextColumn Header="ชื่อไฟล์" Binding="{Binding Name}" Width="2*"/>
            <DataGridTextColumn Header="ขนาด" Binding="{Binding SizeText}" SortMemberPath="Size" Width="90"/>
            <DataGridTextColumn Header="ประเภท" Binding="{Binding Ext}" Width="70"/>
            <DataGridTextColumn Header="แก้ไขล่าสุด" Binding="{Binding ModifiedText}" SortMemberPath="Modified" Width="125"/>
            <DataGridTextColumn Header="ตำแหน่ง" Binding="{Binding Folder}" Width="3*"/>
          </DataGrid.Columns>
        </DataGrid>
        <Grid Grid.Row="4" Margin="0,10,6,0">
          <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
          <TextBlock x:Name="LfSel" Style="{StaticResource Muted}" VerticalAlignment="Center" Text="เลือกไฟล์ในตาราง (กด Ctrl/Shift เพื่อเลือกหลายไฟล์ • ดับเบิลคลิกเพื่อเปิดตำแหน่ง)"/>
          <StackPanel Grid.Column="1" Orientation="Horizontal">
            <Button x:Name="BtnLfAutoSel" Content="เลือกไฟล์ซ้ำอัตโนมัติ (เก็บไว้กลุ่มละ 1)" Style="{StaticResource Secondary}" Margin="0,0,8,0" Visibility="Collapsed"/>
            <Button x:Name="BtnLfOpen" Content="เปิดตำแหน่งไฟล์" Style="{StaticResource Secondary}" Margin="0,0,8,0" IsEnabled="False"/>
            <Button x:Name="BtnLfDelete" Content="ย้ายไปถังขยะ" Style="{StaticResource Outline}" IsEnabled="False"/>
          </StackPanel>
        </Grid>
      </Grid>

      <!-- ============ 6) PC Health Check ============ -->
      <Grid x:Name="Page_health" Visibility="Collapsed">
        <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
        <StackPanel Grid.Row="0">
          <TextBlock Text="PC Health Check" Style="{StaticResource PageTitle}"/>
          <TextBlock Text="ตรวจสถานะระบบปฏิบัติการ ฮาร์ดแวร์ เครือข่าย และบริการสำคัญ พร้อมปุ่มแก้ไขเบื้องต้น (การตรวจเป็นการตรวจเบื้องต้น ไม่รับประกันว่าพบทุกปัญหา)" Style="{StaticResource PageSub}"/>
        </StackPanel>
        <Border Grid.Row="1" Style="{StaticResource Panel}" Margin="0,0,6,6">
          <Grid>
            <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
            <Grid Width="70" Height="70">
              <Ellipse x:Name="HealthRing" Stroke="##PROGTRACK##" StrokeThickness="6"/>
              <TextBlock x:Name="HealthScore" Text="–" FontSize="22" FontWeight="Bold" Foreground="##TITLEFG##" HorizontalAlignment="Center" VerticalAlignment="Center"/>
            </Grid>
            <StackPanel Grid.Column="1" Margin="16,0,0,0" VerticalAlignment="Center">
              <TextBlock x:Name="HealthHeadline" Text="คะแนนสุขภาพเครื่อง" FontSize="18" FontWeight="Bold" Foreground="##TITLEFG##"/>
              <TextBlock x:Name="HealthCounts" Style="{StaticResource Muted}" FontSize="12.5" Margin="0,4,0,0"/>
            </StackPanel>
            <StackPanel Grid.Column="2" Orientation="Horizontal" VerticalAlignment="Center">
              <Button x:Name="BtnHealthHistory" Content="ประวัติการซ่อม" Style="{StaticResource Secondary}" Margin="0,0,8,0"/>
              <Button x:Name="BtnHealthExport" Content="รายงานเครื่อง (HTML/PDF)" Style="{StaticResource Secondary}" Margin="0,0,8,0"/>
              <Button x:Name="BtnHealthScan" Content="ตรวจใหม่" Style="{StaticResource Primary}"/>
            </StackPanel>
          </Grid>
        </Border>
        <ScrollViewer Grid.Row="2" VerticalScrollBarVisibility="Auto">
          <StackPanel x:Name="HealthList" Margin="0,0,6,0"/>
        </ScrollViewer>
      </Grid>

      <!-- ============ โปรแกรมในเครื่อง (ถอนการติดตั้ง) ============ -->
      <Grid x:Name="Page_apps" Visibility="Collapsed">
        <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
        <StackPanel Grid.Row="0">
          <TextBlock Text="โปรแกรมในเครื่อง" Style="{StaticResource PageTitle}"/>
          <TextBlock Text="รายการโปรแกรมที่ติดตั้ง พร้อมขนาดและวันที่ติดตั้ง — เลือกแล้วกด ถอนการติดตั้ง (จะเปิดตัวถอนของโปรแกรมนั้น) • คลิกหัวตารางเพื่อเรียงลำดับ" Style="{StaticResource PageSub}"/>
        </StackPanel>
        <Grid Grid.Row="1" Margin="0,0,6,10">
          <Grid.ColumnDefinitions><ColumnDefinition Width="320"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
          <Grid>
            <TextBox x:Name="AppSearch" Style="{StaticResource Input}"/>
            <TextBlock x:Name="AppSearchHint" Text="🔍  ค้นหาชื่อโปรแกรม / ผู้ผลิต" Style="{StaticResource Muted}" IsHitTestVisible="False" VerticalAlignment="Center" Margin="12,0,0,0"/>
          </Grid>
          <WrapPanel Grid.Column="1" VerticalAlignment="Center" Margin="14,0,0,0">
            <CheckBox x:Name="AppShowStore" Style="{StaticResource Toggle}" IsChecked="True" VerticalAlignment="Center"/>
            <TextBlock Text="แอปจาก Store" Style="{StaticResource Muted}" VerticalAlignment="Center" Margin="8,0,16,0"/>
            <CheckBox x:Name="AppShowSys" Style="{StaticResource Toggle}" VerticalAlignment="Center"/>
            <TextBlock Text="ส่วนประกอบระบบ / อัปเดต" Style="{StaticResource Muted}" VerticalAlignment="Center" Margin="8,0,0,0"/>
          </WrapPanel>
          <Button x:Name="BtnAppsRefresh" Grid.Column="2" Content="รีเฟรช" Style="{StaticResource Secondary}"/>
        </Grid>
        <DataGrid Grid.Row="2" x:Name="AppsGrid" Style="{StaticResource Grid}" SelectionMode="Single" Margin="0,0,6,0">
          <DataGrid.Columns>
            <DataGridTextColumn Header="ชื่อโปรแกรม" Binding="{Binding Name}" Width="3*"/>
            <DataGridTextColumn Header="ผู้ผลิต" Binding="{Binding Publisher}" Width="2*"/>
            <DataGridTextColumn Header="เวอร์ชัน" Binding="{Binding Version}" Width="110"/>
            <DataGridTextColumn Header="ขนาด" Binding="{Binding SizeText}" SortMemberPath="SizeBytes" Width="85"/>
            <DataGridTextColumn Header="ติดตั้งเมื่อ" Binding="{Binding DateText}" SortMemberPath="Date" Width="95"/>
            <DataGridTextColumn Header="ประเภท" Binding="{Binding Kind}" Width="80"/>
          </DataGrid.Columns>
        </DataGrid>
        <Grid Grid.Row="3" Margin="0,10,6,0">
          <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
          <TextBlock x:Name="AppsStatus" Style="{StaticResource Muted}" VerticalAlignment="Center" TextTrimming="CharacterEllipsis" TextWrapping="NoWrap"/>
          <StackPanel Grid.Column="1" Orientation="Horizontal">
            <Button x:Name="BtnAppOpenLoc" Content="เปิดตำแหน่งติดตั้ง" Style="{StaticResource Secondary}" Margin="0,0,8,0" IsEnabled="False"/>
            <Button x:Name="BtnAppUninstall" Content="ถอนการติดตั้ง" Style="{StaticResource Outline}" IsEnabled="False"/>
          </StackPanel>
        </Grid>
      </Grid>

      <!-- ============ เครือข่าย ============ -->
      <ScrollViewer x:Name="Page_net" Visibility="Collapsed" VerticalScrollBarVisibility="Auto">
        <StackPanel Margin="0,0,6,0">
          <TextBlock Text="เครือข่าย" Style="{StaticResource PageTitle}"/>
          <TextBlock Text="ข้อมูลการ์ดเครือข่าย IP / MAC / DNS ทดสอบการเชื่อมต่อ และดูรหัส Wi-Fi ที่เครื่องเคยบันทึกไว้" Style="{StaticResource PageSub}"/>
          <Grid>
            <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
            <StackPanel Margin="0,0,12,0">
              <Border Style="{StaticResource Panel}" Margin="0,0,0,12">
                <Grid>
                  <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                  <StackPanel VerticalAlignment="Center">
                    <TextBlock Text="IP สาธารณะ (อินเทอร์เน็ตเห็นเครื่องนี้เป็น)" Style="{StaticResource RowTitle}"/>
                    <TextBlock x:Name="NetPublic" Text="กดปุ่มเพื่อตรวจ (ส่งคำขอไปที่ api.ipify.org)" Style="{StaticResource RowDesc}"/>
                  </StackPanel>
                  <Button x:Name="BtnNetPublic" Grid.Column="1" Content="ตรวจ IP สาธารณะ" Style="{StaticResource Secondary}" VerticalAlignment="Center"/>
                </Grid>
              </Border>
              <Grid Margin="2,0,0,8">
                <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                <TextBlock Text="การ์ดเครือข่าย" Style="{StaticResource Section}" Margin="0" VerticalAlignment="Center"/>
                <Button x:Name="BtnNetRefresh" Grid.Column="1" Content="รีเฟรช" Style="{StaticResource Link}"/>
              </Grid>
              <StackPanel x:Name="NetAdapters"/>
            </StackPanel>
            <StackPanel Grid.Column="1">
              <Border Style="{StaticResource Panel}" Margin="0,0,0,12">
                <StackPanel>
                  <StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE839;" Foreground="#EE6C2B"/><TextBlock Text="  ทดสอบการเชื่อมต่อ (Ping)" Style="{StaticResource RowTitle}" FontSize="14.5"/></StackPanel>
                  <Grid Margin="0,10,0,0">
                    <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                    <TextBox x:Name="PingHost" Style="{StaticResource Input}" Text="8.8.8.8"/>
                    <Button x:Name="BtnPing" Grid.Column="1" Content="เริ่ม Ping" Style="{StaticResource Primary}" Padding="18,8" Margin="8,0,0,0"/>
                  </Grid>
                  <WrapPanel Margin="0,8,0,0">
                    <Button x:Name="BtnPingGw" Content="Router (Gateway)" Style="{StaticResource Chip}"/>
                    <Button x:Name="BtnPingDns" Content="8.8.8.8" Style="{StaticResource Chip}"/>
                    <Button x:Name="BtnPingWeb" Content="google.com" Style="{StaticResource Chip}"/>
                  </WrapPanel>
                  <TextBlock x:Name="PingSummary" Text="ส่ง 10 ครั้ง วัดเวลาตอบสนองและการสูญหายของข้อมูล" Style="{StaticResource Body}" FontWeight="SemiBold" Margin="0,4,0,8"/>
                  <Border Background="##LOGBG##" BorderBrush="##LOGBORDER##" BorderThickness="1" CornerRadius="10">
                    <TextBox x:Name="PingOut" IsReadOnly="True" BorderThickness="0" Background="Transparent" Foreground="##LOGFG##" FontFamily="Consolas" FontSize="11.5" Height="150" VerticalScrollBarVisibility="Auto" TextWrapping="Wrap" Padding="10,8"/>
                  </Border>
                </StackPanel>
              </Border>
              <Border Style="{StaticResource Panel}" Margin="0,0,0,12">
                <StackPanel>
                  <Grid>
                    <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                    <StackPanel Orientation="Horizontal" VerticalAlignment="Center"><TextBlock Style="{StaticResource Ico}" Text="&#xE701;" Foreground="#EE6C2B"/><TextBlock Text="  รหัส Wi-Fi ที่บันทึกไว้" Style="{StaticResource RowTitle}" FontSize="14.5"/></StackPanel>
                    <Button x:Name="BtnWifiLoad" Grid.Column="1" Content="โหลดรายการ" Style="{StaticResource Secondary}"/>
                  </Grid>
                  <TextBlock Text="ใช้ตอนลืมรหัส Wi-Fi หรือจะต่อเครื่องใหม่ — รหัสจะซ่อนไว้จนกว่าจะกด แสดง" Style="{StaticResource RowDesc}" Margin="0,3,0,10"/>
                  <StackPanel x:Name="WifiList"/>
                </StackPanel>
              </Border>
            </StackPanel>
          </Grid>
          <Border Style="{StaticResource Panel}" Margin="0,0,0,12">
            <StackPanel>
              <Grid>
                <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                <StackPanel>
                  <StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE968;" Foreground="#EE6C2B"/><TextBlock Text="  อุปกรณ์ในวง LAN" Style="{StaticResource RowTitle}" FontSize="14.5"/></StackPanel>
                  <TextBlock Text="หาเครื่องพิมพ์ กล้อง เราเตอร์ และคอมพิวเตอร์ในเครือข่ายเดียวกัน พร้อม IP / MAC — ประเภทอุปกรณ์เดาจากพอร์ตที่เปิดอยู่" Style="{StaticResource RowDesc}" Margin="0,3,0,0"/>
                </StackPanel>
                <Button x:Name="BtnLanScan" Grid.Column="1" Content="สแกนวง LAN" Style="{StaticResource Primary}" Padding="20,8" VerticalAlignment="Center"/>
              </Grid>
              <WrapPanel x:Name="LanNets" Margin="0,10,0,0"/>
              <TextBlock x:Name="LanStatus" Text="เลือกวงเครือข่ายแล้วกด สแกนวง LAN (ใช้เวลาประมาณ 10-30 วินาที)" Style="{StaticResource Muted}" Margin="2,4,0,8"/>
              <DataGrid x:Name="LanGrid" Style="{StaticResource Grid}" SelectionMode="Single" Height="300">
                <DataGrid.Columns>
                  <DataGridTextColumn Header="IP" Binding="{Binding IP}" SortMemberPath="Sort" Width="115"/>
                  <DataGridTextColumn Header="ประเภท (เดา)" Binding="{Binding Kind}" Width="190"/>
                  <DataGridTextColumn Header="ชื่อเครื่อง" Binding="{Binding Name}" Width="*"/>
                  <DataGridTextColumn Header="MAC" Binding="{Binding MAC}" Width="140"/>
                  <DataGridTextColumn Header="พอร์ตที่เปิด" Binding="{Binding Ports}" Width="130"/>
                  <DataGridTextColumn Header="ตอบสนอง" Binding="{Binding MsText}" SortMemberPath="Ms" Width="85"/>
                </DataGrid.Columns>
              </DataGrid>
              <WrapPanel Margin="0,10,0,0">
                <Button x:Name="BtnLanWeb" Content="เปิดหน้าเว็บของอุปกรณ์" Style="{StaticResource Secondary}" Margin="0,0,8,0" IsEnabled="False"/>
                <Button x:Name="BtnLanCopy" Content="คัดลอก IP" Style="{StaticResource Secondary}" Margin="0,0,8,0" IsEnabled="False"/>
                <Button x:Name="BtnLanPing" Content="Ping เครื่องนี้" Style="{StaticResource Secondary}" IsEnabled="False"/>
              </WrapPanel>
            </StackPanel>
          </Border>
        </StackPanel>
      </ScrollViewer>

      <!-- ============ ตรวจฮาร์ดแวร์ (งานช่าง) ============ -->
      <ScrollViewer x:Name="Page_hw" Visibility="Collapsed" VerticalScrollBarVisibility="Auto">
        <StackPanel Margin="0,0,6,0">
          <TextBlock Text="ตรวจฮาร์ดแวร์" Style="{StaticResource PageTitle}"/>
          <TextBlock Text="วิเคราะห์จอฟ้า/เครื่องดับเอง ข้อมูลอัปเกรด RAM ทดสอบความเร็วดิสก์ ทดสอบ CPU/RAM และหาอุปกรณ์ที่ไม่มีไดรเวอร์" Style="{StaticResource PageSub}"/>
          <Border Style="{StaticResource Panel}" Margin="0,0,0,12">
            <StackPanel>
              <Grid>
                <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                <StackPanel Orientation="Horizontal" VerticalAlignment="Center"><TextBlock Style="{StaticResource Ico}" Text="&#xE7BA;" Foreground="#EE6C2B"/><TextBlock Text="  วิเคราะห์จอฟ้า (BSOD) / เครื่องดับเอง" Style="{StaticResource RowTitle}" FontSize="14.5"/></StackPanel>
                <Button x:Name="BtnBsodScan" Grid.Column="1" Content="ตรวจใหม่" Style="{StaticResource Secondary}"/>
              </Grid>
              <TextBlock x:Name="BsodSummary" Text="กำลังอ่านไฟล์ crash dump และ Event Log..." Style="{StaticResource Body}" FontSize="13" FontWeight="SemiBold" Margin="0,10,0,4"/>
              <TextBlock x:Name="BsodAdvice" Style="{StaticResource Muted}" FontSize="12.5"/>
              <StackPanel x:Name="BsodList" Margin="0,10,0,0"/>
            </StackPanel>
          </Border>
          <Grid>
            <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
            <Border Style="{StaticResource Panel}" Margin="0,0,12,12">
              <StackPanel>
                <StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE964;" Foreground="#EE6C2B"/><TextBlock Text="  ข้อมูลอัปเกรด (RAM / เมนบอร์ด)" Style="{StaticResource RowTitle}" FontSize="14.5"/></StackPanel>
                <StackPanel x:Name="HwUpgrade" Margin="0,10,0,0"/>
              </StackPanel>
            </Border>
            <Border Grid.Column="1" Style="{StaticResource Panel}" Margin="0,0,0,12">
              <StackPanel>
                <StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xEDA2;" Foreground="#EE6C2B"/><TextBlock Text="  ทดสอบความเร็วดิสก์" Style="{StaticResource RowTitle}" FontSize="14.5"/></StackPanel>
                <TextBlock Text="เขียน/อ่านไฟล์ทดสอบโดยไม่ผ่าน cache — ใช้เช็คว่า SSD/HDD ช้าผิดปกติหรือไม่ (ไฟล์ทดสอบลบให้อัตโนมัติ)" Style="{StaticResource RowDesc}" Margin="0,3,0,8"/>
                <WrapPanel x:Name="BenchDrives"/>
                <WrapPanel Margin="0,2,0,0">
                  <RadioButton x:Name="bench_256" Content="ไฟล์ทดสอบ 256 MB" Style="{StaticResource Seg}" GroupName="benchsize" Tag="256" IsChecked="True"/>
                  <RadioButton x:Name="bench_1024" Content="1 GB (แม่นกว่า)" Style="{StaticResource Seg}" GroupName="benchsize" Tag="1024"/>
                </WrapPanel>
                <Button x:Name="BtnBench" Content="เริ่มทดสอบ" Style="{StaticResource Primary}" HorizontalAlignment="Left" Padding="22,8" Margin="0,4,0,10"/>
                <ProgressBar x:Name="BenchBar" Style="{StaticResource MiniBar}" Maximum="100" Visibility="Collapsed" Margin="0,0,0,8"/>
                <UniformGrid Columns="3">
                  <StackPanel><TextBlock Text="อ่านต่อเนื่อง" Style="{StaticResource Muted}"/><TextBlock x:Name="BenchRead" Text="–" FontSize="22" FontWeight="Bold" Foreground="##TITLEFG##"/></StackPanel>
                  <StackPanel><TextBlock Text="เขียนต่อเนื่อง" Style="{StaticResource Muted}"/><TextBlock x:Name="BenchWrite" Text="–" FontSize="22" FontWeight="Bold" Foreground="##TITLEFG##"/></StackPanel>
                  <StackPanel><TextBlock Text="อ่านสุ่ม 4K" Style="{StaticResource Muted}"/><TextBlock x:Name="BenchRand" Text="–" FontSize="22" FontWeight="Bold" Foreground="##TITLEFG##"/></StackPanel>
                </UniformGrid>
                <TextBlock x:Name="BenchVerdict" Style="{StaticResource Muted}" Margin="0,8,0,0"/>
              </StackPanel>
            </Border>
          </Grid>
          <Grid>
            <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
            <Border Style="{StaticResource Panel}" Margin="0,0,12,12">
              <StackPanel>
                <StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE950;" Foreground="#EE6C2B"/><TextBlock Text="  ทดสอบ CPU (Stress test)" Style="{StaticResource RowTitle}" FontSize="14.5"/></StackPanel>
                <TextBlock Text="ให้ CPU ทำงานเต็ม 100% ทุกคอร์ ดูว่าเครื่องค้าง/ดับ หรือความเร็วตกเพราะร้อน (Thermal throttling) หรือไม่" Style="{StaticResource RowDesc}" Margin="0,3,0,8"/>
                <WrapPanel>
                  <RadioButton x:Name="stress_30" Content="30 วินาที" Style="{StaticResource Seg}" GroupName="stresstime" Tag="30"/>
                  <RadioButton x:Name="stress_60" Content="1 นาที" Style="{StaticResource Seg}" GroupName="stresstime" Tag="60" IsChecked="True"/>
                  <RadioButton x:Name="stress_300" Content="5 นาที" Style="{StaticResource Seg}" GroupName="stresstime" Tag="300"/>
                </WrapPanel>
                <Button x:Name="BtnStress" Content="เริ่มทดสอบ CPU" Style="{StaticResource Primary}" HorizontalAlignment="Left" Padding="22,8" Margin="0,4,0,10"/>
                <UniformGrid Columns="3">
                  <StackPanel><TextBlock Text="การใช้งาน" Style="{StaticResource Muted}"/><TextBlock x:Name="StressCpu" Text="–" FontSize="20" FontWeight="Bold" Foreground="##TITLEFG##"/></StackPanel>
                  <StackPanel><TextBlock Text="ความเร็วจริง" Style="{StaticResource Muted}"/><TextBlock x:Name="StressMhz" Text="–" FontSize="20" FontWeight="Bold" Foreground="##TITLEFG##"/></StackPanel>
                  <StackPanel><TextBlock Text="อุณหภูมิ" Style="{StaticResource Muted}"/><TextBlock x:Name="StressTemp" Text="–" FontSize="20" FontWeight="Bold" Foreground="##TITLEFG##"/></StackPanel>
                </UniformGrid>
                <TextBlock x:Name="StressResult" Style="{StaticResource Muted}" Margin="0,8,0,0"/>
              </StackPanel>
            </Border>
            <Border Grid.Column="1" Style="{StaticResource Panel}" Margin="0,0,0,12">
              <StackPanel>
                <StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE964;" Foreground="#EE6C2B"/><TextBlock Text="  ทดสอบ RAM" Style="{StaticResource RowTitle}" FontSize="14.5"/></StackPanel>
                <TextBlock Text="ใช้ Windows Memory Diagnostic ตรวจ RAM — เครื่องจะรีสตาร์ทแล้วตรวจก่อนเข้า Windows (ประมาณ 10-20 นาที) ผลจะแสดงที่นี่หลังเปิดเครื่อง" Style="{StaticResource RowDesc}" Margin="0,3,0,10"/>
                <Button x:Name="BtnMemTest" Content="ตรวจ RAM (รีสตาร์ทเครื่อง)..." Style="{StaticResource Outline}" HorizontalAlignment="Left"/>
                <TextBlock x:Name="MemTestLast" Style="{StaticResource Body}" Margin="0,10,0,0"/>
              </StackPanel>
            </Border>
          </Grid>
          <Border Style="{StaticResource Panel}" Margin="0,0,0,12">
            <StackPanel>
              <Grid>
                <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                <StackPanel Orientation="Horizontal" VerticalAlignment="Center"><TextBlock Style="{StaticResource Ico}" Text="&#xE772;" Foreground="#EE6C2B"/><TextBlock Text="  อุปกรณ์ที่มีปัญหา / ไม่มีไดรเวอร์" Style="{StaticResource RowTitle}" FontSize="14.5"/></StackPanel>
                <StackPanel Grid.Column="1" Orientation="Horizontal">
                  <Button x:Name="BtnDevScan" Content="ค้นหาอุปกรณ์ใหม่" Style="{StaticResource Secondary}" Margin="0,0,8,0"/>
                  <Button x:Name="BtnDevMgr" Content="Device Manager" Style="{StaticResource Secondary}"/>
                </StackPanel>
              </Grid>
              <TextBlock Text="คัดลอก Hardware ID ไปค้นหาไดรเวอร์ที่ถูกรุ่นได้ (ใช้ได้แม้ไม่รู้ยี่ห้ออุปกรณ์)" Style="{StaticResource RowDesc}" Margin="0,3,0,8"/>
              <StackPanel x:Name="DevList"/>
            </StackPanel>
          </Border>
        </StackPanel>
      </ScrollViewer>

      <!-- ============ ย้าย / สำรองข้อมูล (งานช่าง) ============ -->
      <Grid x:Name="Page_backup" Visibility="Collapsed">
        <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
        <Grid Grid.Row="0">
          <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
          <StackPanel>
            <TextBlock Text="ย้าย / สำรองข้อมูล" Style="{StaticResource PageTitle}"/>
            <TextBlock Text="สำรองไฟล์ลูกค้า บุ๊กมาร์ก รหัส Wi-Fi และไดรเวอร์ ลง USB ก่อนลง Windows ใหม่ แล้วกู้กลับได้ในคลิกเดียว" Style="{StaticResource PageSub}"/>
          </StackPanel>
          <StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Top" Margin="0,6,6,0">
            <RadioButton x:Name="bk_backup" Content="สำรองข้อมูล" Style="{StaticResource Seg}" GroupName="bkmode" IsChecked="True"/>
            <RadioButton x:Name="bk_restore" Content="กู้คืนข้อมูล" Style="{StaticResource Seg}" GroupName="bkmode"/>
          </StackPanel>
        </Grid>
        <ScrollViewer Grid.Row="1" VerticalScrollBarVisibility="Auto">
          <StackPanel Margin="0,0,6,0">
            <StackPanel x:Name="BkBackupPanel">
              <Border Style="{StaticResource Panel}" Margin="0,0,0,12">
                <StackPanel>
                  <TextBlock Text="1. เลือกบัญชีผู้ใช้ที่จะสำรอง" Style="{StaticResource RowTitle}"/>
                  <WrapPanel x:Name="BkUsers" Margin="0,8,0,0"/>
                </StackPanel>
              </Border>
              <TextBlock Text="2. เลือกสิ่งที่จะสำรอง" Style="{StaticResource Section}" Margin="2,0,0,8"/>
              <StackPanel x:Name="BkItems"/>
              <Border Style="{StaticResource Panel}" Margin="0,4,0,12">
                <StackPanel>
                  <TextBlock Text="3. เลือกปลายทาง (แนะนำ USB / External HDD)" Style="{StaticResource RowTitle}"/>
                  <Grid Margin="0,8,0,0">
                    <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                    <TextBox x:Name="BkDest" Style="{StaticResource Input}" IsReadOnly="True"/>
                    <Button x:Name="BtnBkDest" Grid.Column="1" Content="เลือกปลายทาง..." Style="{StaticResource Secondary}" Margin="8,0,0,0"/>
                  </Grid>
                  <TextBlock x:Name="BkDestInfo" Style="{StaticResource Muted}" Margin="2,6,0,0"/>
                </StackPanel>
              </Border>
            </StackPanel>
            <StackPanel x:Name="BkRestorePanel" Visibility="Collapsed">
              <Border Style="{StaticResource Panel}" Margin="0,0,0,12">
                <StackPanel>
                  <TextBlock Text="1. เลือกโฟลเดอร์สำรองที่ทำไว้ (SCPclear-Backup-...)" Style="{StaticResource RowTitle}"/>
                  <Grid Margin="0,8,0,0">
                    <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                    <TextBox x:Name="BkSrc" Style="{StaticResource Input}" IsReadOnly="True"/>
                    <Button x:Name="BtnBkSrc" Grid.Column="1" Content="เลือกโฟลเดอร์สำรอง..." Style="{StaticResource Secondary}" Margin="8,0,0,0"/>
                  </Grid>
                  <TextBlock x:Name="BkSrcInfo" Style="{StaticResource Muted}" Margin="2,6,0,0"/>
                </StackPanel>
              </Border>
              <TextBlock Text="2. เลือกสิ่งที่จะกู้คืน (กู้คืนให้ผู้ใช้ที่เปิดโปรแกรมอยู่ตอนนี้)" Style="{StaticResource Section}" Margin="2,0,0,8"/>
              <StackPanel x:Name="BkRestoreItems"/>
            </StackPanel>
          </StackPanel>
        </ScrollViewer>
        <Border Grid.Row="2" Style="{StaticResource Panel}" Margin="0,10,6,0" Padding="18,12">
          <Grid>
            <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
            <StackPanel VerticalAlignment="Center" Margin="0,0,12,0">
              <TextBlock x:Name="BkStatus" Text="เลือกรายการแล้วกดเริ่ม" Style="{StaticResource Body}" FontWeight="SemiBold" TextTrimming="CharacterEllipsis" TextWrapping="NoWrap"/>
              <ProgressBar x:Name="BkBar" Style="{StaticResource MiniBar}" Maximum="100" Margin="0,6,0,0" Visibility="Collapsed"/>
            </StackPanel>
            <StackPanel Grid.Column="1" Orientation="Horizontal">
              <Button x:Name="BtnBkOpen" Content="เปิดโฟลเดอร์" Style="{StaticResource Link}" Visibility="Collapsed"/>
              <Button x:Name="BtnBkCancel" Content="หยุด" Style="{StaticResource Secondary}" Margin="0,0,8,0" Visibility="Collapsed"/>
              <Button x:Name="BtnBkRun" Content="เริ่มสำรองข้อมูล" Style="{StaticResource Primary}"/>
            </StackPanel>
          </Grid>
        </Border>
      </Grid>

      <!-- ============ ลงโปรแกรม (winget) ============ -->
      <Grid x:Name="Page_install" Visibility="Collapsed">
        <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
        <StackPanel Grid.Row="0">
          <TextBlock Text="ลงโปรแกรม" Style="{StaticResource PageTitle}"/>
          <TextBlock Text="ติ๊กเลือกโปรแกรม แล้วกดติดตั้ง — ดาวน์โหลดเวอร์ชันล่าสุดจากแหล่งทางการผ่าน winget แบบเงียบ ไม่ต้องกด Next (ต้องมีอินเทอร์เน็ต)" Style="{StaticResource PageSub}"/>
        </StackPanel>
        <Grid Grid.Row="1" Margin="0,0,6,10">
          <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
          <WrapPanel VerticalAlignment="Center">
            <Button x:Name="BtnInsBasic" Content="เลือกชุดพื้นฐาน" Style="{StaticResource Chip}"/>
            <Button x:Name="BtnInsNone" Content="ล้างที่เลือก" Style="{StaticResource Chip}"/>
            <Button x:Name="BtnInsCheck" Content="ตรวจว่าติดตั้งอะไรไปแล้ว" Style="{StaticResource Chip}"/>
            <Button x:Name="BtnInsUpgrade" Content="อัปเดตโปรแกรมทั้งหมดในเครื่อง" Style="{StaticResource Chip}"/>
          </WrapPanel>
          <Button x:Name="BtnInsRun" Grid.Column="1" Content="ติดตั้งที่เลือก" Style="{StaticResource Primary}" VerticalAlignment="Top"/>
        </Grid>
        <ScrollViewer Grid.Row="2" VerticalScrollBarVisibility="Auto">
          <StackPanel x:Name="InsGroups" Margin="0,0,6,0"/>
        </ScrollViewer>
        <Border Grid.Row="3" Style="{StaticResource Panel}" Margin="0,10,6,0" Padding="14,10">
          <StackPanel>
            <Grid>
              <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
              <TextBlock x:Name="InsStatus" Text="พร้อมติดตั้ง" Style="{StaticResource Body}" FontWeight="SemiBold" VerticalAlignment="Center" TextTrimming="CharacterEllipsis" TextWrapping="NoWrap"/>
              <Button x:Name="BtnInsStop" Grid.Column="1" Content="หยุดหลังตัวนี้" Style="{StaticResource Secondary}" Visibility="Collapsed"/>
            </Grid>
            <Border Background="##LOGBG##" BorderBrush="##LOGBORDER##" BorderThickness="1" CornerRadius="10" Margin="0,8,0,0">
              <TextBox x:Name="InsOut" IsReadOnly="True" BorderThickness="0" Background="Transparent" Foreground="##LOGFG##" FontFamily="Consolas" FontSize="11" Height="110" VerticalScrollBarVisibility="Auto" TextWrapping="Wrap" Padding="10,6"/>
            </Border>
          </StackPanel>
        </Border>
      </Grid>

      <!-- ============ 7) PDF Tools ============ -->
      <Grid x:Name="Page_pdf" Visibility="Collapsed">
        <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
        <StackPanel Grid.Row="0">
          <TextBlock Text="PDF Tools" Style="{StaticResource PageTitle}"/>
          <TextBlock Text="รวม แยก จัดเรียง หมุน ลบหน้า แปลงรูป และบีบอัดไฟล์ PDF — ทำงานในเครื่อง ไม่ต้องอัปโหลดขึ้นเว็บ ไฟล์ต้นฉบับไม่ถูกแก้ไข" Style="{StaticResource PageSub}"/>
        </StackPanel>
        <Border Grid.Row="1" x:Name="PdfMissing" Visibility="Collapsed" Background="#FDECEC" CornerRadius="12" Padding="14,10" Margin="0,0,6,12">
          <TextBlock x:Name="PdfMissingText" Foreground="#B42318" FontSize="12.5" TextWrapping="Wrap"/>
        </Border>
        <UniformGrid Grid.Row="2" Columns="4" Margin="0,0,0,4">
          <RadioButton x:Name="pt_merge" Style="{StaticResource Tile}" Tag="merge"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE8C8;" Foreground="#EE6C2B" FontSize="18"/><StackPanel Margin="11,0,0,0"><TextBlock Text="Merge PDF" Style="{StaticResource RowTitle}"/><TextBlock Text="รวมหลายไฟล์เป็นไฟล์เดียว" Style="{StaticResource RowDesc}" FontSize="11"/></StackPanel></StackPanel></RadioButton>
          <RadioButton x:Name="pt_split" Style="{StaticResource Tile}" Tag="split"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE8C6;" Foreground="#EE6C2B" FontSize="18"/><StackPanel Margin="11,0,0,0"><TextBlock Text="Split PDF" Style="{StaticResource RowTitle}"/><TextBlock Text="แยกหน้าเป็นหลายไฟล์" Style="{StaticResource RowDesc}" FontSize="11"/></StackPanel></StackPanel></RadioButton>
          <RadioButton x:Name="pt_reorder" Style="{StaticResource Tile}" Tag="reorder"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE8CB;" Foreground="#EE6C2B" FontSize="18"/><StackPanel Margin="11,0,0,0"><TextBlock Text="จัดเรียงหน้า" Style="{StaticResource RowTitle}"/><TextBlock Text="เปลี่ยนลำดับหน้าเอกสาร" Style="{StaticResource RowDesc}" FontSize="11"/></StackPanel></StackPanel></RadioButton>
          <RadioButton x:Name="pt_rotate" Style="{StaticResource Tile}" Tag="rotate"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE7AD;" Foreground="#EE6C2B" FontSize="18"/><StackPanel Margin="11,0,0,0"><TextBlock Text="Rotate PDF" Style="{StaticResource RowTitle}"/><TextBlock Text="หมุนหน้าเอกสาร" Style="{StaticResource RowDesc}" FontSize="11"/></StackPanel></StackPanel></RadioButton>
          <RadioButton x:Name="pt_delete" Style="{StaticResource Tile}" Tag="delete"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE74D;" Foreground="#EE6C2B" FontSize="18"/><StackPanel Margin="11,0,0,0"><TextBlock Text="Delete Pages" Style="{StaticResource RowTitle}"/><TextBlock Text="ลบหน้าที่ไม่ต้องการ" Style="{StaticResource RowDesc}" FontSize="11"/></StackPanel></StackPanel></RadioButton>
          <RadioButton x:Name="pt_img2pdf" Style="{StaticResource Tile}" Tag="img2pdf"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE8B9;" Foreground="#EE6C2B" FontSize="18"/><StackPanel Margin="11,0,0,0"><TextBlock Text="Images to PDF" Style="{StaticResource RowTitle}"/><TextBlock Text="รวมรูปภาพเป็น PDF" Style="{StaticResource RowDesc}" FontSize="11"/></StackPanel></StackPanel></RadioButton>
          <RadioButton x:Name="pt_pdf2img" Style="{StaticResource Tile}" Tag="pdf2img"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE91B;" Foreground="#EE6C2B" FontSize="18"/><StackPanel Margin="11,0,0,0"><TextBlock Text="PDF to Images" Style="{StaticResource RowTitle}"/><TextBlock Text="แปลงหน้า PDF เป็นรูป" Style="{StaticResource RowDesc}" FontSize="11"/></StackPanel></StackPanel></RadioButton>
          <RadioButton x:Name="pt_compress" Style="{StaticResource Tile}" Tag="compress"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE73F;" Foreground="#EE6C2B" FontSize="18"/><StackPanel Margin="11,0,0,0"><TextBlock Text="PDF Compressor" Style="{StaticResource RowTitle}"/><TextBlock Text="บีบอัดลดขนาดไฟล์" Style="{StaticResource RowDesc}" FontSize="11"/></StackPanel></StackPanel></RadioButton>
          <RadioButton x:Name="pt_protect" Style="{StaticResource Tile}" Tag="protect"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE72E;" Foreground="#EE6C2B" FontSize="18"/><StackPanel Margin="11,0,0,0"><TextBlock Text="รหัสผ่าน PDF" Style="{StaticResource RowTitle}"/><TextBlock Text="ใส่ หรือ ปลดรหัสผ่าน" Style="{StaticResource RowDesc}" FontSize="11"/></StackPanel></StackPanel></RadioButton>
          <RadioButton x:Name="pt_watermark" Style="{StaticResource Tile}" Tag="watermark"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE8D2;" Foreground="#EE6C2B" FontSize="18"/><StackPanel Margin="11,0,0,0"><TextBlock Text="ลายน้ำ" Style="{StaticResource RowTitle}"/><TextBlock Text="ใส่ข้อความลายน้ำทุกหน้า" Style="{StaticResource RowDesc}" FontSize="11"/></StackPanel></StackPanel></RadioButton>
          <RadioButton x:Name="pt_pagenum" Style="{StaticResource Tile}" Tag="pagenum"><StackPanel Orientation="Horizontal"><TextBlock Style="{StaticResource Ico}" Text="&#xE7C3;" Foreground="#EE6C2B" FontSize="18"/><StackPanel Margin="11,0,0,0"><TextBlock Text="ใส่เลขหน้า" Style="{StaticResource RowTitle}"/><TextBlock Text="เลขหน้าท้าย/หัวกระดาษ" Style="{StaticResource RowDesc}" FontSize="11"/></StackPanel></StackPanel></RadioButton>
        </UniformGrid>
        <Border Grid.Row="3" Style="{StaticResource Panel}" Margin="0,0,6,0">
          <Grid>
            <!-- Merge -->
            <Grid x:Name="PdfP_merge">
              <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
              <StackPanel><TextBlock Text="รวมไฟล์ PDF" Style="{StaticResource RowTitle}" FontSize="15"/><TextBlock Text="เพิ่มไฟล์แล้วจัดลำดับ — ไฟล์ด้านบนจะอยู่ก่อน (ลากไฟล์มาวางในกล่องได้)" Style="{StaticResource RowDesc}" Margin="0,2,0,10"/></StackPanel>
              <Grid Grid.Row="1">
                <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                <ListBox x:Name="MergeList" Style="{StaticResource FileList}" AllowDrop="True"/>
                <StackPanel Grid.Column="1" Margin="10,0,0,0" Width="130">
                  <Button x:Name="BtnMergeAdd" Content="+ เพิ่มไฟล์" Style="{StaticResource Secondary}" Margin="0,0,0,6"/>
                  <Button x:Name="BtnMergeUp" Content="▲ เลื่อนขึ้น" Style="{StaticResource Secondary}" Margin="0,0,0,6"/>
                  <Button x:Name="BtnMergeDown" Content="▼ เลื่อนลง" Style="{StaticResource Secondary}" Margin="0,0,0,6"/>
                  <Button x:Name="BtnMergeRemove" Content="เอาออก" Style="{StaticResource Secondary}" Margin="0,0,0,6"/>
                  <Button x:Name="BtnMergeClear" Content="ล้างทั้งหมด" Style="{StaticResource Secondary}"/>
                </StackPanel>
              </Grid>
              <Button Grid.Row="2" x:Name="BtnMergeRun" Content="รวมไฟล์ PDF" Style="{StaticResource Primary}" HorizontalAlignment="Left" Margin="0,12,0,0"/>
            </Grid>
            <!-- Split -->
            <StackPanel x:Name="PdfP_split" Visibility="Collapsed">
              <TextBlock Text="แยกไฟล์ PDF" Style="{StaticResource RowTitle}" FontSize="15"/>
              <TextBlock Text="แยกทุกหน้าเป็นไฟล์ละหน้า หรือกำหนดช่วงหน้าเอง (แต่ละช่วงคั่นด้วยจุลภาค = 1 ไฟล์)" Style="{StaticResource RowDesc}" Margin="0,2,0,12"/>
              <Grid>
                <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                <TextBox x:Name="SplitFile" Style="{StaticResource Input}" IsReadOnly="True" AllowDrop="True"/>
                <Button x:Name="BtnSplitPick" Grid.Column="1" Content="เลือกไฟล์ PDF..." Style="{StaticResource Secondary}" Margin="8,0,0,0"/>
              </Grid>
              <TextBlock x:Name="SplitInfo" Style="{StaticResource Muted}" Margin="2,6,0,12"/>
              <WrapPanel>
                <RadioButton x:Name="split_all" Content="แยกทุกหน้า (หน้าละไฟล์)" Style="{StaticResource Seg}" GroupName="splitmode" IsChecked="True"/>
                <RadioButton x:Name="split_range" Content="กำหนดช่วงหน้าเอง" Style="{StaticResource Seg}" GroupName="splitmode"/>
              </WrapPanel>
              <StackPanel x:Name="SplitRangeBox" Visibility="Collapsed" Margin="0,6,0,0">
                <TextBox x:Name="SplitRanges" Style="{StaticResource Input}" Width="360" HorizontalAlignment="Left"/>
                <TextBlock Text="ตัวอย่าง: 1-3, 5, 8-10  →  ได้ 3 ไฟล์ (หน้า 1-3, หน้า 5, หน้า 8-10)" Style="{StaticResource Muted}" Margin="2,6,0,0"/>
              </StackPanel>
              <Button x:Name="BtnSplitRun" Content="แยกไฟล์ PDF" Style="{StaticResource Primary}" HorizontalAlignment="Left" Margin="0,16,0,0"/>
            </StackPanel>
            <!-- จัดเรียง / หมุน / ลบหน้า -->
            <Grid x:Name="PdfP_org" Visibility="Collapsed">
              <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
              <StackPanel><TextBlock x:Name="OrgTitle" Text="จัดเรียงหน้า" Style="{StaticResource RowTitle}" FontSize="15"/><TextBlock x:Name="OrgDesc" Style="{StaticResource RowDesc}" Margin="0,2,0,10"/></StackPanel>
              <Grid Grid.Row="1">
                <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                <TextBox x:Name="OrgFile" Style="{StaticResource Input}" IsReadOnly="True" AllowDrop="True"/>
                <Button x:Name="BtnOrgPick" Grid.Column="1" Content="เลือกไฟล์ PDF..." Style="{StaticResource Secondary}" Margin="8,0,0,0"/>
              </Grid>
              <WrapPanel Grid.Row="2" Margin="0,10,0,4">
                <WrapPanel x:Name="OrgMoveGrp">
                  <Button x:Name="BtnOrgLeft" Content="◀ เลื่อนไปก่อน" Style="{StaticResource Chip}"/>
                  <Button x:Name="BtnOrgRight" Content="เลื่อนไปหลัง ▶" Style="{StaticResource Chip}"/>
                  <Button x:Name="BtnOrgFirst" Content="ไปหน้าแรก" Style="{StaticResource Chip}"/>
                  <Button x:Name="BtnOrgLast" Content="ไปท้ายสุด" Style="{StaticResource Chip}"/>
                  <Button x:Name="BtnOrgReverse" Content="กลับลำดับทั้งหมด" Style="{StaticResource Chip}"/>
                </WrapPanel>
                <WrapPanel x:Name="OrgRotGrp">
                  <Button x:Name="BtnRotL" Content="⟲ หมุนซ้าย 90°" Style="{StaticResource Chip}"/>
                  <Button x:Name="BtnRotR" Content="⟳ หมุนขวา 90°" Style="{StaticResource Chip}"/>
                  <Button x:Name="BtnRot180" Content="หมุน 180°" Style="{StaticResource Chip}"/>
                </WrapPanel>
                <WrapPanel x:Name="OrgDelGrp">
                  <Button x:Name="BtnOrgDel" Content="ลบหน้าที่เลือก" Style="{StaticResource Chip}"/>
                  <Button x:Name="BtnOrgUndel" Content="คืนหน้าที่ลบทั้งหมด" Style="{StaticResource Chip}"/>
                </WrapPanel>
                <Button x:Name="BtnOrgSelAll" Content="เลือกทุกหน้า" Style="{StaticResource Chip}"/>
                <Button x:Name="BtnOrgSelNone" Content="ยกเลิกเลือก" Style="{StaticResource Chip}"/>
              </WrapPanel>
              <ScrollViewer Grid.Row="3" VerticalScrollBarVisibility="Auto">
                <WrapPanel x:Name="OrgPages"/>
              </ScrollViewer>
              <Grid Grid.Row="4" Margin="0,10,0,0">
                <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                <Button x:Name="BtnOrgSave" Content="บันทึกเป็นไฟล์ใหม่" Style="{StaticResource Primary}" IsEnabled="False"/>
                <TextBlock x:Name="OrgHint" Grid.Column="1" Style="{StaticResource Muted}" VerticalAlignment="Center" Margin="14,0,0,0" Text="คลิกที่หน้าเพื่อเลือก/ยกเลิก (เลือกได้หลายหน้า)"/>
              </Grid>
            </Grid>
            <!-- Images to PDF -->
            <Grid x:Name="PdfP_img" Visibility="Collapsed">
              <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
              <StackPanel><TextBlock Text="รวมรูปภาพเป็น PDF" Style="{StaticResource RowTitle}" FontSize="15"/><TextBlock Text="รองรับ JPG, PNG, BMP, GIF, TIFF — รูปละ 1 หน้า เรียงตามลำดับในรายการ (หมุนรูปจากมือถือให้อัตโนมัติ)" Style="{StaticResource RowDesc}" Margin="0,2,0,10"/></StackPanel>
              <Grid Grid.Row="1">
                <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                <ListBox x:Name="ImgList" Style="{StaticResource FileList}" AllowDrop="True"/>
                <StackPanel Grid.Column="1" Margin="10,0,0,0" Width="130">
                  <Button x:Name="BtnImgAdd" Content="+ เพิ่มรูป" Style="{StaticResource Secondary}" Margin="0,0,0,6"/>
                  <Button x:Name="BtnImgUp" Content="▲ เลื่อนขึ้น" Style="{StaticResource Secondary}" Margin="0,0,0,6"/>
                  <Button x:Name="BtnImgDown" Content="▼ เลื่อนลง" Style="{StaticResource Secondary}" Margin="0,0,0,6"/>
                  <Button x:Name="BtnImgRemove" Content="เอาออก" Style="{StaticResource Secondary}" Margin="0,0,0,6"/>
                  <Button x:Name="BtnImgClear" Content="ล้างทั้งหมด" Style="{StaticResource Secondary}"/>
                </StackPanel>
              </Grid>
              <WrapPanel Grid.Row="2" Margin="0,12,0,0" VerticalAlignment="Center">
                <Button x:Name="BtnImgRun" Content="สร้างไฟล์ PDF" Style="{StaticResource Primary}" Margin="0,0,16,0"/>
                <TextBlock Text="ขนาดหน้า:" Style="{StaticResource Muted}" VerticalAlignment="Center" Margin="0,0,8,6"/>
                <RadioButton x:Name="img_a4" Content="A4 (จัดกึ่งกลาง)" Style="{StaticResource Seg}" GroupName="imgsize" IsChecked="True" VerticalAlignment="Center"/>
                <RadioButton x:Name="img_fit" Content="เท่าขนาดรูป" Style="{StaticResource Seg}" GroupName="imgsize" VerticalAlignment="Center"/>
              </WrapPanel>
            </Grid>
            <!-- PDF to Images -->
            <StackPanel x:Name="PdfP_toimg" Visibility="Collapsed">
              <TextBlock Text="แปลง PDF เป็นรูปภาพ" Style="{StaticResource RowTitle}" FontSize="15"/>
              <TextBlock Text="แปลงทุกหน้าเป็นไฟล์รูป แล้วบันทึกลงโฟลเดอร์ใหม่ข้างไฟล์ต้นฉบับ" Style="{StaticResource RowDesc}" Margin="0,2,0,12"/>
              <Grid>
                <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                <TextBox x:Name="ToImgFile" Style="{StaticResource Input}" IsReadOnly="True" AllowDrop="True"/>
                <Button x:Name="BtnToImgPick" Grid.Column="1" Content="เลือกไฟล์ PDF..." Style="{StaticResource Secondary}" Margin="8,0,0,0"/>
              </Grid>
              <TextBlock x:Name="ToImgInfo" Style="{StaticResource Muted}" Margin="2,6,0,12"/>
              <TextBlock Text="รูปแบบไฟล์" Style="{StaticResource RowTitle}" Margin="0,0,0,6"/>
              <WrapPanel>
                <RadioButton x:Name="toimg_png" Content="PNG (คมชัด)" Style="{StaticResource Seg}" GroupName="toimgfmt" IsChecked="True"/>
                <RadioButton x:Name="toimg_jpg" Content="JPG (ไฟล์เล็ก)" Style="{StaticResource Seg}" GroupName="toimgfmt"/>
              </WrapPanel>
              <TextBlock Text="ความละเอียด" Style="{StaticResource RowTitle}" Margin="0,8,0,6"/>
              <WrapPanel>
                <RadioButton x:Name="dpi_96"  Content="96 DPI (หน้าจอ)" Style="{StaticResource Seg}" GroupName="toimgdpi" Tag="96"/>
                <RadioButton x:Name="dpi_150" Content="150 DPI (แนะนำ)" Style="{StaticResource Seg}" GroupName="toimgdpi" Tag="150" IsChecked="True"/>
                <RadioButton x:Name="dpi_200" Content="200 DPI" Style="{StaticResource Seg}" GroupName="toimgdpi" Tag="200"/>
                <RadioButton x:Name="dpi_300" Content="300 DPI (พิมพ์)" Style="{StaticResource Seg}" GroupName="toimgdpi" Tag="300"/>
              </WrapPanel>
              <Button x:Name="BtnToImgRun" Content="แปลงเป็นรูปภาพ" Style="{StaticResource Primary}" HorizontalAlignment="Left" Margin="0,16,0,0"/>
            </StackPanel>
            <!-- Compressor -->
            <StackPanel x:Name="PdfP_compress" Visibility="Collapsed">
              <TextBlock Text="บีบอัดไฟล์ PDF" Style="{StaticResource RowTitle}" FontSize="15"/>
              <TextBlock Text="ลดขนาดไฟล์เพื่อส่งอีเมล/อัปโหลด — ไฟล์ต้นฉบับยังอยู่ครบ" Style="{StaticResource RowDesc}" Margin="0,2,0,12"/>
              <Grid>
                <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                <TextBox x:Name="CmpFile" Style="{StaticResource Input}" IsReadOnly="True" AllowDrop="True"/>
                <Button x:Name="BtnCmpPick" Grid.Column="1" Content="เลือกไฟล์ PDF..." Style="{StaticResource Secondary}" Margin="8,0,0,0"/>
              </Grid>
              <TextBlock x:Name="CmpInfo" Style="{StaticResource Muted}" Margin="2,6,0,12"/>
              <TextBlock Text="ระดับการบีบอัด" Style="{StaticResource RowTitle}" Margin="0,0,0,6"/>
              <WrapPanel>
                <RadioButton x:Name="cmp_low" Content="ปกติ (คงคุณภาพเดิม)" Style="{StaticResource Seg}" GroupName="cmplvl" IsChecked="True"/>
                <RadioButton x:Name="cmp_med" Content="ลดขนาดมาก (150 DPI)" Style="{StaticResource Seg}" GroupName="cmplvl"/>
                <RadioButton x:Name="cmp_high" Content="เล็กที่สุด (100 DPI)" Style="{StaticResource Seg}" GroupName="cmplvl"/>
              </WrapPanel>
              <TextBlock x:Name="CmpDesc" Style="{StaticResource Muted}" Margin="2,4,0,0"/>
              <Button x:Name="BtnCmpRun" Content="บีบอัด PDF" Style="{StaticResource Primary}" HorizontalAlignment="Left" Margin="0,16,0,0"/>
            </StackPanel>
            <!-- รหัสผ่าน -->
            <StackPanel x:Name="PdfP_protect" Visibility="Collapsed">
              <TextBlock Text="ใส่ / ปลดรหัสผ่าน PDF" Style="{StaticResource RowTitle}" FontSize="15"/>
              <TextBlock Text="ใส่รหัสผ่านก่อนส่งเอกสารสำคัญ หรือปลดรหัสออกจากไฟล์ที่รู้รหัสอยู่แล้ว — บันทึกเป็นไฟล์ใหม่" Style="{StaticResource RowDesc}" Margin="0,2,0,12"/>
              <Grid>
                <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                <TextBox x:Name="ProtFile" Style="{StaticResource Input}" IsReadOnly="True" AllowDrop="True"/>
                <Button x:Name="BtnProtPick" Grid.Column="1" Content="เลือกไฟล์ PDF..." Style="{StaticResource Secondary}" Margin="8,0,0,0"/>
              </Grid>
              <TextBlock x:Name="ProtInfo" Style="{StaticResource Muted}" Margin="2,6,0,12"/>
              <WrapPanel>
                <RadioButton x:Name="prot_add" Content="ใส่รหัสผ่าน" Style="{StaticResource Seg}" GroupName="protmode" IsChecked="True"/>
                <RadioButton x:Name="prot_remove" Content="ปลดรหัสผ่าน" Style="{StaticResource Seg}" GroupName="protmode"/>
              </WrapPanel>
              <Grid Margin="0,8,0,0" MaxWidth="560" HorizontalAlignment="Left">
                <Grid.ColumnDefinitions><ColumnDefinition Width="150"/><ColumnDefinition Width="260"/></Grid.ColumnDefinitions>
                <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
                <TextBlock x:Name="ProtPwLabel" Text="รหัสผ่าน" Style="{StaticResource RowTitle}" VerticalAlignment="Center"/>
                <Border Grid.Column="1" Background="##INPUTBG##" BorderBrush="##INPUTBORDER##" BorderThickness="1" CornerRadius="10" Padding="8,7"><PasswordBox x:Name="ProtPw1" BorderThickness="0" Background="Transparent" Foreground="##BODYFG##" CaretBrush="##BODYFG##" FontSize="13"/></Border>
                <TextBlock x:Name="ProtPw2Label" Grid.Row="1" Text="ยืนยันรหัสผ่าน" Style="{StaticResource RowTitle}" VerticalAlignment="Center" Margin="0,8,0,0"/>
                <Border x:Name="ProtPw2Box" Grid.Row="1" Grid.Column="1" Margin="0,8,0,0" Background="##INPUTBG##" BorderBrush="##INPUTBORDER##" BorderThickness="1" CornerRadius="10" Padding="8,7"><PasswordBox x:Name="ProtPw2" BorderThickness="0" Background="Transparent" Foreground="##BODYFG##" CaretBrush="##BODYFG##" FontSize="13"/></Border>
              </Grid>
              <WrapPanel x:Name="ProtOpts" Margin="0,12,0,0">
                <CheckBox x:Name="ProtAllowPrint" Style="{StaticResource Toggle}" IsChecked="True" VerticalAlignment="Center"/>
                <TextBlock Text="อนุญาตให้พิมพ์" Style="{StaticResource Body}" VerticalAlignment="Center" Margin="8,0,20,0"/>
                <CheckBox x:Name="ProtAllowCopy" Style="{StaticResource Toggle}" VerticalAlignment="Center"/>
                <TextBlock Text="อนุญาตให้คัดลอกข้อความ" Style="{StaticResource Body}" VerticalAlignment="Center" Margin="8,0,0,0"/>
              </WrapPanel>
              <Button x:Name="BtnProtRun" Content="ใส่รหัสผ่าน" Style="{StaticResource Primary}" HorizontalAlignment="Left" Margin="0,16,0,0"/>
            </StackPanel>
            <!-- ลายน้ำ -->
            <StackPanel x:Name="PdfP_watermark" Visibility="Collapsed">
              <TextBlock Text="ใส่ลายน้ำ" Style="{StaticResource RowTitle}" FontSize="15"/>
              <TextBlock Text="ใส่ข้อความลายน้ำกลางทุกหน้า เช่น ห้ามเผยแพร่, สำเนา, ใช้ภายในเท่านั้น — รองรับภาษาไทย" Style="{StaticResource RowDesc}" Margin="0,2,0,12"/>
              <Grid>
                <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                <TextBox x:Name="WmFile" Style="{StaticResource Input}" IsReadOnly="True" AllowDrop="True"/>
                <Button x:Name="BtnWmPick" Grid.Column="1" Content="เลือกไฟล์ PDF..." Style="{StaticResource Secondary}" Margin="8,0,0,0"/>
              </Grid>
              <TextBlock x:Name="WmInfo" Style="{StaticResource Muted}" Margin="2,6,0,12"/>
              <TextBlock Text="ข้อความลายน้ำ" Style="{StaticResource RowTitle}" Margin="0,0,0,6"/>
              <TextBox x:Name="WmText" Style="{StaticResource Input}" Text="ห้ามเผยแพร่" Width="360" HorizontalAlignment="Left"/>
              <WrapPanel Margin="0,10,0,0">
                <TextBlock Text="สี" Style="{StaticResource Muted}" VerticalAlignment="Center" Margin="0,0,8,6"/>
                <RadioButton x:Name="wm_gray" Content="เทา" Style="{StaticResource Seg}" GroupName="wmcolor" IsChecked="True" Tag="128,128,128"/>
                <RadioButton x:Name="wm_red" Content="แดง" Style="{StaticResource Seg}" GroupName="wmcolor" Tag="229,72,77"/>
                <RadioButton x:Name="wm_blue" Content="น้ำเงิน" Style="{StaticResource Seg}" GroupName="wmcolor" Tag="37,99,235"/>
                <TextBlock Text="ความเข้ม" Style="{StaticResource Muted}" VerticalAlignment="Center" Margin="14,0,8,6"/>
                <RadioButton x:Name="wm_o15" Content="จาง" Style="{StaticResource Seg}" GroupName="wmop" Tag="0.15"/>
                <RadioButton x:Name="wm_o30" Content="กลาง" Style="{StaticResource Seg}" GroupName="wmop" Tag="0.3" IsChecked="True"/>
                <RadioButton x:Name="wm_o50" Content="เข้ม" Style="{StaticResource Seg}" GroupName="wmop" Tag="0.5"/>
                <TextBlock Text="แนว" Style="{StaticResource Muted}" VerticalAlignment="Center" Margin="14,0,8,6"/>
                <RadioButton x:Name="wm_diag" Content="ทแยง" Style="{StaticResource Seg}" GroupName="wmdir" IsChecked="True"/>
                <RadioButton x:Name="wm_horz" Content="แนวนอน" Style="{StaticResource Seg}" GroupName="wmdir"/>
              </WrapPanel>
              <Button x:Name="BtnWmRun" Content="ใส่ลายน้ำ" Style="{StaticResource Primary}" HorizontalAlignment="Left" Margin="0,14,0,0"/>
            </StackPanel>
            <!-- เลขหน้า -->
            <StackPanel x:Name="PdfP_pagenum" Visibility="Collapsed">
              <TextBlock Text="ใส่เลขหน้า" Style="{StaticResource RowTitle}" FontSize="15"/>
              <TextBlock Text="ใส่เลขหน้าให้ทุกหน้าอัตโนมัติ (รองรับหน้าที่หมุนแนวนอน)" Style="{StaticResource RowDesc}" Margin="0,2,0,12"/>
              <Grid>
                <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                <TextBox x:Name="PnFile" Style="{StaticResource Input}" IsReadOnly="True" AllowDrop="True"/>
                <Button x:Name="BtnPnPick" Grid.Column="1" Content="เลือกไฟล์ PDF..." Style="{StaticResource Secondary}" Margin="8,0,0,0"/>
              </Grid>
              <TextBlock x:Name="PnInfo" Style="{StaticResource Muted}" Margin="2,6,0,12"/>
              <TextBlock Text="รูปแบบ" Style="{StaticResource RowTitle}" Margin="0,0,0,6"/>
              <WrapPanel>
                <RadioButton x:Name="pn_f1" Content="1" Style="{StaticResource Seg}" GroupName="pnfmt" Tag="{}{n}"/>
                <RadioButton x:Name="pn_f2" Content="หน้า 1" Style="{StaticResource Seg}" GroupName="pnfmt" Tag="หน้า {n}"/>
                <RadioButton x:Name="pn_f3" Content="1 / 10" Style="{StaticResource Seg}" GroupName="pnfmt" Tag="{}{n} / {total}"/>
                <RadioButton x:Name="pn_f4" Content="หน้า 1 จาก 10" Style="{StaticResource Seg}" GroupName="pnfmt" Tag="หน้า {n} จาก {total}" IsChecked="True"/>
              </WrapPanel>
              <TextBlock Text="ตำแหน่ง" Style="{StaticResource RowTitle}" Margin="0,8,0,6"/>
              <WrapPanel>
                <RadioButton x:Name="pn_p0" Content="ล่างกลาง" Style="{StaticResource Seg}" GroupName="pnpos" Tag="0" IsChecked="True"/>
                <RadioButton x:Name="pn_p1" Content="ล่างขวา" Style="{StaticResource Seg}" GroupName="pnpos" Tag="1"/>
                <RadioButton x:Name="pn_p2" Content="บนขวา" Style="{StaticResource Seg}" GroupName="pnpos" Tag="2"/>
              </WrapPanel>
              <WrapPanel Margin="0,8,0,0">
                <TextBlock Text="เริ่มนับที่" Style="{StaticResource RowTitle}" VerticalAlignment="Center" Margin="0,0,8,0"/>
                <TextBox x:Name="PnStart" Style="{StaticResource Input}" Text="1" Width="70"/>
                <CheckBox x:Name="PnSkipFirst" Style="{StaticResource Toggle}" VerticalAlignment="Center" Margin="20,0,8,0"/>
