                <Button x:Name="BtnBootAdv" Content="Advanced Startup (เมนูซ่อม Windows)" Style="{StaticResource Secondary}" Margin="0,0,0,6"/>
                <Button x:Name="BtnBootNormal" Content="ยกเลิก Safe Mode (บูตปกติ)" Style="{StaticResource Outline}" Visibility="Collapsed"/>
              </StackPanel>
            </Border>
          </Grid>
          <Border Style="{StaticResource Panel}" Margin="0,6,12,12">
            <StackPanel>
              <Grid>
                <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
