                <TextBox x:Name="WtOut" IsReadOnly="True" BorderThickness="0" Background="Transparent" Foreground="##LOGFG##" FontFamily="Consolas" FontSize="11.5" Height="190" VerticalScrollBarVisibility="Auto" TextWrapping="Wrap" Padding="10,8"/>
