      <!-- ============ 9) เกี่ยวกับ ============ -->
      <ScrollViewer x:Name="Page_about" Visibility="Collapsed" VerticalScrollBarVisibility="Auto">
        <StackPanel MaxWidth="820" HorizontalAlignment="Left" Margin="0,0,6,0">
          <TextBlock Text="เกี่ยวกับ" Style="{StaticResource PageTitle}"/>
          <TextBlock Text="ข้อมูลเวอร์ชัน การอัปเดต และหมายเหตุการใช้งาน" Style="{StaticResource PageSub}"/>
          <Border Style="{StaticResource Panel}" Margin="0,0,0,12">
            <Grid>
              <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
              <Grid Width="64" Height="64">
                <Border x:Name="AboutLogoBox" CornerRadius="18" Background="#EE6C2B"><TextBlock Text="S" FontSize="32" FontWeight="Bold" Foreground="White" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border>
                <Image x:Name="AboutLogo" Visibility="Collapsed" RenderOptions.BitmapScalingMode="HighQuality"/>
              </Grid>
              <StackPanel Grid.Column="1" Margin="16,0,0,0" VerticalAlignment="Center">
                <TextBlock x:Name="AboutVer" FontSize="20" FontWeight="Bold" Foreground="##TITLEFG##"/>
                <TextBlock Text="โปรแกรมดูแลเครื่องคอมพิวเตอร์ครบในที่เดียว — ปรับแต่ง ล้างขยะ วิเคราะห์พื้นที่ ตรวจสุขภาพเครื่อง และเครื่องมือ PDF" Style="{StaticResource Muted}" FontSize="12.5" Margin="0,3,0,0"/>
              </StackPanel>
            </Grid>
          </Border>
          <TextBlock Text="อัปเดต" Style="{StaticResource Section}"/>
          <Border Style="{StaticResource Panel}" Margin="0,0,0,12">
            <Grid>
              <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
              <StackPanel VerticalAlignment="Center"><TextBlock Text="อัปเดตโปรแกรม" Style="{StaticResource RowTitle}"/><TextBlock x:Name="UpdStatus" Text="เช็คเวอร์ชันใหม่จาก GitHub Releases — ถ้ามี จะดาวน์โหลดและติดตั้งให้อัตโนมัติ แล้วเปิดโปรแกรมใหม่" Style="{StaticResource RowDesc}"/></StackPanel>
              <Button x:Name="BtnCheckUpdate" Grid.Column="1" Content="ตรวจสอบอัปเดต" Style="{StaticResource Secondary}" VerticalAlignment="Center"/>
            </Grid>
