          <Border Style="{StaticResource Panel}" Margin="0,0,0,12">
            <StackPanel>
              <TextBlock Text="•  ควรตรวจสอบไฟล์ก่อนลบทุกครั้ง" Style="{StaticResource Body}" Margin="0,0,0,4"/>
              <TextBlock Text="•  การตรวจสุขภาพเครื่องเป็นการตรวจเบื้องต้น ไม่ได้รับประกันว่าจะตรวจพบหรือแก้ไขปัญหาได้ทุกกรณี" Style="{StaticResource Body}" Margin="0,0,0,4"/>
              <TextBlock Text="•  แนะนำให้เปิด 'สร้าง Restore Point ก่อน' ทุกครั้งที่ปรับแต่งเครื่อง เพื่อย้อนกลับได้" Style="{StaticResource Body}" Margin="0,0,0,4"/>
              <TextBlock Text="•  PDF Tools ทำงานในเครื่องทั้งหมด ไม่มีการอัปโหลดไฟล์ — ไฟล์ PDF ที่มีรหัสผ่านยังไม่รองรับ" Style="{StaticResource Body}"/>
            </StackPanel>
          </Border>
          <TextBlock Text="เครดิต" Style="{StaticResource Section}"/>
          <TextBlock Text="ฟอนต์ Sarabun (SIL Open Font License) • PDFsharp (MIT License) • Windows.Data.Pdf" Style="{StaticResource Muted}" Margin="2,0,0,10"/>
        </StackPanel>
      </ScrollViewer>

    </Grid>
  </Grid>
</Window>
'@


foreach($tk in @{
    "##WINDOWBG##"=$Theme.WindowBg; "##SIDEBARBG##"=$Theme.SidebarBg; "##SIDEBORDER##"=$Theme.SideBorder
    "##CARDBG##"=$Theme.CardBg; "##CARDBGHOVER##"=$Theme.CardBgHover; "##CARDBORDER##"=$Theme.CardBorder
    "##TITLEFG##"=$Theme.TitleFg; "##BODYFG##"=$Theme.BodyFg; "##MUTEDFG##"=$Theme.MutedFg; "##SECTIONFG##"=$Theme.SectionFg
    "##CHIPBG##"=$Theme.ChipBg; "##CHIPBORDER##"=$Theme.ChipBorder; "##CHIPHOVER##"=$Theme.ChipHover; "##CHIPFG##"=$Theme.ChipFg
    "##OUTLINEBG##"=$Theme.OutlineBg; "##OUTLINEBORDER##"=$Theme.OutlineBorder; "##OUTLINEHOVER##"=$Theme.OutlineHover
    "##LOGBG##"=$Theme.LogBg; "##LOGBORDER##"=$Theme.LogBorder; "##LOGFG##"=$Theme.LogFg
    "##TOGGLEOFF##"=$Theme.ToggleTrackOff; "##LINKFG##"=$Theme.LinkFg; "##PROGTRACK##"=$Theme.ProgTrack
    "##SECONDARYBG##"=$Theme.SecondaryBg; "##SECONDARYHOVER##"=$Theme.SecondaryHover
    "##NAVHOVER##"=$Theme.NavHover; "##ACCENTSOFT##"=$Theme.AccentSoft; "##INPUTBG##"=$Theme.InputBg; "##INPUTBORDER##"=$Theme.InputBorder; "##ALTROW##"=$Theme.AltRow
    "##FONTFAMILY##"=$FontFamilyValue
}.GetEnumerator()){ $xaml = $xaml.Replace($tk.Key, $tk.Value) }

$reader = New-Object System.Xml.XmlNodeReader ([xml]$xaml)
$window = [Windows.Markup.XamlReader]::Load($reader)
Set-ModernChrome $window

# ดึงทุก element ที่มี x:Name มาไว้ใน $ui
$ui = @{}
foreach($mt in [regex]::Matches($xaml, 'x:Name="([^"]+)"')){
    $n = $mt.Groups[1].Value
    $el = $window.FindName($n)
    if($el){ $ui[$n] = $el }
}

# กันโปรแกรมปิดตัวเมื่อเกิด error ที่ไม่คาดคิด
$window.Dispatcher.Add_UnhandledException({
    $_.Handled = $true
    $msg = $_.Exception.Message
    try{ [void][System.Windows.MessageBox]::Show("เกิดข้อผิดพลาด:`n`n$msg","SCPclear",[System.Windows.MessageBoxButton]::OK,[System.Windows.MessageBoxImage]::Warning) }catch{}
})

# ============================================================
#   ตัวช่วยทั่วไป
# ============================================================
function NewBrush($hex){ $b = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($hex)); $b.Freeze(); return $b }
function Fmt-Size($bytes){ return [Scp.Sys]::Size([double]$bytes) }
function Show-Msg($text, $title = "SCPclear", $icon = "Information"){
    [void][System.Windows.MessageBox]::Show($window, $text, $title, [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::$icon)
}
function Ask-YesNo($text, $title = "ยืนยัน", $icon = "Question"){
    return ([System.Windows.MessageBox]::Show($window, $text, $title, [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::$icon) -eq [System.Windows.MessageBoxResult]::Yes)
}
function New-Text($text, $size = 12.5, $fg = $Theme.BodyFg, $weight = "Normal"){
    $t = New-Object System.Windows.Controls.TextBlock
    $t.Text = $text; $t.FontSize = $size; $t.Foreground = (NewBrush $fg); $t.FontWeight = $weight; $t.TextWrapping = 'Wrap'
    return $t
}
function New-Icon($code, $size = 16, $fg = "#EE6C2B"){
    $t = New-Object System.Windows.Controls.TextBlock
    $t.FontFamily = New-Object System.Windows.Media.FontFamily("Segoe MDL2 Assets")
    $t.Text = [string][char]$code; $t.FontSize = $size; $t.Foreground = (NewBrush $fg); $t.VerticalAlignment = 'Center'
    return $t
}
function New-Card($padding = "16,12", $margin = "0,0,0,8"){
    $c = New-Object System.Windows.Controls.Border
    $c.Background = (NewBrush $Theme.CardBg); $c.CornerRadius = "12"; $c.BorderBrush = (NewBrush $Theme.CardBorder); $c.BorderThickness = "1"
    $c.Padding = $padding; $c.Margin = $margin
    return $c
}
function New-Grid([string[]]$cols){
    $g = New-Object System.Windows.Controls.Grid
    foreach($w in $cols){ $cd = New-Object System.Windows.Controls.ColumnDefinition; $cd.Width = $w; $g.ColumnDefinitions.Add($cd) }
    return $g
}
function Add-ToGrid($grid, $el, $col = 0, $row = 0){
    [System.Windows.Controls.Grid]::SetColumn($el, $col); [System.Windows.Controls.Grid]::SetRow($el, $row)
    [void]$grid.Children.Add($el)
}
function New-MiniBar($value, $color = "#EE6C2B"){
    $p = New-Object System.Windows.Controls.ProgressBar
    $p.Style = $window.FindResource("MiniBar"); $p.Maximum = 100; $p.Value = [double]$value; $p.Foreground = (NewBrush $color)
    return $p
}
function Get-LoadColor($pct){ if($pct -ge 90){ "#E5484D" } elseif($pct -ge 75){ "#F5A623" } else { "#EE6C2B" } }
function Open-Path($path, [switch]$Select){
    try{
        if($Select){ Start-Process explorer.exe "/select,`"$path`"" }
        else { Start-Process explorer.exe "`"$path`"" }
    }catch{}
}
function Flush-UI { $window.Dispatcher.Invoke([Windows.Threading.DispatcherPriority]::Render, [action]{}) }

# ============================================================
#   งานเบื้องหลัง (ไม่ให้หน้าจอค้างระหว่างสแกน/แปลงไฟล์)
#   - Task จาก C#  -> Watch-Task
#   - สคริปต์ PowerShell ใน runspace แยก -> Start-BgWork
#   - โปรเซสภายนอก (sfc/DISM) -> Watch-Proc
#   OnDone จะถูกเรียกด้วย ($result, $errorMessage, $job)
# ============================================================
$script:Jobs = New-Object System.Collections.ArrayList
$script:JobTimer = New-Object System.Windows.Threading.DispatcherTimer
$script:JobTimer.Interval = [TimeSpan]::FromMilliseconds(200)
$script:JobTimer.Add_Tick({
    if($script:Jobs.Count -eq 0){ $script:JobTimer.Stop(); return }
    foreach($j in @($script:Jobs)){
        try{
            if($j.OnTick){ & $j.OnTick $j }
            $done = $false
            if($j.Kind -eq 'task'){ $done = $j.Task.IsCompleted }
            elseif($j.Kind -eq 'ps'){ $done = $j.Handle.IsCompleted }
            elseif($j.Kind -eq 'proc'){ $done = $j.Proc.Done }
            if(-not $done){ continue }
            [void]$script:Jobs.Remove($j)
            $res = $null; $err = $null
            if($j.Kind -eq 'task'){
                if($j.Task.IsFaulted){
                    $ex = $j.Task.Exception.InnerException
                    $err = if($ex){ $ex.Message } else { $j.Task.Exception.Message }
                } elseif($j.Task.GetType().IsGenericType){ $res = $j.Task.Result }
            } elseif($j.Kind -eq 'ps'){
                try{
                    $res = $j.PS.EndInvoke($j.Handle)
                    if((-not $res -or $res.Count -eq 0) -and $j.PS.Streams.Error.Count -gt 0){ $err = $j.PS.Streams.Error[0].ToString() }
                }catch{
                    $ie = $_.Exception
                    while($ie.InnerException){ $ie = $ie.InnerException }
                    $err = $ie.Message
                }
                try{ $j.PS.Dispose(); $j.RS.Dispose() }catch{}
            } elseif($j.Kind -eq 'proc'){ $res = $j.Proc.ExitCode }
            if($j.OnDone){ & $j.OnDone $res $err $j }
        }catch{
            [void]$script:Jobs.Remove($j)
            Show-Msg ("เกิดข้อผิดพลาดระหว่างทำงาน:`n`n" + $_.Exception.Message) "SCPclear" "Warning"
        }
    }
})
function Watch-Task($Task, [scriptblock]$OnDone, [scriptblock]$OnTick = $null, $State = $null){
    $j = @{ Kind='task'; Task=$Task; OnDone=$OnDone; OnTick=$OnTick; State=$State }
    [void]$script:Jobs.Add($j); $script:JobTimer.Start()
    return $j
}
function Watch-Proc($Proc, [scriptblock]$OnDone, [scriptblock]$OnTick = $null, $State = $null){
    $j = @{ Kind='proc'; Proc=$Proc; OnDone=$OnDone; OnTick=$OnTick; State=$State }
    [void]$script:Jobs.Add($j); $script:JobTimer.Start()
    return $j
}
function Start-BgWork([scriptblock]$Work, [object[]]$ArgList = @(), [string[]]$Functions = @(), [scriptblock]$OnDone, [scriptblock]$OnTick = $null, $State = $null){
    $sync = [hashtable]::Synchronized(@{ Status=''; Cancel=$false })
    $rs = [runspacefactory]::CreateRunspace(); $rs.ApartmentState = 'STA'; $rs.ThreadOptions = 'ReuseThread'; $rs.Open()
    $ps = [powershell]::Create(); $ps.Runspace = $rs
    $defs = '$ErrorActionPreference = "Stop"' + "`n"
    foreach($fn in $Functions){ $defs += "function $fn {`n" + (Get-Item "function:$fn").Definition + "`n}`n" }
    [void]$ps.AddScript($defs); [void]$ps.Invoke(); $ps.Commands.Clear()
    [void]$ps.AddScript($Work.ToString()); [void]$ps.AddArgument($sync)
    foreach($a in $ArgList){ [void]$ps.AddArgument($a) }
    $j = @{ Kind='ps'; PS=$ps; RS=$rs; Handle=$ps.BeginInvoke(); Sync=$sync; OnDone=$OnDone; OnTick=$OnTick; State=$State }
    [void]$script:Jobs.Add($j); $script:JobTimer.Start()
    return $j
}

