# ============================================================
#   1) หน้าหลัก (Dashboard)
# ============================================================
function Get-SysInfo {
    $cs = Get-CimInstance Win32_ComputerSystem
    $os = Get-CimInstance Win32_OperatingSystem
    $cpu = Get-CimInstance Win32_Processor | Select-Object -First 1
    $gpu = ''
    try{ $gpu = (@(Get-CimInstance Win32_VideoController -ErrorAction Stop | Where-Object { $_.Name -notmatch 'Basic Display|Remote|Virtual|Mirage|Parsec|Meta' } | ForEach-Object { $_.Name.Trim() }) -join ', ') }catch{}
    $dv = ''
    try{ $dv = (Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction Stop).DisplayVersion }catch{}
    return @{
        Model = ("{0} {1}" -f $cs.Manufacturer, $cs.Model).Trim()
        Cpu   = ($cpu.Name -replace '\s+',' ').Trim()
        Cores = "$($cpu.NumberOfCores) คอร์ / $($cpu.NumberOfLogicalProcessors) เธรด"
        Gpu   = $(if($gpu){ $gpu } else { '-' })
        Os    = (("{0} {1}" -f ($os.Caption -replace '^Microsoft\s+',''), $dv).Trim() + " (Build $($os.BuildNumber))")
        Boot  = $os.LastBootUpTime
    }
}
function Add-InfoRow($grid, $label, $value){
    $rd = New-Object System.Windows.Controls.RowDefinition; $rd.Height = "Auto"; $grid.RowDefinitions.Add($rd)
    $r = $grid.RowDefinitions.Count - 1
    $l = New-Text $label 12 $Theme.MutedFg; $l.Margin = "0,3,8,3"
    $v = New-Text $value 12.5 $Theme.BodyFg "SemiBold"; $v.Margin = "0,3,0,3"
    Add-ToGrid $grid $l 0 $r; Add-ToGrid $grid $v 1 $r
}
function Get-UptimeText {
    $up = (Get-Date) - $script:SysInfo.Boot
    if($up.Days -gt 0){ "$($up.Days) วัน $($up.Hours) ชม." } else { "$($up.Hours) ชม. $($up.Minutes) นาที" }
}
function Update-DashLive {
    $c = [Scp.Sys]::CpuPercent(); $m = [Scp.Sys]::Memory()
    $ui.DashCpuVal.Text = "{0:0}%" -f $c; $ui.DashCpuBar.Value = $c; $ui.DashCpuBar.Foreground = (NewBrush (Get-LoadColor $c))
    $ui.DashRamVal.Text = "{0:0}%" -f $m[2]; $ui.DashRamBar.Value = $m[2]; $ui.DashRamBar.Foreground = (NewBrush (Get-LoadColor $m[2]))
    $ui.DashRamSub.Text = "ใช้ {0} จาก {1}" -f (Fmt-Size $m[1]), (Fmt-Size $m[0])
}
function Update-Dashboard {
    if(-not $script:SysInfo){
        $script:SysInfo = Get-SysInfo
        $g = $ui.DashInfo
        Add-InfoRow $g "รุ่นเครื่อง" $script:SysInfo.Model
        Add-InfoRow $g "CPU" $script:SysInfo.Cpu
        Add-InfoRow $g "คอร์" $script:SysInfo.Cores
        Add-InfoRow $g "การ์ดจอ" $script:SysInfo.Gpu
        Add-InfoRow $g "RAM" "$ramGB GB"
        Add-InfoRow $g "ระบบ" $script:SysInfo.Os
        Add-InfoRow $g "ไดรฟ์ระบบ" "$($env:SystemDrive) ($diskType)"
        $ui.DashCpuSub.Text = $script:SysInfo.Cpu
        $ui.DashCpuSub.ToolTip = $script:SysInfo.Cpu
    }
    $hour = (Get-Date).Hour
    $greet = if($hour -lt 12){ "สวัสดีตอนเช้า" } elseif($hour -lt 17){ "สวัสดีตอนบ่าย" } else { "สวัสดีตอนเย็น" }
    $ui.DashHello.Text = "$greet, $env:USERNAME"
    $ui.DashSub.Text = "$env:COMPUTERNAME  •  $($script:SysInfo.Os)  •  เปิดเครื่องมาแล้ว $(Get-UptimeText)"

    # ไดรฟ์ระบบ
    try{
        $sd = New-Object System.IO.DriveInfo($env:SystemDrive)
        $used = $sd.TotalSize - $sd.TotalFreeSpace; $pct = [math]::Round($used / $sd.TotalSize * 100)
        $ui.DashDiskLabel.Text = "  ไดรฟ์ $($env:SystemDrive)"
        $ui.DashDiskVal.Text = "$pct%"; $ui.DashDiskBar.Value = $pct; $ui.DashDiskBar.Foreground = (NewBrush (Get-LoadColor $pct))
        $ui.DashDiskSub.Text = "เหลือ {0} จาก {1}" -f (Fmt-Size $sd.TotalFreeSpace), (Fmt-Size $sd.TotalSize)
    }catch{}

    # ไดรฟ์ทั้งหมด
    $sp = $ui.DashDrives; $sp.Children.Clear()
    foreach($d in [System.IO.DriveInfo]::GetDrives()){
        try{
            if(-not $d.IsReady -or ($d.DriveType -ne 'Fixed' -and $d.DriveType -ne 'Removable')){ continue }
            $used = $d.TotalSize - $d.TotalFreeSpace
            $pct = if($d.TotalSize -gt 0){ [math]::Round($used / $d.TotalSize * 100) } else { 0 }
            $label = if($d.VolumeLabel){ "$($d.Name.TrimEnd('\'))  $($d.VolumeLabel)" } else { $d.Name.TrimEnd('\') }
            if($d.DriveType -eq 'Removable'){ $label += "  (USB)" }
            $g = New-Grid @('*','Auto'); $g.Margin = "0,0,0,12"
            foreach($i in 0..1){ $rd = New-Object System.Windows.Controls.RowDefinition; $rd.Height = "Auto"; $g.RowDefinitions.Add($rd) }
            Add-ToGrid $g (New-Text $label 12.5 $Theme.BodyFg "SemiBold") 0 0
            $info = New-Text ("เหลือ {0} / {1}" -f (Fmt-Size $d.TotalFreeSpace), (Fmt-Size $d.TotalSize)) 11.5 $Theme.MutedFg
            Add-ToGrid $g $info 1 0
            $bar = New-MiniBar $pct (Get-LoadColor $pct); $bar.Margin = "0,6,0,0"
            [System.Windows.Controls.Grid]::SetColumnSpan($bar, 2); Add-ToGrid $g $bar 0 1
            [void]$sp.Children.Add($g)
        }catch{}
    }
    Update-DashLive
}
