function Get-ErrMsg($er){ $e = $er.Exception; while($e.InnerException){ $e = $e.InnerException }; return $e.Message }
function PdfErr($msg){ if($msg -match 'password|encrypt|protected|decrypt|owner'){ return "ไฟล์ PDF มีรหัสผ่านหรือถูกป้องกัน — ยังไม่รองรับ" }; return $msg }
function Load-Bitmap($path){
    $bi = New-Object System.Windows.Media.Imaging.BitmapImage
    $bi.BeginInit(); $bi.CacheOption = 'OnLoad'; $bi.UriSource = New-Object System.Uri($path); $bi.EndInit(); $bi.Freeze()
    return $bi
}
function Get-UniquePath($path){
    if(-not (Test-Path -LiteralPath $path)){ return $path }
    $dir = Split-Path $path; $ext = [IO.Path]::GetExtension($path); $base = [IO.Path]::GetFileNameWithoutExtension($path)
    $i = 2; while(Test-Path -LiteralPath (Join-Path $dir "$base ($i)$ext")){ $i++ }
    return (Join-Path $dir "$base ($i)$ext")
}
function Pick-Files($filter, [bool]$multi){
    $d = New-Object Microsoft.Win32.OpenFileDialog; $d.Filter = $filter; $d.Multiselect = $multi
    if($d.ShowDialog($window)){ return ,[string[]]$d.FileNames }
    return ,[string[]]@()
}
function Pick-SaveFile($defaultPath){
    $d = New-Object Microsoft.Win32.SaveFileDialog
    $d.Filter = "PDF (*.pdf)|*.pdf"; $d.OverwritePrompt = $true
    $d.InitialDirectory = Split-Path $defaultPath; $d.FileName = [IO.Path]::GetFileName($defaultPath)
    if($d.ShowDialog($window)){ return $d.FileName }
    return $null
}
function Set-PdfStatus($msg, $kind = 'info', $outPath = $null){
    $ui.PdfStatus.Text = $msg
    $col = switch($kind){ 'ok' { "#22A06B" } 'err' { "#E5484D" } 'busy' { "#EE6C2B" } default { $Theme.MutedFg } }
    $ui.PdfStatus.Foreground = (NewBrush $col)
    $script:PdfLastOut = $outPath
    $ui.BtnPdfOpenOut.Visibility = if($outPath){ 'Visible' } else { 'Collapsed' }
}
function Set-PdfBusy($busy){
    $script:PdfBusy = $busy
    foreach($n in $PdfRunButtons){ $ui[$n].IsEnabled = -not $busy }
    if(-not $busy){ $ui.BtnOrgSave.IsEnabled = ($script:Org.Pages.Count -gt 0) }
}
