# ---------- รายการไฟล์ (Merge / Images to PDF) ----------
function New-FileItem($path){
    $sp = New-Object System.Windows.Controls.StackPanel; $sp.Orientation = 'Horizontal'; $sp.Tag = $path
    $n = New-Object System.Windows.Controls.TextBlock; $n.Text = [IO.Path]::GetFileName($path); $n.FontWeight = 'SemiBold'; $n.VerticalAlignment = 'Center'
    $size = try{ Fmt-Size (Get-Item -LiteralPath $path).Length }catch{ '' }
    $d = New-Object System.Windows.Controls.TextBlock; $d.Text = "    $size   •   $(Split-Path $path)"; $d.Foreground = (NewBrush $Theme.MutedFg); $d.FontSize = 11.5; $d.VerticalAlignment = 'Center'
    [void]$sp.Children.Add($n); [void]$sp.Children.Add($d)
    $sp.ToolTip = $path
    return $sp
}
function Add-ToFileList($list, $paths, $exts){
    $skipped = 0
    foreach($p in $paths){
        if(-not $p -or -not (Test-Path -LiteralPath $p -PathType Leaf)){ continue }
        if($exts -notcontains [IO.Path]::GetExtension($p).ToLower()){ $skipped++; continue }
        $dup = $false; foreach($it in $list.Items){ if($it.Tag -eq $p){ $dup = $true } }
        if(-not $dup){ [void]$list.Items.Add((New-FileItem $p)) }
    }
    if($skipped){ Set-PdfStatus "ข้าม $skipped ไฟล์ที่ไม่รองรับ" 'info' }
}
function Move-ListItems($list, [int]$dir){
    $sel = @($list.SelectedItems)
    if($sel.Count -eq 0){ return }
    $items = New-Object System.Collections.ArrayList
    foreach($i in $list.Items){ [void]$items.Add($i) }
    $order = if($dir -lt 0){ 0..($items.Count - 1) } else { ($items.Count - 1)..0 }
    foreach($i in $order){
        $it = $items[$i]
        if($sel -notcontains $it){ continue }
        $j = $i + $dir
        if($j -lt 0 -or $j -ge $items.Count -or ($sel -contains $items[$j])){ continue }
        $items[$i] = $items[$j]; $items[$j] = $it
    }
    $list.Items.Clear()
    foreach($it in $items){ [void]$list.Items.Add($it) }
    foreach($it in $sel){ [void]$list.SelectedItems.Add($it) }
}
function Remove-ListSelected($list){ foreach($it in @($list.SelectedItems)){ $list.Items.Remove($it) } }

