# ---------- ไฟล์เดี่ยว (Split / จัดหน้า / เป็นรูป / บีบอัด) ----------
function Set-PdfFile($which, $path){
    if(-not $path -or [IO.Path]::GetExtension($path).ToLower() -ne '.pdf'){ Show-Msg "กรุณาเลือกไฟล์ .pdf" "PDF Tools"; return }
    $n = -1; $locked = $false
    if($PdfReady){
        try{ $n = [Scp.Pdf]::PageCount($path) }
        catch{
            $locked = [Scp.Pdf]::IsProtected($path)
            if($which -eq 'prot' -and $locked){ $n = -1 }
            elseif($locked){ Show-Msg "ไฟล์นี้มีรหัสผ่าน — ปลดรหัสก่อนที่เมนู 'รหัสผ่าน PDF' แล้วค่อยใช้เครื่องมือนี้" "PDF Tools" "Warning"; return }
            else { Show-Msg ("เปิดไฟล์ไม่ได้: " + (PdfErr (Get-ErrMsg $_))) "PDF Tools" "Warning"; return }
        }
    }
    $size = (Get-Item -LiteralPath $path).Length
    $info = "{0}  •  {1}" -f $(if($locked){ "🔒 มีรหัสผ่าน" } elseif($n -ge 0){ "$n หน้า" } else { "ไฟล์ PDF" }), (Fmt-Size $size)
    switch($which){
        'split' { $ui.SplitFile.Text = $path; $ui.SplitInfo.Text = $info; $script:SplitPages = $n }
        'org'   { Load-OrgFile $path $n }
        'toimg' { $ui.ToImgFile.Text = $path; $ui.ToImgInfo.Text = $info }
        'cmp'   { $ui.CmpFile.Text = $path; $ui.CmpInfo.Text = $info }
        'prot'  { $ui.ProtFile.Text = $path; $ui.ProtInfo.Text = $info; if($locked){ $ui.prot_remove.IsChecked = $true } else { $ui.prot_add.IsChecked = $true } }
        'wm'    { $ui.WmFile.Text = $path; $ui.WmInfo.Text = $info }
        'pn'    { $ui.PnFile.Text = $path; $ui.PnInfo.Text = $info }
    }
    Set-PdfStatus ""
}
