    $ui.ProtPw2Label.Visibility = $vis; $ui.ProtPw2Box.Visibility = $vis; $ui.ProtOpts.Visibility = $vis
    $ui.ProtPwLabel.Text = if($add){ "ตั้งรหัสผ่าน" } else { "รหัสผ่านปัจจุบัน" }
    $ui.BtnProtRun.Content = if($add){ "ใส่รหัสผ่าน" } else { "ปลดรหัสผ่าน" }
}
$ui.prot_add.Add_Checked({ Set-ProtMode })
