    if(-not $f){ Show-Msg "กรุณาเลือกไฟล์ PDF ก่อน" "รหัสผ่าน PDF"; return }
    $pw = $ui.ProtPw1.Password
    $base = Join-Path (Split-Path $f) ([IO.Path]::GetFileNameWithoutExtension($f))
    if($ui.prot_add.IsChecked){
        if($pw.Length -lt 4){ Show-Msg "รหัสผ่านควรยาวอย่างน้อย 4 ตัวอักษร" "รหัสผ่าน PDF" "Warning"; return }
        if($pw -ne $ui.ProtPw2.Password){ Show-Msg "รหัสผ่านทั้งสองช่องไม่ตรงกัน" "รหัสผ่าน PDF" "Warning"; return }
        $out = Pick-SaveFile "$base`_ใส่รหัส.pdf"; if(-not $out){ return }
        if($out -eq $f){ Show-Msg "ห้ามบันทึกทับไฟล์ต้นฉบับ กรุณาตั้งชื่อใหม่" "รหัสผ่าน PDF" "Warning"; return }
        Set-PdfBusy $true; Set-PdfStatus "กำลังใส่รหัสผ่าน..." 'busy'
        $task = [Scp.Pdf]::Protect($f, $out, $pw, [bool]$ui.ProtAllowPrint.IsChecked, [bool]$ui.ProtAllowCopy.IsChecked)
        $ui.ProtPw1.Clear(); $ui.ProtPw2.Clear()
        $null = Watch-Task $task {
            param($res, $err, $job)
            Set-PdfBusy $false
            if($err){ Set-PdfStatus ("ใส่รหัสผ่านไม่สำเร็จ: " + (PdfErr $err)) 'err'; return }
            Set-PdfStatus ("✓ ใส่รหัสผ่านแล้ว — จดรหัสไว้ให้ดี ถ้าลืมจะเปิดไฟล์ไม่ได้  →  " + [IO.Path]::GetFileName($job.State)) 'ok' $job.State
        } -State $out
    } else {
        if(-not $pw){ Show-Msg "ใส่รหัสผ่านปัจจุบันของไฟล์" "รหัสผ่าน PDF" "Warning"; return }
        $out = Pick-SaveFile "$base`_ไม่มีรหัส.pdf"; if(-not $out){ return }
        if($out -eq $f){ Show-Msg "ห้ามบันทึกทับไฟล์ต้นฉบับ กรุณาตั้งชื่อใหม่" "รหัสผ่าน PDF" "Warning"; return }
        Set-PdfBusy $true; Set-PdfStatus "กำลังปลดรหัสผ่าน..." 'busy'
        $task = [Scp.Pdf]::Unprotect($f, $out, $pw)
        $ui.ProtPw1.Clear()
        $null = Watch-Task $task {
            param($res, $err, $job)
            Set-PdfBusy $false
            if($err){
                $m = if($err -match 'password is invalid|invalid password'){ "รหัสผ่านไม่ถูกต้อง" } elseif($err -match 'AES|not supported|unsupported'){ "ไฟล์นี้ใช้การเข้ารหัสแบบที่ยังไม่รองรับ (AES)" } else { $err }
                Set-PdfStatus "ปลดรหัสผ่านไม่สำเร็จ: $m" 'err'; return
            }
            Set-PdfStatus ("✓ ปลดรหัสผ่านแล้ว ({0} หน้า)  →  {1}" -f $res, [IO.Path]::GetFileName($job.State)) 'ok' $job.State
        } -State $out
    }
})

