    $rgb = "128,128,128"; foreach($rb in @($ui.wm_gray, $ui.wm_red, $ui.wm_blue)){ if($rb.IsChecked){ $rgb = [string]$rb.Tag } }
    $c = @($rgb -split ',' | ForEach-Object { [int]$_ })
