    if($out -eq $f){ Show-Msg "ห้ามบันทึกทับไฟล์ต้นฉบับ กรุณาตั้งชื่อใหม่" "ลายน้ำ" "Warning"; return }
    Set-PdfBusy $true; Set-PdfStatus "กำลังใส่ลายน้ำ..." 'busy'
    $null = Watch-Task ([Scp.Pdf]::Watermark($f, $out, $text, $op, [bool]$ui.wm_diag.IsChecked, $c[0], $c[1], $c[2])) {
        param($res, $err, $job)
        Set-PdfBusy $false
        if($err){ Set-PdfStatus ("ใส่ลายน้ำไม่สำเร็จ: " + (PdfErr $err)) 'err'; return }
        Set-PdfStatus ("✓ ใส่ลายน้ำแล้ว {0} หน้า  →  {1}" -f $res, [IO.Path]::GetFileName($job.State)) 'ok' $job.State
    } -State $out
})

