    if(-not $f){ Show-Msg "กรุณาเลือกไฟล์ PDF ก่อน" "ใส่เลขหน้า"; return }
    $pattern = "หน้า {n} จาก {total}"; foreach($rb in @($ui.pn_f1, $ui.pn_f2, $ui.pn_f3, $ui.pn_f4)){ if($rb.IsChecked){ $pattern = [string]$rb.Tag } }
    $pos = 0; foreach($rb in @($ui.pn_p0, $ui.pn_p1, $ui.pn_p2)){ if($rb.IsChecked){ $pos = [int]$rb.Tag } }
