    $out = Pick-SaveFile (Join-Path (Split-Path $f) ([IO.Path]::GetFileNameWithoutExtension($f) + "_เลขหน้า.pdf")); if(-not $out){ return }
    if($out -eq $f){ Show-Msg "ห้ามบันทึกทับไฟล์ต้นฉบับ กรุณาตั้งชื่อใหม่" "ใส่เลขหน้า" "Warning"; return }
    Set-PdfBusy $true; Set-PdfStatus "กำลังใส่เลขหน้า..." 'busy'
    $null = Watch-Task ([Scp.Pdf]::PageNumbers($f, $out, $pos, $pattern, $start, [bool]$ui.PnSkipFirst.IsChecked, 11)) {
        param($res, $err, $job)
        Set-PdfBusy $false
        if($err){ Set-PdfStatus ("ใส่เลขหน้าไม่สำเร็จ: " + (PdfErr $err)) 'err'; return }
        Set-PdfStatus ("✓ ใส่เลขหน้าแล้ว {0} หน้า  →  {1}" -f $res, [IO.Path]::GetFileName($job.State)) 'ok' $job.State
    } -State $out
})

# Split
$ui.split_all.Add_Checked({ $ui.SplitRangeBox.Visibility = 'Collapsed' })
$ui.split_range.Add_Checked({ $ui.SplitRangeBox.Visibility = 'Visible'; $ui.SplitRanges.Focus() })
function Parse-Ranges([string]$text, [int]$n){
    $groups = New-Object 'System.Collections.Generic.List[int[]]'
    foreach($part in ($text -split '[,;]')){
        $p = $part.Trim(); if(-not $p){ continue }
        if($p -match '^(\d+)\s*-\s*(\d+)$'){ $a = [int]$Matches[1]; $b = [int]$Matches[2] }
        elseif($p -match '^\d+$'){ $a = [int]$p; $b = $a }
        else { throw "รูปแบบไม่ถูกต้อง: '$p' (ตัวอย่างที่ถูก: 1-3, 5, 8-10)" }
        if($a -lt 1 -or $b -lt 1 -or $a -gt $n -or $b -gt $n){ throw "เลขหน้า '$p' เกินจำนวนหน้า (ไฟล์นี้มี $n หน้า)" }
        $groups.Add([int[]]@(($a - 1)..($b - 1)))
    }
    if($groups.Count -eq 0){ throw "กรุณาใส่ช่วงหน้า เช่น 1-3, 5" }
    return ,$groups.ToArray()
}
$ui.BtnSplitRun.Add_Click({
    $f = $ui.SplitFile.Text
    if(-not $f){ Show-Msg "กรุณาเลือกไฟล์ PDF ก่อน" "Split PDF"; return }
    $n = $script:SplitPages
    try{
        if($ui.split_all.IsChecked){
            if($n -gt 300 -and -not (Ask-YesNo "ไฟล์นี้มี $n หน้า จะได้ $n ไฟล์ ต้องการทำต่อ?")){ return }
            $groups = New-Object 'int[][]' $n
            for($i = 0; $i -lt $n; $i++){ $groups[$i] = [int[]]@($i) }
        } else { $groups = Parse-Ranges $ui.SplitRanges.Text $n }
    }catch{ Show-Msg $_.Exception.Message "Split PDF" "Warning"; return }
    $base = [IO.Path]::GetFileNameWithoutExtension($f)
    $outDir = Get-UniquePath (Join-Path (Split-Path $f) "${base}_แยกไฟล์")
    try{ New-Item -ItemType Directory -Path $outDir -Force | Out-Null }catch{ Show-Msg "สร้างโฟลเดอร์ไม่ได้: $outDir" "Split PDF" "Warning"; return }
    Set-PdfBusy $true; Set-PdfStatus "กำลังแยกไฟล์..." 'busy'
    $null = Watch-Task ([Scp.Pdf]::Split($f, $outDir, $base, $groups)) {
        param($res, $err, $job)
        Set-PdfBusy $false
        if($err){ Set-PdfStatus ("แยกไฟล์ไม่สำเร็จ: " + (PdfErr $err)) 'err'; return }
        Set-PdfStatus ("✓ แยกได้ {0} ไฟล์  →  โฟลเดอร์ {1}" -f $res, (Split-Path $job.State -Leaf)) 'ok' $job.State
    } -State $outDir
})

# ---------- จัดเรียง / หมุน / ลบหน้า (ใช้หน้าจอเดียวกัน) ----------
function Set-OrgMode($k){
    $script:OrgMode = $k
    $ui.OrgMoveGrp.Visibility = if($k -eq 'reorder'){ 'Visible' } else { 'Collapsed' }
    $ui.OrgRotGrp.Visibility  = if($k -eq 'rotate'){ 'Visible' } else { 'Collapsed' }
    $ui.OrgDelGrp.Visibility  = if($k -eq 'delete'){ 'Visible' } else { 'Collapsed' }
    switch($k){
        'reorder' { $ui.OrgTitle.Text = "จัดเรียงหน้า"; $ui.OrgDesc.Text = "คลิกเลือกหน้า แล้วกดเลื่อนไปก่อน/หลัง หรือย้ายไปหน้าแรก/ท้ายสุด — ไฟล์ใหม่จะเรียงตามที่เห็น" }
        'rotate'  { $ui.OrgTitle.Text = "หมุนหน้า PDF"; $ui.OrgDesc.Text = "คลิกเลือกหน้าที่ต้องการหมุน แล้วกดปุ่มหมุน (ถ้าไม่เลือกหน้าใดเลย จะหมุนทุกหน้า)" }
        'delete'  { $ui.OrgTitle.Text = "ลบหน้า PDF"; $ui.OrgDesc.Text = "คลิกเลือกหน้าที่ไม่ต้องการ แล้วกด ลบหน้าที่เลือก — หน้าที่จะถูกลบจะจางลง (ไฟล์ต้นฉบับไม่ถูกแก้)" }
    }
}
function Set-OrgTileLook($b){
    $p = $b.Tag
    $b.Background = (NewBrush $(if($p.Sel){ $Theme.AccentSoft } else { $Theme.CardBg }))
    $b.BorderBrush = (NewBrush $(if($p.Sel){ "#EE6C2B" } else { $Theme.CardBorder }))
    $b.BorderThickness = if($p.Sel){ "2" } else { "1" }
    $b.Opacity = if($p.Del){ 0.38 } else { 1 }
}
function Update-OrgHint {
    $pages = $script:Org.Pages
    if($pages.Count -eq 0){ $ui.OrgHint.Text = "เลือกไฟล์ PDF เพื่อเริ่ม (ลากไฟล์มาวางที่ช่องด้านบนก็ได้)"; return }
    $sel = @($pages | Where-Object { $_.Sel }).Count; $del = @($pages | Where-Object { $_.Del }).Count
    $t = "$($pages.Count) หน้า  •  เลือกอยู่ $sel หน้า"
    if($del){ $t += "  •  จะลบ $del หน้า" }
    $ui.OrgHint.Text = $t + "  —  คลิกที่หน้าเพื่อเลือก/ยกเลิก"
}
function Render-OrgPages {
    $wp = $ui.OrgPages; $wp.Children.Clear()
    $k = 0
    foreach($p in $script:Org.Pages){
        $k++
        $b = New-Object System.Windows.Controls.Border
        $b.Width = 132; $b.Margin = "0,0,10,10"; $b.Padding = "8"; $b.CornerRadius = "12"; $b.Cursor = 'Hand'; $b.Tag = $p
        Set-OrgTileLook $b
        $sp = New-Object System.Windows.Controls.StackPanel
        $box = New-Object System.Windows.Controls.Grid; $box.Height = 150
        $rt = New-Object System.Windows.Media.RotateTransform([double]$p.Rot)
        if($p.Img){
            $im = New-Object System.Windows.Controls.Image; $im.Source = $p.Img; $im.Stretch = 'Uniform'; $im.MaxHeight = 146; $im.MaxWidth = 114
            $im.LayoutTransform = $rt; $im.HorizontalAlignment = 'Center'; $im.VerticalAlignment = 'Center'
            [void]$box.Children.Add($im)
        } else {
            $ph = New-Object System.Windows.Controls.Border; $ph.Width = 96; $ph.Height = 128; $ph.CornerRadius = "6"
            $ph.Background = (NewBrush $Theme.ProgTrack); $ph.LayoutTransform = $rt; $ph.HorizontalAlignment = 'Center'; $ph.VerticalAlignment = 'Center'
            $pn = New-Text "$($p.Src + 1)" 26 $Theme.MutedFg "Bold"; $pn.HorizontalAlignment = 'Center'; $pn.VerticalAlignment = 'Center'
            $ph.Child = $pn
            [void]$box.Children.Add($ph)
        }
        [void]$sp.Children.Add($box)
        $t = New-Text "หน้า $k" 12 $Theme.BodyFg "SemiBold"; $t.HorizontalAlignment = 'Center'; $t.Margin = "0,6,0,0"
        [void]$sp.Children.Add($t)
        $notes = @()
        if(($p.Src + 1) -ne $k){ $notes += "เดิมหน้า $($p.Src + 1)" }
        if($p.Rot){ $notes += "หมุน $($p.Rot)°" }
        if($p.Del){ $notes += "จะถูกลบ" }
        if($notes.Count){
            $nt = New-Text ($notes -join " • ") 10.5 $(if($p.Del){ "#E5484D" } else { "#EE6C2B" }) "SemiBold"; $nt.HorizontalAlignment = 'Center'; $nt.TextAlignment = 'Center'
            [void]$sp.Children.Add($nt)
        }
        $b.Child = $sp
        $b.Add_MouseLeftButtonUp({ $pg = $this.Tag; $pg.Sel = -not $pg.Sel; Set-OrgTileLook $this; Update-OrgHint })
        [void]$wp.Children.Add($b)
    }
    Update-OrgHint
}
function Load-OrgFile($path, $n){
    $ui.OrgFile.Text = $path
    $script:Org.File = $path; $script:Org.Pages.Clear(); $script:Org.Gen++
    for($i = 0; $i -lt $n; $i++){ [void]$script:Org.Pages.Add(@{ Src=$i; Rot=0; Sel=$false; Del=$false; Img=$null }) }
    Render-OrgPages
    $ui.BtnOrgSave.IsEnabled = ($n -gt 0 -and -not $script:PdfBusy)
    if($n -gt 0 -and $n -le 300){
        $dir = Join-Path $TempRoot ("thumbs_" + [guid]::NewGuid().ToString('N'))
        Set-PdfStatus "กำลังสร้างภาพตัวอย่างหน้า..." 'busy'
        $null = Start-BgWork -Work {
            param($Sync, $Path, $Out)
            Invoke-PdfRender -Sync $Sync -Path $Path -OutDir $Out -Prefix 'p' -Dpi 0 -Width 150 -Fmt 'png' -Quality 90 -Pages $null
        } -ArgList @($path, $dir) -Functions @('Invoke-PdfRender') -State @{ Gen=$script:Org.Gen } -OnTick {
            param($job)
            if($job.State.Gen -eq $script:Org.Gen -and $job.Sync.Status){ $ui.PdfStatus.Text = "กำลังสร้างภาพตัวอย่าง... $($job.Sync.Status)" }
        } -OnDone {
            param($res, $err, $job)
            if($job.State.Gen -ne $script:Org.Gen){ return }
            if($err){ Set-PdfStatus "แสดงภาพตัวอย่างไม่ได้ (ยังจัดการหน้าได้ตามปกติ)" 'info'; return }
            $files = @($res)
            foreach($pg in $script:Org.Pages){
                if($pg.Src -lt $files.Count){ try{ $pg.Img = Load-Bitmap ([string]$files[$pg.Src]) }catch{} }
            }
            Render-OrgPages
            if(-not $script:PdfBusy){ Set-PdfStatus "" }
        }
    } elseif($n -gt 300){ Set-PdfStatus "ไฟล์มีหน้าเยอะ ($n หน้า) จึงแสดงเป็นเลขหน้าแทนภาพตัวอย่าง" 'info' }
}
function Get-OrgSelected { return ,@($script:Org.Pages | Where-Object { $_.Sel }) }
function Rotate-OrgPages([int]$deg){
    if($script:Org.Pages.Count -eq 0){ return }
    $targets = Get-OrgSelected
    if($targets.Count -eq 0){ $targets = @($script:Org.Pages) }
    foreach($p in $targets){ $p.Rot = (($p.Rot + $deg) % 360 + 360) % 360 }
    Render-OrgPages
}
$ui.BtnRotL.Add_Click({ Rotate-OrgPages -90 })
$ui.BtnRotR.Add_Click({ Rotate-OrgPages 90 })
$ui.BtnRot180.Add_Click({ Rotate-OrgPages 180 })
$ui.BtnOrgDel.Add_Click({
    $sel = Get-OrgSelected
    if($sel.Count -eq 0){ Show-Msg "คลิกเลือกหน้าที่ต้องการลบก่อน" "Delete Pages"; return }
    foreach($p in $sel){ $p.Del = $true; $p.Sel = $false }
    Render-OrgPages
})
$ui.BtnOrgUndel.Add_Click({ foreach($p in $script:Org.Pages){ $p.Del = $false }; Render-OrgPages })
$ui.BtnOrgSelAll.Add_Click({ foreach($p in $script:Org.Pages){ $p.Sel = $true }; Render-OrgPages })
$ui.BtnOrgSelNone.Add_Click({ foreach($p in $script:Org.Pages){ $p.Sel = $false }; Render-OrgPages })
$ui.BtnOrgLeft.Add_Click({
    $pg = $script:Org.Pages
    for($i = 1; $i -lt $pg.Count; $i++){ if($pg[$i].Sel -and -not $pg[$i-1].Sel){ $t = $pg[$i-1]; $pg[$i-1] = $pg[$i]; $pg[$i] = $t } }
    Render-OrgPages
})
$ui.BtnOrgRight.Add_Click({
    $pg = $script:Org.Pages
    for($i = $pg.Count - 2; $i -ge 0; $i--){ if($pg[$i].Sel -and -not $pg[$i+1].Sel){ $t = $pg[$i+1]; $pg[$i+1] = $pg[$i]; $pg[$i] = $t } }
    Render-OrgPages
})
function Move-OrgSelectedTo([bool]$first){
    $sel = @($script:Org.Pages | Where-Object { $_.Sel }); $rest = @($script:Org.Pages | Where-Object { -not $_.Sel })
    if($sel.Count -eq 0){ return }
    $script:Org.Pages.Clear()
    if($first){ foreach($p in $sel + $rest){ [void]$script:Org.Pages.Add($p) } } else { foreach($p in $rest + $sel){ [void]$script:Org.Pages.Add($p) } }
    Render-OrgPages
}
$ui.BtnOrgFirst.Add_Click({ Move-OrgSelectedTo $true })
$ui.BtnOrgLast.Add_Click({ Move-OrgSelectedTo $false })
$ui.BtnOrgReverse.Add_Click({ $script:Org.Pages.Reverse(); Render-OrgPages })
$ui.BtnOrgSave.Add_Click({
    $f = $script:Org.File
    if(-not $f){ Show-Msg "กรุณาเลือกไฟล์ PDF ก่อน"; return }
    $keep = @($script:Org.Pages | Where-Object { -not $_.Del })
    if($keep.Count -eq 0){ Show-Msg "ต้องเหลืออย่างน้อย 1 หน้า" "PDF Tools" "Warning"; return }
    $changed = ($keep.Count -ne $script:Org.Pages.Count)
    for($i = 0; $i -lt $keep.Count; $i++){ if($keep[$i].Src -ne $i -or $keep[$i].Rot -ne 0){ $changed = $true } }
    if(-not $changed){ Show-Msg "ยังไม่ได้เปลี่ยนแปลงอะไร — จัดเรียง/หมุน/ลบหน้าก่อนแล้วค่อยบันทึก" "PDF Tools"; return }
    $order = [int[]]@($keep | ForEach-Object { $_.Src }); $rot = [int[]]@($keep | ForEach-Object { $_.Rot })
    $suffix = switch($script:OrgMode){ 'reorder' { '_จัดเรียง' } 'rotate' { '_หมุน' } 'delete' { '_ลบหน้า' } default { '_แก้ไข' } }
    $out = Pick-SaveFile (Join-Path (Split-Path $f) ([IO.Path]::GetFileNameWithoutExtension($f) + "$suffix.pdf"))
    if(-not $out){ return }
    if($out -eq $f){ Show-Msg "ห้ามบันทึกทับไฟล์ต้นฉบับ กรุณาตั้งชื่อใหม่" "PDF Tools" "Warning"; return }
    Set-PdfBusy $true; Set-PdfStatus "กำลังบันทึก..." 'busy'
    $null = Watch-Task ([Scp.Pdf]::Organize($f, $out, $order, $rot)) {
        param($res, $err, $job)
        Set-PdfBusy $false
        if($err){ Set-PdfStatus ("บันทึกไม่สำเร็จ: " + (PdfErr $err)) 'err'; return }
        Set-PdfStatus ("✓ บันทึกไฟล์ใหม่แล้ว — {0} หน้า  →  {1}" -f $res, [IO.Path]::GetFileName($job.State)) 'ok' $job.State
    } -State $out
})

# PDF to Images
$ui.BtnToImgRun.Add_Click({
    $f = $ui.ToImgFile.Text
    if(-not $f){ Show-Msg "กรุณาเลือกไฟล์ PDF ก่อน" "PDF to Images"; return }
    $fmt = if($ui.toimg_jpg.IsChecked){ 'jpg' } else { 'png' }
    $dpi = 150; foreach($rb in @($ui.dpi_96, $ui.dpi_150, $ui.dpi_200, $ui.dpi_300)){ if($rb.IsChecked){ $dpi = [int]$rb.Tag } }
    $base = [IO.Path]::GetFileNameWithoutExtension($f)
    $outDir = Get-UniquePath (Join-Path (Split-Path $f) "${base}_รูปภาพ")
    Set-PdfBusy $true; Set-PdfStatus "กำลังแปลงเป็นรูปภาพ..." 'busy'
    $null = Start-BgWork -Work {
        param($Sync, $Path, $Out, $Prefix, $Dpi, $Fmt)
        Invoke-PdfRender -Sync $Sync -Path $Path -OutDir $Out -Prefix $Prefix -Dpi $Dpi -Width 0 -Fmt $Fmt -Quality 90 -Pages $null
    } -ArgList @($f, $outDir, "${base}_หน้า", $dpi, $fmt) -Functions @('Invoke-PdfRender') -State $outDir -OnTick {
        param($job)
        if($job.Sync.Status){ $ui.PdfStatus.Text = "กำลังแปลงหน้า $($job.Sync.Status)..." }
    } -OnDone {
        param($res, $err, $job)
        Set-PdfBusy $false
        if($err){ Set-PdfStatus ("แปลงไม่สำเร็จ: " + (PdfErr $err)) 'err'; return }
        Set-PdfStatus ("✓ แปลงแล้ว {0} หน้า  →  โฟลเดอร์ {1}" -f @($res).Count, (Split-Path $job.State -Leaf)) 'ok' $job.State
    }
})

# PDF Compressor
function Update-CmpDesc {
    $ui.CmpDesc.Text = if($ui.cmp_med.IsChecked){ "แปลงแต่ละหน้าเป็นภาพ 150 DPI — ลดขนาดได้มาก เหมาะกับไฟล์สแกน  ⚠ ข้อความในไฟล์ใหม่จะคัดลอก/ค้นหาไม่ได้" }
                       elseif($ui.cmp_high.IsChecked){ "แปลงแต่ละหน้าเป็นภาพ 100 DPI คุณภาพต่ำลง — ไฟล์เล็กที่สุด  ⚠ ข้อความในไฟล์ใหม่จะคัดลอก/ค้นหาไม่ได้" }
                       else { "บีบอัดโครงสร้างไฟล์โดยไม่แตะรูปและข้อความ — ปลอดภัย แต่บางไฟล์อาจลดได้น้อย" }
}
foreach($rb in @($ui.cmp_low, $ui.cmp_med, $ui.cmp_high)){ $rb.Add_Checked({ Update-CmpDesc }) }
function Report-Compress($orig, $out){
    $new = (Get-Item -LiteralPath $out).Length
    if($new -ge $orig){
        Remove-Item -LiteralPath $out -Force -ErrorAction SilentlyContinue
        Set-PdfStatus "ไฟล์นี้บีบอัดเพิ่มไม่ได้แล้ว (ผลลัพธ์ไม่เล็กกว่าเดิม) — ลองเลือกระดับที่สูงขึ้น" 'info'
        return
    }
    $pct = [math]::Round((1 - $new / $orig) * 100)
    Set-PdfStatus ("✓ ลดขนาดจาก {0} เหลือ {1} (เล็กลง {2}%)  →  {3}" -f (Fmt-Size $orig), (Fmt-Size $new), $pct, [IO.Path]::GetFileName($out)) 'ok' $out
}
$ui.BtnCmpRun.Add_Click({
    $f = $ui.CmpFile.Text
    if(-not $f){ Show-Msg "กรุณาเลือกไฟล์ PDF ก่อน" "PDF Compressor"; return }
    $orig = (Get-Item -LiteralPath $f).Length
    $out = Pick-SaveFile (Join-Path (Split-Path $f) ([IO.Path]::GetFileNameWithoutExtension($f) + "_บีบอัด.pdf"))
    if(-not $out){ return }
    if($out -eq $f){ Show-Msg "ห้ามบันทึกทับไฟล์ต้นฉบับ กรุณาตั้งชื่อใหม่" "PDF Compressor" "Warning"; return }
    Set-PdfBusy $true
    $st = @{ Orig=$orig; Out=$out }
    if($ui.cmp_low.IsChecked){
        Set-PdfStatus "กำลังบีบอัด..." 'busy'
        $null = Watch-Task ([Scp.Pdf]::CompressLossless($f, $out)) {
            param($res, $err, $job)
            Set-PdfBusy $false
            if($err){ Set-PdfStatus ("บีบอัดไม่สำเร็จ: " + (PdfErr $err)) 'err'; return }
            Report-Compress $job.State.Orig $job.State.Out
        } -State $st
    } else {
        $dpi = if($ui.cmp_high.IsChecked){ 100 } else { 150 }
        $q = if($ui.cmp_high.IsChecked){ 55 } else { 70 }
        $tmp = Join-Path $TempRoot ("cmp_" + [guid]::NewGuid().ToString('N'))
        Set-PdfStatus "กำลังบีบอัด (แปลงหน้าเป็นภาพ)..." 'busy'
        $null = Start-BgWork -Work {
            param($Sync, $Path, $Out, $Tmp, $Dpi, $Q)
            $files = Invoke-PdfRender -Sync $Sync -Path $Path -OutDir $Tmp -Prefix 'p' -Dpi $Dpi -Width 0 -Fmt 'jpg' -Quality $Q -Pages $null
            $Sync.Status = 'สร้างไฟล์ PDF'
            $size = [Scp.Pdf]::BuildFromImages([string[]]$files, [double]$Dpi, $Out)
            Remove-Item $Tmp -Recurse -Force -ErrorAction SilentlyContinue
            $size
        } -ArgList @($f, $out, $tmp, $dpi, $q) -Functions @('Invoke-PdfRender') -State $st -OnTick {
            param($job)
            if($job.Sync.Status){ $ui.PdfStatus.Text = "กำลังบีบอัด... $($job.Sync.Status)" }
        } -OnDone {
            param($res, $err, $job)
            Set-PdfBusy $false
            if($err){ Set-PdfStatus ("บีบอัดไม่สำเร็จ: " + (PdfErr $err)) 'err'; return }
            Report-Compress $job.State.Orig $job.State.Out
        }
    }
})


# ============================================================
#   โปรแกรมในเครื่อง (รายการ + ถอนการติดตั้ง)
# ============================================================
# ฟังก์ชันนี้ถูกส่งไปรันใน runspace เบื้องหลัง (และใช้ในรายงานเครื่อง)
function Get-InstalledApps([bool]$IncludeStore, [bool]$IncludeSystem) {
    $list = New-Object System.Collections.Generic.List[object]
    $roots = @(
        @{ Path='HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall'; Kind='โปรแกรม' }
        @{ Path='HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall'; Kind='โปรแกรม' }
        @{ Path='HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall'; Kind='ผู้ใช้' }
    )
    $seen = @{}
    foreach($r in $roots){
        if(-not (Test-Path $r.Path)){ continue }
        foreach($k in @(Get-ChildItem $r.Path -ErrorAction SilentlyContinue)){
            $p = Get-ItemProperty $k.PSPath -ErrorAction SilentlyContinue
            if(-not $p -or -not $p.DisplayName){ continue }
            $isSys = ($p.SystemComponent -eq 1) -or [bool]$p.ParentKeyName -or ([string]$p.ReleaseType -match 'Update|Hotfix|Security') -or (-not $p.UninstallString)
            if($isSys -and -not $IncludeSystem){ continue }
            $key = "$($p.DisplayName)|$($p.DisplayVersion)"
            if($seen.ContainsKey($key)){ continue }
            $seen[$key] = 1
            $a = New-Object Scp.AppItem
            $a.Name = ([string]$p.DisplayName).Trim(); $a.Publisher = [string]$p.Publisher; $a.Version = [string]$p.DisplayVersion
            $kb = 0; try{ $kb = [long]$p.EstimatedSize }catch{}
            $a.SizeBytes = $kb * 1024
            $a.SizeText = if($kb -gt 0){ [Scp.Sys]::Size($kb * 1024) } else { '' }
            $d = [datetime]::MinValue
            if([string]$p.InstallDate -match '^\d{8}$'){ try{ $d = [datetime]::ParseExact([string]$p.InstallDate, 'yyyyMMdd', [Globalization.CultureInfo]::InvariantCulture) }catch{} }
            $a.Date = $d
            $a.DateText = if($d -ne [datetime]::MinValue){ $d.ToString('dd/MM/yyyy') } else { '' }
            $a.Kind = if($isSys){ 'ระบบ' } else { $r.Kind }
            $a.Uninstall = [string]$p.UninstallString; $a.QuietUninstall = [string]$p.QuietUninstallString
            $a.Location = ([string]$p.InstallLocation).Trim('"', ' ')
            $list.Add($a)
        }
    }
    if($IncludeStore){
        foreach($x in @(Get-AppxPackage -ErrorAction SilentlyContinue | Where-Object { -not $_.IsFramework -and -not $_.IsResourcePackage -and $_.SignatureKind -eq 'Store' })){
            $a = New-Object Scp.AppItem
            $a.Name = ($x.Name -replace '^[^.]+\.', '')
            $a.Publisher = ($x.Publisher -replace '^CN=([^,]+).*', '$1')
            try{
                $mf = (Get-AppxPackageManifest -Package $x.PackageFullName -ErrorAction Stop).Package.Properties
                if($mf.DisplayName -and [string]$mf.DisplayName -notmatch '^ms-resource:'){ $a.Name = [string]$mf.DisplayName }
                if($mf.PublisherDisplayName -and [string]$mf.PublisherDisplayName -notmatch '^ms-resource:'){ $a.Publisher = [string]$mf.PublisherDisplayName }
            }catch{}
            $a.Version = [string]$x.Version
            $a.SizeText = ''; $a.Kind = 'Store'; $a.Package = $x.PackageFullName; $a.Location = $x.InstallLocation
            $a.Date = [datetime]::MinValue; $a.DateText = ''
            try{ $ct = (Get-Item -LiteralPath $x.InstallLocation -ErrorAction Stop).CreationTime; $a.Date = $ct; $a.DateText = $ct.ToString('dd/MM/yyyy') }catch{}
            $list.Add($a)
        }
    }
    return $list
}

$script:AppItems = New-Object 'System.Collections.ObjectModel.ObservableCollection[Scp.AppItem]'
$ui.AppsGrid.ItemsSource = $script:AppItems
$script:AppsView = [System.Windows.Data.CollectionViewSource]::GetDefaultView($script:AppItems)
$script:AppsView.Filter = [Predicate[object]]{
    param($o)
    $q = $ui.AppSearch.Text.Trim()
    if(-not $q){ return $true }
    return (([string]$o.Name).IndexOf($q, [StringComparison]::OrdinalIgnoreCase) -ge 0 -or ([string]$o.Publisher).IndexOf($q, [StringComparison]::OrdinalIgnoreCase) -ge 0)
}

function Update-AppsStatus {
    if($script:AppsBusy){ return }
    $shown = 0; foreach($x in $script:AppsView){ $shown++ }
    $sum = 0; foreach($x in $script:AppItems){ $sum += $x.SizeBytes }
    $t = "พบ $($script:AppItems.Count) โปรแกรม"
    if($shown -ne $script:AppItems.Count){ $t += "  •  แสดง $shown รายการที่ตรงกับคำค้น" }
    $t += "  •  ขนาดรวมประมาณ $(Fmt-Size $sum) (เฉพาะโปรแกรมที่แจ้งขนาด)"
    $ui.AppsStatus.Text = $t
}

function Load-Apps {
    if($script:AppsBusy){ return }
    $script:AppsBusy = $true; $script:AppsLoaded = $true
    $ui.AppsStatus.Text = "กำลังโหลดรายการโปรแกรม..."; $ui.BtnAppsRefresh.IsEnabled = $false
    $null = Start-BgWork -Work {
        param($Sync, $Store, $Sys)
        Get-InstalledApps $Store $Sys
    } -ArgList @([bool]$ui.AppShowStore.IsChecked, [bool]$ui.AppShowSys.IsChecked) -Functions @('Get-InstalledApps') -OnDone {
        param($res, $err)
        $script:AppsBusy = $false; $ui.BtnAppsRefresh.IsEnabled = $true
        if($err){ $ui.AppsStatus.Text = "โหลดรายการไม่สำเร็จ: $err"; return }
        $script:AppItems.Clear()
        foreach($a in (@($res) | Sort-Object Name)){ $script:AppItems.Add($a) }
        Update-AppsStatus
    }
}

function Split-CommandLine([string]$cmd){
    $c = $cmd.Trim()
    if($c.StartsWith('"')){
        $e = $c.IndexOf('"', 1)
        if($e -gt 0){ return @($c.Substring(1, $e - 1), $c.Substring($e + 1).Trim()) }
    }
    $i = $c.ToLower().IndexOf('.exe')
    if($i -ge 0){ return @($c.Substring(0, $i + 4), $c.Substring($i + 4).Trim()) }
    $sp = $c.IndexOf(' ')
    if($sp -gt 0){ return @($c.Substring(0, $sp), $c.Substring($sp + 1)) }
    return @($c, '')
}

$ui.AppSearch.Add_TextChanged({
    $ui.AppSearchHint.Visibility = if($ui.AppSearch.Text){ 'Collapsed' } else { 'Visible' }
    $script:AppsView.Refresh(); Update-AppsStatus
})
