$ui.BtnAppsRefresh.Add_Click({ Load-Apps })
$ui.AppsGrid.Add_SelectionChanged({
    $it = $ui.AppsGrid.SelectedItem
    $ui.BtnAppUninstall.IsEnabled = [bool]$it
    $ui.BtnAppOpenLoc.IsEnabled = ($it -and $it.Location -and (Test-Path -LiteralPath $it.Location))
})
$ui.BtnAppOpenLoc.Add_Click({ $it = $ui.AppsGrid.SelectedItem; if($it -and $it.Location){ Open-Path $it.Location } })
$ui.BtnAppUninstall.Add_Click({
    $it = $ui.AppsGrid.SelectedItem
    if(-not $it){ return }
    if(-not (Ask-YesNo "ถอนการติดตั้ง `"$($it.Name)`" ?`n`nผู้ผลิต: $($it.Publisher)`nเวอร์ชัน: $($it.Version)`n`nควรปิดโปรแกรมนั้นก่อน" "ถอนการติดตั้ง" "Warning")){ return }
    if($it.Kind -eq 'Store'){
        try{
            Remove-AppxPackage -Package $it.Package -ErrorAction Stop
            [void]$script:AppItems.Remove($it); Update-AppsStatus
            Add-HistoryEntry "ถอนโปรแกรม" $it.Name "สำเร็จ: ถอนแอป Store แล้ว"
            Show-Msg "ถอนแอป $($it.Name) แล้ว" "ถอนการติดตั้ง"
        }catch{ Show-Msg "ถอนไม่สำเร็จ: $($_.Exception.Message)" "ถอนการติดตั้ง" "Warning" }
        return
    }
    if(-not $it.Uninstall){ Show-Msg "โปรแกรมนี้ไม่มีตัวถอนการติดตั้งที่ลงทะเบียนไว้" "ถอนการติดตั้ง" "Warning"; return }
    $parts = Split-CommandLine $it.Uninstall
    $exe = $parts[0]; $arg = $parts[1]
    if($exe -match 'msiexec'){ $arg = $arg -replace '(?i)/I\s*(\{)', '/X$1' }
    try{
        if($arg){ Start-Process -FilePath $exe -ArgumentList $arg } else { Start-Process -FilePath $exe }
        $ui.AppsStatus.Text = "เปิดตัวถอนการติดตั้ง $($it.Name) แล้ว — ทำตามขั้นตอนในหน้าต่างของโปรแกรม เสร็จแล้วกด รีเฟรช"
        Add-HistoryEntry "ถอนโปรแกรม" $it.Name "สำเร็จ: เปิดตัวถอนการติดตั้งแล้ว"
    }catch{ Show-Msg "เปิดตัวถอนการติดตั้งไม่ได้: $($_.Exception.Message)`n`nคำสั่ง: $($it.Uninstall)" "ถอนการติดตั้ง" "Warning" }
})


# ============================================================
#   เครือข่าย (การ์ดเครือข่าย / IP สาธารณะ / Ping / รหัส Wi-Fi)
# ============================================================
# สรุปการ์ดเครือข่าย (ใช้ทั้งหน้าเครือข่ายและรายงานเครื่อง)
function Get-NetSummary {
    $out = New-Object System.Collections.Generic.List[object]
    $cfgs = @{}
    foreach($c in @(Get-NetIPConfiguration -All -ErrorAction SilentlyContinue)){ $cfgs[[int]$c.InterfaceIndex] = $c }
    foreach($a in @(Get-NetAdapter -ErrorAction SilentlyContinue | Sort-Object @{ e = { $_.Status -ne 'Up' } }, Name)){
        $c = $cfgs[[int]$a.ifIndex]
        $ip = ''; $gw = ''; $dns = ''; $dhcp = ''
        if($c){
            $ip = (@($c.IPv4Address | ForEach-Object { "$($_.IPAddress)/$($_.PrefixLength)" }) -join ', ')
            $gw = (@($c.IPv4DefaultGateway | ForEach-Object { $_.NextHop }) -join ', ')
            $dns = (@($c.DNSServer | Where-Object { $_.AddressFamily -eq 2 } | ForEach-Object { $_.ServerAddresses }) -join ', ')
        }
        try{ $ipif = Get-NetIPInterface -InterfaceIndex $a.ifIndex -AddressFamily IPv4 -ErrorAction Stop; $dhcp = if([string]$ipif.Dhcp -eq 'Enabled'){ 'อัตโนมัติ (DHCP)' } else { 'ตั้งค่าเอง (Static)' } }catch{}
        $isWifi = ([string]$a.MediaType -match '802\.11') -or ([string]$a.InterfaceDescription -match 'Wi-?Fi|Wireless|WLAN|802\.11')
        $out.Add([pscustomobject]@{
            Name = $a.Name; Desc = [string]$a.InterfaceDescription; Status = [string]$a.Status; Wifi = $isWifi
            IP = $ip; Gateway = $gw; DNS = $dns; MAC = [string]$a.MacAddress; Speed = [string]$a.LinkSpeed; DHCP = $dhcp
        })
    }
    return $out
}

function New-CopyText($value){
    $t = New-Object System.Windows.Controls.TextBox
    $t.Text = $value; $t.IsReadOnly = $true; $t.BorderThickness = "0"; $t.Background = (NewBrush "Transparent")
    $t.Foreground = (NewBrush $Theme.BodyFg); $t.FontSize = 12.5; $t.FontWeight = "SemiBold"; $t.Padding = "0"; $t.TextWrapping = 'Wrap'
    return $t
}

function Load-NetAdapters {
    $script:NetLoaded = $true
    $sp = $ui.NetAdapters; $sp.Children.Clear()
    $list = @()
    try{ $list = @(Get-NetSummary) }catch{}
    if($list.Count -eq 0){ [void]$sp.Children.Add((New-Text "อ่านข้อมูลการ์ดเครือข่ายไม่ได้" 12.5 $Theme.MutedFg)); return }
    $script:NetGateway = ($list | Where-Object { $_.Status -eq 'Up' -and $_.Gateway } | Select-Object -First 1).Gateway
    if($script:NetGateway){ $script:NetGateway = ($script:NetGateway -split ',')[0].Trim() }
    foreach($n in $list){
        $card = New-Card "16,12" "0,0,0,10"
        $stk = New-Object System.Windows.Controls.StackPanel
        $hd = New-Grid @('Auto','*','Auto')
        Add-ToGrid $hd (New-Icon $(if($n.Wifi){ 0xE701 } else { 0xE839 }) 18 $(if($n.Status -eq 'Up'){ "#EE6C2B" } else { $Theme.MutedFg })) 0
        $ns = New-Object System.Windows.Controls.StackPanel; $ns.Margin = "12,0,8,0"
        [void]$ns.Children.Add((New-Text $n.Name 13.5 $Theme.BodyFg "SemiBold"))
        $dt = New-Text $n.Desc 11 $Theme.MutedFg; $dt.TextTrimming = 'CharacterEllipsis'; $dt.TextWrapping = 'NoWrap'; [void]$ns.Children.Add($dt)
        Add-ToGrid $hd $ns 1
        $stText = switch($n.Status){ 'Up' { 'เชื่อมต่ออยู่' } 'Disabled' { 'ปิดใช้งาน' } default { 'ไม่ได้เชื่อมต่อ' } }
        $st = New-Text $stText 11.5 $(if($n.Status -eq 'Up'){ "#22A06B" } else { $Theme.MutedFg }) "SemiBold"; $st.VerticalAlignment = 'Center'
        Add-ToGrid $hd $st 2
        [void]$stk.Children.Add($hd)
        if($n.Status -eq 'Up'){
            $g = New-Grid @('95','*'); $g.Margin = "30,8,0,0"
            $rows = @(@('IPv4', $n.IP), @('Gateway', $n.Gateway), @('DNS', $n.DNS), @('การรับ IP', $n.DHCP), @('MAC', $n.MAC), @('ความเร็ว', $n.Speed))
            foreach($r in $rows){
                if(-not $r[1]){ continue }
                $rd = New-Object System.Windows.Controls.RowDefinition; $rd.Height = "Auto"; $g.RowDefinitions.Add($rd)
                $ri = $g.RowDefinitions.Count - 1
                $l = New-Text $r[0] 12 $Theme.MutedFg; $l.Margin = "0,2,8,2"; Add-ToGrid $g $l 0 $ri
                $v = New-CopyText $r[1]; $v.Margin = "0,2,0,2"; Add-ToGrid $g $v 1 $ri
            }
            [void]$stk.Children.Add($g)
        } else {
            $m = New-Text ("MAC " + $n.MAC) 11.5 $Theme.MutedFg; $m.Margin = "30,6,0,0"; [void]$stk.Children.Add($m)
        }
        $card.Child = $stk
        [void]$sp.Children.Add($card)
    }
    Load-LanNets
}
$ui.BtnNetRefresh.Add_Click({ Load-NetAdapters })

$ui.BtnNetPublic.Add_Click({
    $ui.NetPublic.Text = "กำลังตรวจ..."; $ui.BtnNetPublic.IsEnabled = $false
    $null = Start-BgWork -Work {
        param($Sync)
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
        ([string](Invoke-RestMethod -Uri 'https://api.ipify.org' -TimeoutSec 8)).Trim()
    } -OnDone {
