        $ui.BtnNetPublic.IsEnabled = $true
        $ui.NetPublic.Text = if($err){ "ตรวจไม่ได้ (ไม่มีอินเทอร์เน็ต หรือถูกบล็อก)" } else { "IP สาธารณะ: " + [string]@($res)[0] }
    }
})

# ---------- Ping ----------
function Start-Ping([string]$target){
    $target = $target.Trim()
    if(-not $target){ return }
    if($script:PingBusy){ return }
    $script:PingBusy = $true
    $ui.PingHost.Text = $target; $ui.PingOut.Text = ""; $ui.BtnPing.IsEnabled = $false
    $ui.PingSummary.Text = "กำลัง Ping $target ..."; $ui.PingSummary.Foreground = (NewBrush "#EE6C2B")
    $null = Start-BgWork -Work {
        param($Sync, $H)
        $p = New-Object System.Net.NetworkInformation.Ping
        $times = New-Object System.Collections.Generic.List[long]; $lost = 0
        for($i = 1; $i -le 10; $i++){
            if($Sync.Cancel){ break }
            try{
                $r = $p.Send($H, 2000)
                if($r.Status -eq 'Success'){
                    $times.Add($r.RoundtripTime)
                    $ttl = if($r.Options){ " TTL=$($r.Options.Ttl)" } else { "" }
                    $Sync.Out += "ตอบกลับจาก $($r.Address): เวลา=$($r.RoundtripTime) ms$ttl`r`n"
                } else { $lost++; $Sync.Out += "ไม่ตอบสนอง ($($r.Status))`r`n" }
            }catch{
                $lost++
                $m = $_.Exception; while($m.InnerException){ $m = $m.InnerException }
                $Sync.Out += "ผิดพลาด: $($m.Message)`r`n"
            }
            Start-Sleep -Milliseconds 400
        }
        @{ Times = $times.ToArray(); Lost = $lost }
    } -ArgList @($target) -OnTick {
        param($job)
        if($job.Sync.Out -and $ui.PingOut.Text -ne $job.Sync.Out){ $ui.PingOut.Text = $job.Sync.Out; $ui.PingOut.ScrollToEnd() }
    } -OnDone {
        param($res, $err, $job)
        $script:PingBusy = $false; $ui.BtnPing.IsEnabled = $true
        $ui.PingOut.Text = [string]$job.Sync.Out
        if($err){ $ui.PingSummary.Text = "Ping ไม่สำเร็จ: $err"; $ui.PingSummary.Foreground = (NewBrush "#E5484D"); return }
        $d = @($res)[0]; $t = @($d.Times); $sent = $t.Count + $d.Lost
        $lossPct = if($sent){ [math]::Round($d.Lost / $sent * 100) } else { 100 }
        if($t.Count -eq 0){ $ui.PingSummary.Text = "ไม่ตอบสนองเลย (สูญหาย 100%) — ตรวจสาย/Wi-Fi หรือปลายทางอาจปิดการตอบ Ping"; $ui.PingSummary.Foreground = (NewBrush "#E5484D"); return }
        $avg = [math]::Round(($t | Measure-Object -Average).Average); $mn = ($t | Measure-Object -Minimum).Minimum; $mx = ($t | Measure-Object -Maximum).Maximum
        $verdict = if($lossPct -gt 0){ "มีการหลุดบางครั้ง" } elseif($avg -lt 50){ "การเชื่อมต่อดีมาก" } elseif($avg -lt 150){ "การเชื่อมต่อปกติ" } else { "ค่อนข้างช้า" }
        $ui.PingSummary.Text = "$verdict  •  เฉลี่ย $avg ms (ต่ำสุด $mn / สูงสุด $mx)  •  สูญหาย $lossPct%"
        $ui.PingSummary.Foreground = (NewBrush $(if($lossPct -gt 0 -or $avg -ge 150){ "#F5A623" } else { "#22A06B" }))
    }
}
$ui.BtnPing.Add_Click({ Start-Ping $ui.PingHost.Text })
$ui.PingHost.Add_KeyDown({ if($_.Key -eq 'Return'){ Start-Ping $ui.PingHost.Text } })
$ui.BtnPingGw.Add_Click({ if($script:NetGateway){ Start-Ping $script:NetGateway } else { Show-Msg "ไม่พบ Gateway (ยังไม่ได้เชื่อมต่อเครือข่าย?)" "Ping" } })
$ui.BtnPingDns.Add_Click({ Start-Ping "8.8.8.8" })
$ui.BtnPingWeb.Add_Click({ Start-Ping "google.com" })

# ---------- รหัส Wi-Fi ที่บันทึกไว้ (อ่านจากไฟล์ export ของ netsh แล้วลบทิ้งทันที) ----------
$ui.BtnWifiLoad.Add_Click({
    $sp = $ui.WifiList; $sp.Children.Clear()
    $dir = Join-Path $TempRoot ("wifi_" + [guid]::NewGuid().ToString('N'))
    $profiles = @()
    try{
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
        $p = Start-Process netsh.exe -ArgumentList "wlan export profile key=clear folder=`"$dir`"" -WindowStyle Hidden -PassThru
        [void]$p.WaitForExit(15000)
        foreach($f in @(Get-ChildItem $dir -Filter *.xml -ErrorAction SilentlyContinue)){
            try{
                [xml]$x = Get-Content -LiteralPath $f.FullName -Raw -Encoding UTF8
                $w = $x.WLANProfile
                $name = [string]$w.SSIDConfig.SSID.name; if(-not $name){ $name = [string]$w.name }
                $auth = [string]$w.MSM.security.authEncryption.authentication
                $key = [string]$w.MSM.security.sharedKey.keyMaterial
                $profiles += [pscustomobject]@{ Name=$name; Auth=$auth; Key=$key }
            }catch{}
        }
    } finally { Remove-Item -LiteralPath $dir -Recurse -Force -ErrorAction SilentlyContinue }
    if($profiles.Count -eq 0){ [void]$sp.Children.Add((New-Text "ไม่พบโปรไฟล์ Wi-Fi (เครื่องนี้อาจไม่มี Wi-Fi หรือบริการ WLAN ปิดอยู่)" 12.5 $Theme.MutedFg)); return }
    foreach($w in ($profiles | Sort-Object Name)){
        $card = New-Card "14,9" "0,0,0,6"
        $g = New-Grid @('*','Auto','Auto','Auto')
        $ns = New-Object System.Windows.Controls.StackPanel; $ns.VerticalAlignment = 'Center'
        [void]$ns.Children.Add((New-Text $w.Name 13 $Theme.BodyFg "SemiBold"))
        $authText = if($w.Auth){ $w.Auth } else { "-" }
        [void]$ns.Children.Add((New-Text $authText 11 $Theme.MutedFg))
        Add-ToGrid $g $ns 0
        $kt = New-CopyText $(if($w.Key){ "••••••••" } else { "(ไม่มีรหัส / ใช้บัญชีองค์กร)" }); $kt.VerticalAlignment = 'Center'; $kt.Margin = "8,0,8,0"; $kt.FontFamily = New-Object System.Windows.Media.FontFamily("Consolas"); $kt.MinWidth = 120
        Add-ToGrid $g $kt 1
        if($w.Key){
            $bs = New-Object System.Windows.Controls.Button; $bs.Style = $window.FindResource("Link"); $bs.Content = "แสดง"; $bs.Tag = @{ Box=$kt; Key=$w.Key }
            $bs.Add_Click({ $t = $this.Tag; if($t.Box.Text -eq $t.Key){ $t.Box.Text = "••••••••"; $this.Content = "แสดง" } else { $t.Box.Text = $t.Key; $this.Content = "ซ่อน" } })
            Add-ToGrid $g $bs 2
            $bc = New-Object System.Windows.Controls.Button; $bc.Style = $window.FindResource("Link"); $bc.Content = "คัดลอก"; $bc.Tag = $w.Key
            $bc.Add_Click({ try{ [System.Windows.Clipboard]::SetText([string]$this.Tag); $this.Content = "คัดลอกแล้ว ✓" }catch{} })
            Add-ToGrid $g $bc 3
        }
        $card.Child = $g
        [void]$sp.Children.Add($card)
    }
})


# ============================================================
#   รายงานเครื่อง (HTML + PDF) — สเปก, สุขภาพ, ดิสก์, เครือข่าย, โปรแกรม, Startup
# ============================================================
function HtmlEnc($s){ return [System.Net.WebUtility]::HtmlEncode([string]$s) }

function Get-EdgePath {
    foreach($p in @("${env:ProgramFiles(x86)}\Microsoft\Edge\Application\msedge.exe", "$env:ProgramFiles\Microsoft\Edge\Application\msedge.exe")){
        if($p -and (Test-Path $p)){ return $p }
    }
    return $null
}

function Build-ReportHtml($data){
    if(-not $script:SysInfo){ $script:SysInfo = Get-SysInfo }
    $si = $script:SysInfo
    $bios = $null; try{ $bios = Get-CimInstance Win32_BIOS -ErrorAction Stop }catch{}
    $os = Get-CimInstance Win32_OperatingSystem
    $now = Get-Date
    $font = ""
    foreach($pair in @(@('Sarabun-Regular.ttf', 400), @('Sarabun-Bold.ttf', 700))){
        $fp = Join-Path $FontDir $pair[0]
        if(Test-Path $fp){ $font += "@font-face{font-family:'Sarabun';font-weight:$($pair[1]);src:url(data:font/ttf;base64,$([Convert]::ToBase64String([IO.File]::ReadAllBytes($fp))))}`n" }
    }
    $findings = @($script:HealthFindings)
    $g = @($findings | Where-Object { $_.Status -eq 'Green' }).Count
    $y = @($findings | Where-Object { $_.Status -eq 'Yellow' }).Count
    $r = @($findings | Where-Object { $_.Status -eq 'Red' }).Count
    $score = if($findings.Count){ [math]::Round(($g * 100 + $y * 50) / $findings.Count) } else { '-' }
    $scoreCol = if($score -is [string]){ '#888' } elseif($score -ge 80){ '#22A06B' } elseif($score -ge 60){ '#D98B0B' } else { '#E5484D' }
    $sb = New-Object System.Text.StringBuilder
    function Add([string]$s){ [void]$sb.Append($s) }
    function Row($k, $v){ Add "<tr><th>$(HtmlEnc $k)</th><td>$(HtmlEnc $v)</td></tr>" }

    Add "<!DOCTYPE html><html lang='th'><head><meta charset='utf-8'><title>รายงานเครื่อง $(HtmlEnc $env:COMPUTERNAME)</title><style>$font"
    Add @'
body{font-family:'Sarabun','Leelawadee UI',Tahoma,sans-serif;color:#1f2937;margin:0;background:#f4f5f7;font-size:13px}
.page{max-width:960px;margin:0 auto;padding:28px 32px;background:#fff}
h1{margin:0;font-size:26px} h2{font-size:16px;margin:26px 0 8px;padding-bottom:6px;border-bottom:2px solid #EE6C2B;color:#111827}
.sub{color:#6b7280;margin-top:2px}.brand{color:#EE6C2B;font-weight:700}
.head{display:flex;justify-content:space-between;align-items:center;gap:16px}
.score{text-align:center;border:3px solid;border-radius:50%;width:84px;height:84px;display:flex;flex-direction:column;justify-content:center}
.score b{font-size:26px;line-height:1}.score span{font-size:11px;color:#6b7280}
table{width:100%;border-collapse:collapse;margin-top:4px}
th,td{text-align:left;padding:5px 8px;border-bottom:1px solid #eceef1;vertical-align:top}
table.kv th{width:180px;color:#6b7280;font-weight:400}
table.grid th{background:#f7f8fa;color:#6b7280;font-weight:700;font-size:12px}
.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:6px}
.Green{background:#22A06B}.Yellow{background:#F5A623}.Red{background:#E5484D}
.tag{font-size:11px;padding:1px 8px;border-radius:9px;background:#f1f2f4}
.muted{color:#6b7280}.foot{margin-top:28px;color:#9aa1ac;font-size:11px;text-align:center}
@media print{body{background:#fff}.page{padding:0}h2{break-after:avoid}tr{break-inside:avoid}}
</style></head><body><div class='page'>
'@
    Add "<div class='head'><div><div class='brand'>SCPclear $ScriptVersion</div><h1>รายงานเครื่องคอมพิวเตอร์</h1>"
    Add "<div class='sub'>$(HtmlEnc $env:COMPUTERNAME) • ผู้ใช้ $(HtmlEnc $env:USERNAME) • สร้างเมื่อ $(HtmlEnc $now.ToString('dd/MM/yyyy HH:mm'))</div></div>"
    Add "<div class='score' style='border-color:$scoreCol'><b style='color:$scoreCol'>$score</b><span>คะแนนสุขภาพ</span></div></div>"

    Add "<h2>ข้อมูลเครื่อง</h2><table class='kv'>"
    Row "ชื่อเครื่อง" $env:COMPUTERNAME
    Row "รุ่นเครื่อง" $si.Model
    if($bios){ Row "Serial Number" $bios.SerialNumber; Row "BIOS" ("{0} ({1})" -f $bios.SMBIOSBIOSVersion, $(if($bios.ReleaseDate){ $bios.ReleaseDate.ToString('dd/MM/yyyy') } else { '-' })) }
    Row "CPU" "$($si.Cpu) — $($si.Cores)"
    Row "RAM" "$ramGB GB"
    Row "การ์ดจอ" $si.Gpu
    Row "ระบบปฏิบัติการ" $si.Os
    if($os.InstallDate){ Row "ติดตั้ง Windows เมื่อ" $os.InstallDate.ToString('dd/MM/yyyy') }
    Row "เปิดเครื่องล่าสุด" ("{0}  (เปิดมาแล้ว {1})" -f $si.Boot.ToString('dd/MM/yyyy HH:mm'), (Get-UptimeText))
    Add "</table>"

    Add "<h2>ไดรฟ์</h2><table class='grid'><tr><th>ไดรฟ์</th><th>ชื่อ</th><th>ขนาด</th><th>ใช้ไป</th><th>เหลือ</th><th>% ใช้</th></tr>"
    foreach($d in [System.IO.DriveInfo]::GetDrives()){
        try{
            if(-not $d.IsReady -or ($d.DriveType -ne 'Fixed' -and $d.DriveType -ne 'Removable')){ continue }
            $used = $d.TotalSize - $d.TotalFreeSpace
            Add "<tr><td>$(HtmlEnc $d.Name)</td><td>$(HtmlEnc $d.VolumeLabel)</td><td>$(Fmt-Size $d.TotalSize)</td><td>$(Fmt-Size $used)</td><td>$(Fmt-Size $d.TotalFreeSpace)</td><td>$([math]::Round($used / [math]::Max([double]1, $d.TotalSize) * 100))%</td></tr>"
        }catch{}
    }
    Add "</table>"

    $disks = @($data.Disks)
    if($disks.Count){
        Add "<h2>สุขภาพดิสก์ (SMART)</h2><table class='grid'><tr><th>ดิสก์</th><th>ชนิด</th><th>ขนาด</th><th>สถานะ</th><th>อุณหภูมิ</th><th>ชั่วโมงใช้งาน</th><th>อายุ SSD ใช้ไป</th></tr>"
        foreach($d in $disks){
            Add "<tr><td>$(HtmlEnc $d.Name)</td><td>$(HtmlEnc "$($d.Media) $($d.Bus)")</td><td>$(Fmt-Size $d.Size)</td><td>$(HtmlEnc $d.Health)</td><td>$(if($d.Temp){ "$($d.Temp)°C" } else { '-' })</td><td>$(if($d.Hours){ '{0:N0}' -f $d.Hours } else { '-' })</td><td>$(if($d.Wear -ne $null){ "$($d.Wear)%" } else { '-' })</td></tr>"
        }
        Add "</table>"
    }

    if($findings.Count){
        Add "<h2>ผลตรวจสุขภาพเครื่อง</h2><p class='muted'>ปกติ $g • ควรตรวจสอบ $y • มีปัญหา $r</p><table class='grid'><tr><th style='width:150px'>หมวด</th><th>รายการ</th><th>รายละเอียด</th></tr>"
        foreach($f in ($findings | Sort-Object { $HealthRank[[string]$_.Status] }, { $_.Cat })){
            Add "<tr><td class='muted'>$(HtmlEnc $f.Cat)</td><td><span class='dot $([string]$f.Status)'></span>$(HtmlEnc $f.Title)</td><td>$(HtmlEnc $f.Detail)</td></tr>"
        }
        Add "</table>"
    }

    $net = @($data.Net | Where-Object { $_.Status -eq 'Up' })
    if($net.Count){
        Add "<h2>เครือข่าย</h2><table class='grid'><tr><th>การ์ด</th><th>IPv4</th><th>Gateway</th><th>DNS</th><th>MAC</th></tr>"
        foreach($n in $net){ Add "<tr><td>$(HtmlEnc $n.Name)<div class='muted'>$(HtmlEnc $n.Desc)</div></td><td>$(HtmlEnc $n.IP)</td><td>$(HtmlEnc $n.Gateway)</td><td>$(HtmlEnc $n.DNS)</td><td>$(HtmlEnc $n.MAC)</td></tr>" }
        Add "</table>"
    }

    $st = @(); try{ $st = @(Get-RunEntries 'HKCU') + @(Get-RunEntries 'HKLM') }catch{}
    if($st.Count){
        Add "<h2>โปรแกรมที่เปิดพร้อม Windows ($($st.Count))</h2><table class='grid'><tr><th>ชื่อ</th><th>สถานะ</th><th>คำสั่ง</th></tr>"
        foreach($e in ($st | Sort-Object Name)){ Add "<tr><td>$(HtmlEnc $e.Name)</td><td>$(if($e.Enabled){ 'เปิด' } else { '<span class=muted>ปิด</span>' })</td><td class='muted' style='word-break:break-all'>$(HtmlEnc $e.Cmd)</td></tr>" }
        Add "</table>"
    }

    $apps = @($data.Apps | Sort-Object Name)
    if($apps.Count){
        Add "<h2>โปรแกรมที่ติดตั้ง ($($apps.Count))</h2><table class='grid'><tr><th>ชื่อโปรแกรม</th><th>ผู้ผลิต</th><th>เวอร์ชัน</th><th>ขนาด</th><th>ติดตั้งเมื่อ</th></tr>"
        foreach($a in $apps){ Add "<tr><td>$(HtmlEnc $a.Name)</td><td class='muted'>$(HtmlEnc $a.Publisher)</td><td>$(HtmlEnc $a.Version)</td><td>$(HtmlEnc $a.SizeText)</td><td>$(HtmlEnc $a.DateText)</td></tr>" }
        Add "</table>"
    }
    Add "<div class='foot'>สร้างโดย SCPclear $ScriptVersion • การตรวจเป็นการตรวจเบื้องต้น ไม่รับประกันว่าพบทุกปัญหา</div></div></body></html>"
    return $sb.ToString()
}

function Start-MachineReport {
    if($script:ReportBusy){ return }
    $script:ReportBusy = $true
    $ui.BtnHealthExport.IsEnabled = $false; $ui.BtnHealthExport.Content = "กำลังสร้างรายงาน..."
    $needHealth = -not $script:HealthFindings
    $null = Start-BgWork -Work {
        param($Sync, $NeedHealth)
        $o = @{}
        if($NeedHealth){ $o.Health = Get-HealthReport }
        $o.Disks = Get-DiskHealth
        $o.Apps = Get-InstalledApps $false $false
        $o.Net = Get-NetSummary
        $o
    } -ArgList @($needHealth) -Functions @('Get-HealthReport','Get-RunEntries','Get-StartupEnabled','Get-DiskHealth','Get-InstalledApps','Get-NetSummary') -OnDone {
        param($res, $err)
        $restore = { $script:ReportBusy = $false; $ui.BtnHealthExport.IsEnabled = $true; $ui.BtnHealthExport.Content = "รายงานเครื่อง (HTML/PDF)" }
        if($err){ & $restore; Show-Msg "สร้างรายงานไม่สำเร็จ: $err" "รายงานเครื่อง" "Warning"; return }
        $d = @($res)[0]
        if(-not $script:DiskInfo){ $script:DiskInfo = @($d.Disks) }
        if($d.Health){ $script:HealthFindings = @($d.Health) + @(Get-DiskFindings $d.Disks); Render-Health }
        $base = Join-Path ([Environment]::GetFolderPath('Desktop')) ("SCPclear-Report-$env:COMPUTERNAME-" + (Get-Date).ToString('yyyyMMdd_HHmm', [Globalization.CultureInfo]::InvariantCulture))
        $html = "$base.html"; $pdf = "$base.pdf"
        try{ [IO.File]::WriteAllText($html, (Build-ReportHtml $d), (New-Object System.Text.UTF8Encoding($true))) }
        catch{ & $restore; Show-Msg "บันทึกรายงานไม่ได้: $($_.Exception.Message)" "รายงานเครื่อง" "Warning"; return }
        $edge = Get-EdgePath
        if(-not $edge){ & $restore; Show-Msg "สร้างรายงาน HTML แล้วที่ Desktop:`n$html`n`n(ไม่พบ Microsoft Edge จึงไม่ได้สร้าง PDF — เปิดไฟล์ HTML แล้วสั่งพิมพ์เป็น PDF ได้)" "รายงานเครื่อง"; Start-Process $html; return }
        $ui.BtnHealthExport.Content = "กำลังสร้าง PDF..."
        $prof = Join-Path $TempRoot ("edge_" + [guid]::NewGuid().ToString('N'))
        $null = Start-BgWork -Work {
            param($Sync, $Edge, $Html, $Pdf, $Prof)
            $uri = ([Uri]$Html).AbsoluteUri
            $a = "--headless --disable-gpu --no-first-run --no-default-browser-check --disable-extensions --user-data-dir=`"$Prof`" --no-pdf-header-footer --print-to-pdf=`"$Pdf`" `"$uri`""
            $p = Start-Process -FilePath $Edge -ArgumentList $a -WindowStyle Hidden -PassThru
            if(-not $p.WaitForExit(90000)){ try{ $p.Kill() }catch{} }
            for($i = 0; $i -lt 20 -and -not (Test-Path $Pdf); $i++){ Start-Sleep -Milliseconds 250 }
            Remove-Item -LiteralPath $Prof -Recurse -Force -ErrorAction SilentlyContinue
            Test-Path $Pdf
        } -ArgList @($edge, $html, $pdf, $prof) -State @{ Html=$html; Pdf=$pdf; Restore=$restore } -OnDone {
            param($res2, $err2, $job)
            & $job.State.Restore
            $okPdf = (Test-Path $job.State.Pdf)
            $msg = "สร้างรายงานแล้วที่ Desktop:`n• " + (Split-Path $job.State.Html -Leaf)
            if($okPdf){ $msg += "`n• " + (Split-Path $job.State.Pdf -Leaf) } else { $msg += "`n(สร้าง PDF ไม่สำเร็จ — เปิดไฟล์ HTML แล้วสั่งพิมพ์เป็น PDF ได้)" }
            Add-HistoryEntry "รายงานเครื่อง" "สร้างรายงาน HTML/PDF" "สำเร็จ: $(Split-Path $job.State.Html -Leaf)"
            Show-Msg $msg "รายงานเครื่อง"
            Start-Process $(if($okPdf){ $job.State.Pdf } else { $job.State.Html })
        }
    }
}


# ============================================================
#   อัปเดตตัวเอง (GitHub Releases หรือเซิร์ฟเวอร์ภายในองค์กร)
#   ตั้งค่าแหล่งอัปเดตเองได้ด้วยตัวแปรระบบ SCPCLEAR_UPDATE_FEED
#   (URL หรือไฟล์ JSON รูปแบบเดียวกับ GitHub: tag_name, body, html_url, assets[name, browser_download_url])
# ============================================================
$UpdateFeed = if($env:SCPCLEAR_UPDATE_FEED){ $env:SCPCLEAR_UPDATE_FEED } else { "https://api.github.com/repos/$GitHubRepo/releases/latest" }

# ฟังก์ชันนี้ถูกส่งไปรันใน runspace เบื้องหลัง
function Get-ReleaseInfo([string]$Feed){
    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
    if($Feed -match '^https?://'){ return (Invoke-RestMethod -Uri $Feed -Headers @{ 'User-Agent' = 'SCPclear' } -TimeoutSec 20) }
    $path = if($Feed -match '^file:'){ ([Uri]$Feed).LocalPath } else { $Feed }
    return (Get-Content -LiteralPath $path -Raw -Encoding UTF8 | ConvertFrom-Json)
}

function Get-Sha256([string]$path){
    $sha = [System.Security.Cryptography.SHA256]::Create(); $fs = [System.IO.File]::OpenRead($path)
    try{ return ([BitConverter]::ToString($sha.ComputeHash($fs)) -replace "-", "") } finally { $fs.Close(); $sha.Dispose() }
}

function Set-UpdStatus($text, $color = $null){
    $ui.UpdStatus.Text = $text
    $ui.UpdStatus.Foreground = (NewBrush $(if($color){ $color } else { $Theme.MutedFg }))
}

$ui.BtnCheckUpdate.Add_Click({
    if($script:UpdBusy){ return }
    $script:UpdBusy = $true; $ui.BtnCheckUpdate.IsEnabled = $false
    Set-UpdStatus "กำลังตรวจสอบเวอร์ชันใหม่..." "#EE6C2B"
    $null = Start-BgWork -Work { param($Sync, $Feed) Get-ReleaseInfo $Feed } -ArgList @($UpdateFeed) -Functions @('Get-ReleaseInfo') -OnDone {
        param($res, $err)
        $script:UpdBusy = $false; $ui.BtnCheckUpdate.IsEnabled = $true
        if($err){ Set-UpdStatus "ตรวจสอบไม่สำเร็จ (ไม่มีอินเทอร์เน็ต หรือยังไม่มี release): $err" "#E5484D"; return }
        $rel = @($res)[0]
        $latest = ([string]$rel.tag_name) -replace '^[vV]', ''
        $newer = $false
        try{ $newer = ([version]$latest -gt [version]$ScriptVersion) }catch{ Set-UpdStatus "รูปแบบเวอร์ชันจากแหล่งอัปเดตไม่ถูกต้อง: '$latest'" "#E5484D"; return }
        if(-not $newer){ Set-UpdStatus "✓ ใช้เวอร์ชันล่าสุดแล้ว (v$ScriptVersion)  •  ตรวจเมื่อ $(Get-Date -Format 'HH:mm')" "#22A06B"; return }
        $want = if($SelfExe){ '\.exe$' } else { '\.ps1$' }
        $asset = @($rel.assets) | Where-Object { $_.name -match $want } | Sort-Object { if($_.name -match '^SCPclear'){ 0 } else { 1 } } | Select-Object -First 1
        $sha = @($rel.assets) | Where-Object { $_.name -match '\.sha256$' } | Select-Object -First 1
        $notes = [string]$rel.body
        if($notes.Length -gt 700){ $notes = $notes.Substring(0, 700) + " ..." }
        Set-UpdStatus "มีเวอร์ชันใหม่ v$latest (ตอนนี้ v$ScriptVersion)" "#EE6C2B"
        if(-not $asset){
            if(Ask-YesNo "มีเวอร์ชันใหม่ v$latest แต่ไม่มีไฟล์สำหรับติดตั้งอัตโนมัติ`n`nเปิดหน้าดาวน์โหลดเลยไหม?" "อัปเดต SCPclear" "Information"){ if($rel.html_url){ Start-Process $rel.html_url } }
            return
        }
        if(-not (Ask-YesNo "มีเวอร์ชันใหม่: v$latest  (ตอนนี้ใช้ v$ScriptVersion)`n`n$notes`n`nดาวน์โหลดและติดตั้งเลยไหม?`nโปรแกรมจะปิดแล้วเปิดใหม่อัตโนมัติ" "อัปเดต SCPclear" "Information")){ return }
        Start-UpdateDownload ([string]$asset.browser_download_url) $(if($sha){ [string]$sha.browser_download_url } else { $null }) $latest
    }
})

function Start-UpdateDownload([string]$url, $shaUrl, [string]$ver){
    $dir = Join-Path $TempRoot "update"
    New-Item -ItemType Directory -Path $dir -Force | Out-Null
    $ext = if($SelfExe){ '.exe' } else { '.ps1' }
    $target = Join-Path $dir "SCPclear-$ver$ext"
    Remove-Item -LiteralPath $target -Force -ErrorAction SilentlyContinue
    $script:UpdBusy = $true; $ui.BtnCheckUpdate.IsEnabled = $false
    Set-UpdStatus "กำลังดาวน์โหลด v$ver ..." "#EE6C2B"
    $null = Start-BgWork -Work {
        param($Sync, $Url, $ShaUrl, $Out)
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
        $wc = New-Object System.Net.WebClient
        $wc.Headers.Add('User-Agent', 'SCPclear')
        $wc.DownloadFile($Url, $Out)
        $sha = $null
        if($ShaUrl){ $sha = (($wc.DownloadString($ShaUrl)).Trim() -split '\s+')[0] }
        @{ Sha = $sha }
    } -ArgList @($url, $shaUrl, $target) -State @{ File=$target; Ver=$ver } -OnDone {
        param($res, $err, $job)
        $script:UpdBusy = $false; $ui.BtnCheckUpdate.IsEnabled = $true
        $file = $job.State.File
        if($err -or -not (Test-Path -LiteralPath $file)){ Set-UpdStatus "ดาวน์โหลดไม่สำเร็จ: $err" "#E5484D"; return }
        if((Get-Item -LiteralPath $file).Length -lt 10KB){ Set-UpdStatus "ไฟล์ที่ดาวน์โหลดเสียหาย (เล็กผิดปกติ) — ยกเลิกการอัปเดต" "#E5484D"; return }
        $expect = @($res)[0].Sha
        if($expect -and (Get-Sha256 $file) -ne $expect.ToUpper()){
            Remove-Item -LiteralPath $file -Force -ErrorAction SilentlyContinue
            Set-UpdStatus "ไฟล์ไม่ตรงกับ checksum (SHA-256) — ยกเลิกการอัปเดตเพื่อความปลอดภัย" "#E5484D"; return
        }
        if($SelfExe){
            $cur = Get-AuthenticodeSignature -LiteralPath $SelfExe
            if($cur.Status -eq 'Valid'){
                $new = Get-AuthenticodeSignature -LiteralPath $file
                if($new.Status -ne 'Valid' -or $new.SignerCertificate.Thumbprint -ne $cur.SignerCertificate.Thumbprint){
                    Remove-Item -LiteralPath $file -Force -ErrorAction SilentlyContinue
                    Set-UpdStatus "ลายเซ็นดิจิทัลของไฟล์ใหม่ไม่ตรงกับเวอร์ชันปัจจุบัน — ยกเลิกการอัปเดตเพื่อความปลอดภัย" "#E5484D"; return
                }
            }
        }
        Install-Update $file $job.State.Ver
    }
}

function Install-Update([string]$newFile, [string]$ver){
    $self = if($SelfExe){ $SelfExe } else { $PSCommandPath }
    $dir = Split-Path $newFile
    $cfg = Join-Path $dir "apply-update.json"
    $updater = Join-Path $dir "apply-update.ps1"
    $restartExe = if($SelfExe){ $SelfExe } else { Join-Path $env:SystemRoot "System32\WindowsPowerShell\v1.0\powershell.exe" }
    $restartArgs = if($SelfExe){ "" } else { "-NoProfile -Sta -ExecutionPolicy Bypass -File `"$self`"" }
    ([ordered]@{ WaitPid = $PID; Src = $newFile; Dst = $self; Restart = $restartExe; RestartArgs = $restartArgs; Log = (Join-Path $dir "apply-update.log") } | ConvertTo-Json) | Set-Content -LiteralPath $cfg -Encoding UTF8
    @'
param([string]$Config)
$c = Get-Content -LiteralPath $Config -Raw -Encoding UTF8 | ConvertFrom-Json
function L($m){ try{ Add-Content -LiteralPath $c.Log -Value ("{0:yyyy-MM-dd HH:mm:ss} {1}" -f (Get-Date), $m) -Encoding UTF8 }catch{} }
L "รอโปรแกรมเดิมปิด (PID $($c.WaitPid))"
try{ Wait-Process -Id $c.WaitPid -Timeout 60 -ErrorAction SilentlyContinue }catch{}
$ok = $false
for($i = 0; $i -lt 40 -and -not $ok; $i++){
    try{
        Copy-Item -LiteralPath $c.Dst -Destination ($c.Dst + ".bak") -Force -ErrorAction SilentlyContinue
        Copy-Item -LiteralPath $c.Src -Destination $c.Dst -Force -ErrorAction Stop
        $ok = $true
    }catch{ Start-Sleep -Milliseconds 500 }
}
if($ok){ L "ติดตั้งไฟล์ใหม่แล้ว: $($c.Dst)"; Remove-Item -LiteralPath ($c.Dst + ".bak") -Force -ErrorAction SilentlyContinue; Remove-Item -LiteralPath $c.Src -Force -ErrorAction SilentlyContinue }
else { L "แทนที่ไฟล์ไม่สำเร็จ — ใช้เวอร์ชันเดิมต่อ" }
if($c.RestartArgs){ Start-Process -FilePath $c.Restart -ArgumentList $c.RestartArgs } else { Start-Process -FilePath $c.Restart }
L "เปิดโปรแกรมใหม่แล้ว"
'@ | Set-Content -LiteralPath $updater -Encoding UTF8
    $ps = Join-Path $env:SystemRoot "System32\WindowsPowerShell\v1.0\powershell.exe"
    Start-Process -FilePath $ps -ArgumentList "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$updater`" -Config `"$cfg`"" -WindowStyle Hidden
    Add-HistoryEntry "อัปเดตโปรแกรม" "อัปเดตเป็น v$ver" "สำเร็จ: ดาวน์โหลดแล้ว กำลังติดตั้ง"
    Set-UpdStatus "กำลังติดตั้ง v$ver — โปรแกรมจะเปิดใหม่ในไม่กี่วินาที" "#22A06B"
    Show-Msg "ดาวน์โหลด v$ver เรียบร้อย`n`nโปรแกรมจะปิดและเปิดเวอร์ชันใหม่ให้อัตโนมัติ" "อัปเดต SCPclear"
    $script:UpdClosing = $true
    $window.Close()
}


