function Get-BugInfo($code){
    if([uint64]$code -gt 0x7FFFFFFF){ return $null }
    $k = [int]$code
    if($BugCodes.ContainsKey($k)){ return $BugCodes[$k] }
    return $null
}
function Get-DriverHint([string]$drv){
    if(-not $drv){ return "" }
    foreach($h in $DriverHints){ if($drv -match $h[0]){ return $h[1] } }
    return ""
}

# ฟังก์ชันนี้ถูกส่งไปรันใน runspace เบื้องหลัง
function Get-CrashInfo {
    $since = (Get-Date).AddDays(-90)
    $dumps = @()
    foreach($f in @(Get-ChildItem "$env:SystemRoot\Minidump" -Filter *.dmp -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 30)){
        $dumps += [Scp.MiniDump]::Read($f.FullName)
    }
    $bug = @()
    try{
        foreach($e in @(Get-WinEvent -FilterHashtable @{ LogName='System'; Id=1001; ProviderName='Microsoft-Windows-WER-SystemErrorReporting'; StartTime=$since } -ErrorAction Stop)){
            $m = [regex]::Match($e.Message, '0x[0-9a-fA-F]{8}')
            if($m.Success){ $bug += [pscustomobject]@{ Time=$e.TimeCreated; Code=[Convert]::ToUInt32($m.Value.Substring(2), 16) } }
        }
    }catch{}
    $power = @()
    try{
        foreach($e in @(Get-WinEvent -FilterHashtable @{ LogName='System'; Id=41; ProviderName='Microsoft-Windows-Kernel-Power'; StartTime=$since } -ErrorAction Stop)){
            $code = 0; try{ $code = [uint32]$e.Properties[0].Value }catch{}
            $power += [pscustomobject]@{ Time=$e.TimeCreated; Code=$code }
        }
    }catch{}
    @{ Dumps = $dumps; Bug = $bug; Power = $power }
}

function Get-DriverOwner([string]$drv){
    try{
        $sd = Get-CimInstance Win32_SystemDriver -ErrorAction Stop | Where-Object { $_.PathName -and ([IO.Path]::GetFileName(($_.PathName -replace '^\\\?\?\\', '').Trim('"')) -ieq $drv) } | Select-Object -First 1
        if($sd){
            $p = ($sd.PathName -replace '^\\\?\?\\', '').Trim('"') -replace '^\\SystemRoot', $env:SystemRoot
            if(Test-Path -LiteralPath $p){ $v = (Get-Item -LiteralPath $p).VersionInfo; $t = (@($v.CompanyName, $v.FileDescription) | Where-Object { $_ }) -join ' — '; if($t){ return $t } }
        }
    }catch{}
    return ""
}

function Start-BsodScan {
    $ui.BsodSummary.Text = "กำลังอ่านไฟล์ crash dump และ Event Log..."; $ui.BsodAdvice.Text = ""; $ui.BsodList.Children.Clear()
    $ui.BtnBsodScan.IsEnabled = $false
    $null = Start-BgWork -Work { param($Sync) Get-CrashInfo } -Functions @('Get-CrashInfo') -OnDone {
        param($res, $err)
        $ui.BtnBsodScan.IsEnabled = $true
        if($err){ $ui.BsodSummary.Text = "อ่านข้อมูลไม่สำเร็จ: $err"; return }
        Render-Bsod (@($res)[0])
    }
}

function Render-Bsod($d){
    $list = $ui.BsodList; $list.Children.Clear()
    $dumps = @($d.Dumps | Where-Object { $_.Code -ne 0 })
    $bugOnly = @($d.Bug | Where-Object { $ev = $_; -not ($dumps | Where-Object { [math]::Abs(($_.Time - $ev.Time).TotalMinutes) -lt 10 }) })
    $hardOff = @($d.Power | Where-Object { $_.Code -eq 0 })
    $crashes = @()
    foreach($x in $dumps){ $crashes += [pscustomobject]@{ Time=$x.Time; Code=[uint32]$x.Code; Driver=[string]$x.Driver; Src='dump' } }
    foreach($x in $bugOnly){ $crashes += [pscustomobject]@{ Time=$x.Time; Code=[uint32]$x.Code; Driver=''; Src='event' } }
    if($crashes.Count -eq 0 -and $hardOff.Count -eq 0){
        $ui.BsodSummary.Text = "✓ ไม่พบจอฟ้าหรือเครื่องดับเองใน 90 วันที่ผ่านมา"
        $ui.BsodSummary.Foreground = (NewBrush "#22A06B"); $ui.BsodAdvice.Text = ""; return
    }
    $ui.BsodSummary.Foreground = (NewBrush $Theme.BodyFg)
    $parts = @()
    if($crashes.Count){ $parts += "จอฟ้า $($crashes.Count) ครั้ง" }
    if($hardOff.Count){ $parts += "เครื่องดับ/รีสตาร์ทกะทันหัน (ไม่ใช่จอฟ้า) $($hardOff.Count) ครั้ง" }
    $ui.BsodSummary.Text = "พบ " + ($parts -join " และ ") + " ในช่วง 90 วัน"
    $advice = @()
    $topDrv = $crashes | Where-Object { $_.Driver } | Group-Object Driver | Sort-Object Count -Descending | Select-Object -First 1
    if($topDrv){
        $hint = Get-DriverHint $topDrv.Name
        $owner = Get-DriverOwner $topDrv.Name
        $advice += "ตัวการหลัก: $($topDrv.Name) (เกิด $($topDrv.Count) ครั้ง)" + $(if($owner){ " — $owner" } else { "" })
        if($hint){ $advice += "แนะนำ: $hint" }
    } elseif($crashes.Count){
        $topCode = $crashes | Group-Object Code | Sort-Object Count -Descending | Select-Object -First 1
        $bi = Get-BugInfo ([uint32]$topCode.Name)
        if($bi){ $advice += "แนะนำ: " + $bi[1] }
    }
    if($hardOff.Count){ $advice += "เครื่องดับกะทันหัน: มักเกิดจากไฟตก/ปลั๊กหลวม, Power Supply เสื่อม, ความร้อนสูงเกิน หรือกดปุ่มปิดค้าง — ทดสอบ CPU ด้านล่างเพื่อดูว่าดับตอนทำงานหนักไหม" }
    $ui.BsodAdvice.Text = $advice -join "`n"

    $all = @($crashes | ForEach-Object { $_ }) + @($hardOff | ForEach-Object { [pscustomobject]@{ Time=$_.Time; Code=[uint32]0; Driver=''; Src='power' } })
    foreach($x in ($all | Sort-Object Time -Descending | Select-Object -First 15)){
        $c = New-Card "14,9" "0,0,0,6"
        $g = New-Grid @('130','*')
        Add-ToGrid $g (New-Text $x.Time.ToString('dd/MM/yyyy HH:mm') 12 $Theme.MutedFg) 0
        $sp = New-Object System.Windows.Controls.StackPanel
        if($x.Src -eq 'power'){
            [void]$sp.Children.Add((New-Text "เครื่องดับ/รีสตาร์ทกะทันหัน (ไม่มีจอฟ้า)" 12.5 "#F5A623" "SemiBold"))
            [void]$sp.Children.Add((New-Text "Kernel-Power 41 — ไฟดับ/ไฟตก, PSU, ความร้อน หรือกดปิดเครื่อง" 11.5 $Theme.MutedFg))
        } else {
            $info = Get-BugInfo $x.Code
            if(-not $info){ $info = @('', 'รหัสนี้ไม่อยู่ในฐานข้อมูล — ค้นหารหัสนี้ในเว็บได้') }
            $title = ("จอฟ้า 0x{0:X8}" -f $x.Code) + $(if($info[0]){ "  $($info[0])" } else { "" })
            [void]$sp.Children.Add((New-Text $title 12.5 "#E5484D" "SemiBold"))
            if($x.Driver){ [void]$sp.Children.Add((New-Text "ตัวการ: $($x.Driver)" 12 $Theme.BodyFg "SemiBold")) }
            [void]$sp.Children.Add((New-Text $info[1] 11.5 $Theme.MutedFg))
        }
        Add-ToGrid $g $sp 1
        $c.Child = $g
        [void]$list.Children.Add($c)
    }
}
$ui.BtnBsodScan.Add_Click({ Start-BsodScan })

# ---------- ข้อมูลอัปเกรด RAM / เมนบอร์ด ----------
function Load-UpgradeInfo {
    $sp = $ui.HwUpgrade; $sp.Children.Clear()
    try{
        $mem = @(Get-CimInstance Win32_PhysicalMemory -ErrorAction Stop)
        $arr = @(Get-CimInstance Win32_PhysicalMemoryArray -ErrorAction SilentlyContinue | Where-Object { $_.Use -eq 3 -or -not $_.Use }) | Select-Object -First 1
        $board = Get-CimInstance Win32_BaseBoard -ErrorAction SilentlyContinue | Select-Object -First 1
        $cpu = Get-CimInstance Win32_Processor | Select-Object -First 1
        $slots = if($arr -and $arr.MemoryDevices){ [int]$arr.MemoryDevices } else { $mem.Count }
        $slots = [math]::Max($slots, $mem.Count)
        $maxKB = if($arr.MaxCapacityEx){ [double]$arr.MaxCapacityEx } elseif($arr.MaxCapacity){ [double]$arr.MaxCapacity } else { 0 }
        $maxGB = [math]::Round($maxKB / 1MB)
        $types = @{ 20='DDR'; 21='DDR2'; 24='DDR3'; 26='DDR4'; 29='LPDDR3'; 30='LPDDR4'; 34='DDR5'; 35='LPDDR5' }
        $t = [int]($mem | Select-Object -First 1).SMBIOSMemoryType
        $type = if($types.ContainsKey($t)){ $types[$t] } else { "RAM" }
        $ff = [int]($mem | Select-Object -First 1).FormFactor
        $form = if($ff -eq 12){ "SO-DIMM (โน้ตบุ๊ก)" } elseif($ff -eq 8){ "DIMM (PC ตั้งโต๊ะ)" } else { "" }
        $speed = ($mem | Measure-Object -Property Speed -Maximum).Maximum
        $totalGB = [math]::Round(($mem | Measure-Object -Property Capacity -Sum).Sum / 1GB)
        $stickGB = [math]::Round(($mem | Select-Object -First 1).Capacity / 1GB)

        if($board){ [void]$sp.Children.Add((New-Text "เมนบอร์ด: $($board.Manufacturer) $($board.Product)" 12.5 $Theme.BodyFg "SemiBold")) }
        [void]$sp.Children.Add((New-Text "CPU: $($cpu.Name.Trim())  •  Socket $($cpu.SocketDesignation)" 12 $Theme.MutedFg))
        $sum = New-Text ("RAM: $totalGB GB  •  $type-$speed  $form" + $(if($maxGB -gt 0){ "  •  ใส่ได้สูงสุด $maxGB GB (ตามข้อมูล BIOS)" } else { "" })) 12 $Theme.MutedFg
        $sum.Margin = "0,0,0,10"; [void]$sp.Children.Add($sum)

        $wp = New-Object System.Windows.Controls.WrapPanel
        for($i = 0; $i -lt $slots; $i++){
            $m = if($i -lt $mem.Count){ $mem[$i] } else { $null }
            $b = New-Object System.Windows.Controls.Border
            $b.Width = 112; $b.Height = 62; $b.CornerRadius = "10"; $b.Margin = "0,0,8,8"; $b.Padding = "10,6"; $b.BorderThickness = "1.5"
            $st = New-Object System.Windows.Controls.StackPanel
            if($m){
                $b.Background = (NewBrush $Theme.AccentSoft); $b.BorderBrush = (NewBrush "#EE6C2B")
                [void]$st.Children.Add((New-Text ("{0} GB" -f [math]::Round($m.Capacity / 1GB)) 15 "#EE6C2B" "Bold"))
                $mk = if($m.Manufacturer -and $m.Manufacturer -ne 'Unknown'){ $m.Manufacturer.Trim() } else { "$type-$($m.Speed)" }
                $mt = New-Text $mk 10.5 $Theme.MutedFg; $mt.TextTrimming = 'CharacterEllipsis'; $mt.TextWrapping = 'NoWrap'; $mt.ToolTip = "$($m.DeviceLocator) • $($m.PartNumber)"
                [void]$st.Children.Add($mt)
            } else {
                $b.Background = (NewBrush $Theme.CardBg); $b.BorderBrush = (NewBrush $Theme.ChipBorder)
                [void]$st.Children.Add((New-Text "ว่าง" 15 $Theme.MutedFg "Bold"))
                [void]$st.Children.Add((New-Text "ช่อง $($i + 1)" 10.5 $Theme.MutedFg))
            }
            $b.Child = $st
            [void]$wp.Children.Add($b)
        }
        [void]$sp.Children.Add($wp)

        $free = $slots - $mem.Count
        $tip = if($free -gt 0){
            "เพิ่ม RAM ได้อีก $free แผง — แนะนำ $type-$speed $(($form -split ' ')[0]) ขนาด $stickGB GB ให้เท่าของเดิม เพื่อทำงานแบบ Dual Channel"
        } elseif($maxGB -gt $totalGB){
            $next = [math]::Min($maxGB, $totalGB * 2)
            "ช่องเต็มแล้ว ($slots ช่อง) — ถ้าจะเพิ่มต้องเปลี่ยนเป็นแผงใหญ่ขึ้น เช่น $slots x $([math]::Round($next / $slots)) GB = $next GB ($type-$speed)"
        } else { "ช่องเต็มและใส่ถึงความจุสูงสุดแล้ว" }
        if($mem.Count -eq 1 -and $slots -ge 2){ $tip += "`nตอนนี้ใส่แผงเดียว (Single Channel) — ใส่เพิ่มอีก 1 แผงขนาดเท่ากันจะเร็วขึ้นชัดเจน" }
        $tt = New-Text $tip 12 $Theme.BodyFg; $tt.Margin = "0,4,0,0"
        [void]$sp.Children.Add($tt)

        $disks = @(Get-PhysicalDisk -ErrorAction SilentlyContinue | Sort-Object { [int]$_.DeviceId })
        if($disks.Count){
            $dt = New-Text ("ดิสก์: " + (($disks | ForEach-Object { "$($_.FriendlyName.Trim()) ($($_.MediaType) $($_.BusType), $(Fmt-Size $_.Size))" }) -join "  •  ")) 11.5 $Theme.MutedFg
            $dt.Margin = "0,8,0,0"; [void]$sp.Children.Add($dt)
        }
    }catch{ [void]$sp.Children.Add((New-Text "อ่านข้อมูลฮาร์ดแวร์ไม่ได้: $($_.Exception.Message)" 12 $Theme.MutedFg)) }
}

# ---------- ทดสอบความเร็วดิสก์ ----------
function Load-BenchDrives {
    $wp = $ui.BenchDrives; $wp.Children.Clear(); $first = $true
    foreach($d in [System.IO.DriveInfo]::GetDrives()){
        try{
            if(-not $d.IsReady -or ($d.DriveType -ne 'Fixed' -and $d.DriveType -ne 'Removable')){ continue }
            $rb = New-Object System.Windows.Controls.RadioButton
            $rb.Style = $window.FindResource("Seg"); $rb.GroupName = "benchdrive"; $rb.Tag = $d.RootDirectory.FullName
            $rb.Content = $d.Name.TrimEnd('\') + $(if($d.VolumeLabel){ " $($d.VolumeLabel)" } else { "" })
            if($first){ $rb.IsChecked = $true; $first = $false }
            [void]$wp.Children.Add($rb)
        }catch{}
    }
}
$ui.BtnBench.Add_Click({
    if($script:Bench){ $script:Bench.Cancel = $true; return }
    $root = $null; foreach($rb in $ui.BenchDrives.Children){ if($rb.IsChecked){ $root = [string]$rb.Tag } }
    if(-not $root){ return }
    $mb = if($ui.bench_1024.IsChecked){ 1024 } else { 256 }
    $free = (New-Object System.IO.DriveInfo($root)).AvailableFreeSpace
    if($free -lt ($mb + 512) * 1MB){ Show-Msg "พื้นที่ว่างในไดรฟ์ $root ไม่พอสำหรับไฟล์ทดสอบ $mb MB" "ทดสอบดิสก์" "Warning"; return }
    $dir = if($root -ieq ($env:SystemDrive + '\')){ $env:TEMP } else { $root }
    $script:Bench = New-Object Scp.DiskBench
    $task = $script:Bench.Start($dir, [long]$mb * 1MB)
    $ui.BtnBench.Content = "หยุด"; $ui.BenchBar.Visibility = 'Visible'; $ui.BenchBar.Value = 0
    foreach($t in @($ui.BenchRead, $ui.BenchWrite, $ui.BenchRand)){ $t.Text = "..." }
    $ui.BenchVerdict.Text = "กำลังทดสอบไดรฟ์ $root ..."
    $null = Watch-Task $task {
        param($res, $err, $job)
        $b = $script:Bench; $script:Bench = $null
        $ui.BtnBench.Content = "เริ่มทดสอบ"; $ui.BenchBar.Visibility = 'Collapsed'
        if($err){ $ui.BenchVerdict.Text = "ทดสอบไม่สำเร็จ: $err"; return }
        if($b.Cancel){ $ui.BenchVerdict.Text = "หยุดการทดสอบแล้ว"; return }
        $ui.BenchRead.Text = "{0:N0} MB/s" -f $b.SeqRead; $ui.BenchWrite.Text = "{0:N0} MB/s" -f $b.SeqWrite
        $ui.BenchRand.Text = "{0:N1} MB/s" -f $b.RandRead
        $kind = if($b.SeqRead -ge 1500){ "ระดับ SSD NVMe — เร็วมาก" } elseif($b.SeqRead -ge 350){ "ระดับ SSD SATA — ปกติดี" } elseif($b.SeqRead -ge 80){ "ระดับฮาร์ดดิสก์ (HDD)" } else { "ช้ากว่าปกติมาก — ดิสก์อาจเสื่อม สายหลวม หรือเป็น USB 2.0" }
        $ui.BenchVerdict.Text = "ไดรฟ์ $($job.State): $kind  •  อ่านสุ่ม {0:N0} IOPS" -f $b.RandIops
        if($b.RandIops -lt 300 -and $b.SeqRead -ge 350){ $ui.BenchVerdict.Text += "  • ⚠ อ่านสุ่มต่ำผิดปกติสำหรับ SSD" }
    } {
        param($job)
        if($script:Bench){
            $ui.BenchBar.Value = $script:Bench.Progress * 100
            $ph = switch($script:Bench.Phase){ 'write' { "กำลังทดสอบเขียน..." } 'read' { "กำลังทดสอบอ่าน..." } 'random' { "กำลังทดสอบอ่านแบบสุ่ม 4K..." } default { "กำลังเตรียม..." } }
            $ui.BenchVerdict.Text = $ph
        }
    } -State $root
})

# ---------- ทดสอบ CPU ----------
function Get-CpuMhz {
    try{
        $pp = (Get-CimInstance Win32_PerfFormattedData_Counters_ProcessorInformation -Filter "Name='_Total'" -ErrorAction Stop).PercentProcessorPerformance
        if(-not $script:CpuBaseMhz){ $script:CpuBaseMhz = (Get-CimInstance Win32_Processor | Select-Object -First 1).MaxClockSpeed }
        return [math]::Round($script:CpuBaseMhz * $pp / 100)
    }catch{ return $null }
}
function Get-CpuTemp {
    try{
        $z = @(Get-CimInstance -Namespace root\wmi -ClassName MSAcpi_ThermalZoneTemperature -ErrorAction Stop)
        if($z.Count){ return [math]::Round((($z | Measure-Object CurrentTemperature -Maximum).Maximum / 10) - 273.15) }
    }catch{}
    return $null
}
$script:StressTimer = New-Object System.Windows.Threading.DispatcherTimer
$script:StressTimer.Interval = [TimeSpan]::FromSeconds(1)
$script:StressTimer.Add_Tick({
    try{
        $s = $script:StressStat
        $cpu = [Scp.Sys]::CpuPercent(); $mhz = Get-CpuMhz; $temp = Get-CpuTemp
        $ui.StressCpu.Text = "{0:0}%" -f $cpu
        if($mhz){ $ui.StressMhz.Text = "{0:N0} MHz" -f $mhz; if($mhz -lt $s.MinMhz){ $s.MinMhz = $mhz }; if($mhz -gt $s.MaxMhz){ $s.MaxMhz = $mhz } }
        if($temp){ $ui.StressTemp.Text = "$temp°C"; if($temp -gt $s.MaxTemp){ $s.MaxTemp = $temp } } else { $ui.StressTemp.Text = "ไม่รายงาน" }
        $left = [math]::Max(0, [math]::Round(($s.End - (Get-Date)).TotalSeconds))
        $ui.StressResult.Text = "กำลังทดสอบ... เหลือ $left วินาที (ใช้งานหน้าอื่นได้ แต่เครื่องจะหน่วง)"
        if(-not $script:Stress.Running){
            $script:StressTimer.Stop(); $ui.BtnStress.Content = "เริ่มทดสอบ CPU"
            $base = $script:CpuBaseMhz
            $r = "ทดสอบเสร็จ — เครื่องไม่ค้าง/ไม่ดับระหว่างทดสอบ ✓"
            if($s.MaxMhz -gt 0){
                $r += "`nความเร็วระหว่างทดสอบ {0:N0} - {1:N0} MHz (ความเร็วพื้นฐาน {2:N0} MHz)" -f $s.MinMhz, $s.MaxMhz, $base
                if($s.MinMhz -lt $base * 0.7){ $r += "`n⚠ ความเร็วตกต่ำกว่าพื้นฐานมาก — อาจร้อนจนลดความเร็ว (Thermal throttling) ควรเป่าฝุ่น/เปลี่ยนซิลิโคน หรือดูการตั้งค่าพลังงาน" }
            }
            if($s.MaxTemp -gt 0){ $r += "`nอุณหภูมิสูงสุด $($s.MaxTemp)°C" + $(if($s.MaxTemp -ge 90){ " — ⚠ ร้อนมาก" } elseif($s.MaxTemp -ge 80){ " — ค่อนข้างร้อน" } else { " — ปกติ" }) }
            $ui.StressResult.Text = $r
            $script:Stress = $null
        }
    }catch{}
})
$ui.BtnStress.Add_Click({
    if($script:Stress){ $script:Stress.Stop = $true; return }
    $sec = 60; foreach($rb in @($ui.stress_30, $ui.stress_60, $ui.stress_300)){ if($rb.IsChecked){ $sec = [int]$rb.Tag } }
    [void][Scp.Sys]::CpuPercent()
    $script:StressStat = @{ MinMhz = [double]::MaxValue; MaxMhz = 0; MaxTemp = 0; End = (Get-Date).AddSeconds($sec) }
    $script:Stress = New-Object Scp.CpuStress
    $script:Stress.Start($sec)
    $ui.BtnStress.Content = "หยุดทดสอบ"
    $script:StressTimer.Start()
})

# ---------- ทดสอบ RAM ----------
function Load-MemTestResult {
    try{
        $e = Get-WinEvent -FilterHashtable @{ LogName='System'; ProviderName='Microsoft-Windows-MemoryDiagnostics-Results' } -MaxEvents 1 -ErrorAction Stop
        $ok = ($e.Id -eq 1101 -or $e.Id -eq 1201)
        $ui.MemTestLast.Text = "ผลตรวจครั้งล่าสุด ($($e.TimeCreated.ToString('dd/MM/yyyy HH:mm'))): " + $(if($ok){ "✓ ไม่พบปัญหา RAM" } else { "⚠ " + (($e.Message -split "`n")[0]) })
        $ui.MemTestLast.Foreground = (NewBrush $(if($ok){ "#22A06B" } else { "#E5484D" }))
    }catch{ $ui.MemTestLast.Text = "ยังไม่เคยตรวจ RAM ด้วย Windows Memory Diagnostic" }
}
$ui.BtnMemTest.Add_Click({
    if(-not (Ask-YesNo "เปิด Windows Memory Diagnostic?`n`nในหน้าต่างถัดไป เลือก 'Restart now and check for problems'`nเครื่องจะรีสตาร์ทและตรวจ RAM ประมาณ 10-20 นาที — บันทึกงานให้เรียบร้อยก่อน")){ return }
    try{ Start-Process mdsched.exe }catch{ Show-Msg "เปิดไม่ได้: $($_.Exception.Message)" "ทดสอบ RAM" "Warning" }
})

# ---------- อุปกรณ์ที่มีปัญหา ----------
$DevErr = @{ 1='ตั้งค่าไม่ถูกต้อง'; 3='ไดรเวอร์เสีย หรือหน่วยความจำไม่พอ'; 10='เริ่มทำงานไม่ได้'; 12='ทรัพยากรชนกัน'; 14='ต้องรีสตาร์ทเครื่อง'; 18='ต้องติดตั้งไดรเวอร์ใหม่'; 19='ข้อมูลใน Registry เสีย'; 22='ถูกปิดใช้งาน'; 28='ยังไม่ได้ติดตั้งไดรเวอร์'; 31='ทำงานไม่ถูกต้อง'; 32='บริการของไดรเวอร์ถูกปิด'; 37='โหลดไดรเวอร์ไม่สำเร็จ'; 39='ไดรเวอร์เสียหายหรือหายไป'; 43='อุปกรณ์รายงานว่ามีปัญหา (มักฮาร์ดแวร์เสีย/USB หลวม)'; 52='ไดรเวอร์ไม่มีลายเซ็นดิจิทัล' }
function Load-ProblemDevices {
    $sp = $ui.DevList; $sp.Children.Clear()
    $devs = @()
    try{ $devs = @(Get-CimInstance Win32_PnPEntity -ErrorAction Stop | Where-Object { $_.ConfigManagerErrorCode -ne 0 -and $_.ConfigManagerErrorCode -ne 45 -and $_.ConfigManagerErrorCode -ne 24 }) }catch{}
    if($devs.Count -eq 0){ $t = New-Text "✓ ไม่พบอุปกรณ์ที่มีปัญหา — ไดรเวอร์ครบทุกตัว" 12.5 "#22A06B" "SemiBold"; [void]$sp.Children.Add($t); return }
    foreach($d in $devs){
        $c = New-Card "14,10" "0,0,0,6"
        $g = New-Grid @('*','Auto')
        $st = New-Object System.Windows.Controls.StackPanel
        $nm = if($d.Name){ $d.Name } else { "อุปกรณ์ที่ไม่รู้จัก" }
        [void]$st.Children.Add((New-Text $nm 13 $Theme.BodyFg "SemiBold"))
        $code = [int]$d.ConfigManagerErrorCode
        $msg = if($DevErr.ContainsKey($code)){ $DevErr[$code] } else { "ปัญหารหัส $code" }
        [void]$st.Children.Add((New-Text "รหัส $code — $msg" 11.5 $(if($code -eq 28){ "#E5484D" } else { "#F5A623" })))
        $hwid = @($d.HardwareID)[0]
        if($hwid){ $ht = New-CopyText $hwid; $ht.FontFamily = New-Object System.Windows.Media.FontFamily("Consolas"); $ht.FontSize = 11.5; $ht.Margin = "0,4,0,0"; [void]$st.Children.Add($ht) }
        Add-ToGrid $g $st 0
        $bp = New-Object System.Windows.Controls.StackPanel; $bp.Orientation = 'Horizontal'; $bp.VerticalAlignment = 'Center'
        if($hwid){
            $b1 = New-Object System.Windows.Controls.Button; $b1.Style = $window.FindResource("Link"); $b1.Content = "คัดลอก ID"; $b1.Tag = $hwid
            $b1.Add_Click({ try{ [System.Windows.Clipboard]::SetText([string]$this.Tag); $this.Content = "คัดลอกแล้ว ✓" }catch{} })
            [void]$bp.Children.Add($b1)
            $b2 = New-Object System.Windows.Controls.Button; $b2.Style = $window.FindResource("Link"); $b2.Content = "ค้นหาไดรเวอร์"; $b2.Tag = $hwid
            $b2.Add_Click({ $q = [Uri]::EscapeDataString(([string]$this.Tag -replace '&SUBSYS.*$|&REV.*$', '') + " driver"); Start-Process "https://www.google.com/search?q=$q" })
            [void]$bp.Children.Add($b2)
        }
        Add-ToGrid $g $bp 1
        $c.Child = $g
        [void]$sp.Children.Add($c)
    }
}
$ui.BtnDevMgr.Add_Click({ Start-Process devmgmt.msc })
$ui.BtnDevScan.Add_Click({
    $ui.BtnDevScan.IsEnabled = $false; $ui.BtnDevScan.Content = "กำลังค้นหา..."
    $null = Start-BgWork -Work { param($Sync) $p = Start-Process pnputil.exe -ArgumentList "/scan-devices" -WindowStyle Hidden -PassThru; [void]$p.WaitForExit(60000); $p.ExitCode } -OnDone {
        param($res, $err)
        $ui.BtnDevScan.IsEnabled = $true; $ui.BtnDevScan.Content = "ค้นหาอุปกรณ์ใหม่"
        Load-ProblemDevices
    }
})


# ============================================================
#   ย้าย / สำรองข้อมูลลูกค้า (ก่อนลง Windows ใหม่) และกู้คืน
# ============================================================
$BkFolderDefs = @(
    @{ Key='desktop';   Name='Desktop (หน้าจอ)';     Sub='Desktop';   Special='Desktop';     Def=$true }
    @{ Key='documents'; Name='Documents (เอกสาร)';   Sub='Documents'; Special='MyDocuments'; Def=$true }
    @{ Key='pictures';  Name='Pictures (รูปภาพ)';     Sub='Pictures';  Special='MyPictures';  Def=$true }
    @{ Key='videos';    Name='Videos (วิดีโอ)';       Sub='Videos';    Special='MyVideos';    Def=$true }
    @{ Key='music';     Name='Music (เพลง)';          Sub='Music';     Special='MyMusic';     Def=$true }
    @{ Key='downloads'; Name='Downloads (ดาวน์โหลด)'; Sub='Downloads'; Special=$null;          Def=$false }
)

function Get-ProfileFolder($profile, $def){
    if($profile -ieq $env:USERPROFILE){
        if($def.Special){ try{ $p = [Environment]::GetFolderPath($def.Special); if($p -and (Test-Path $p)){ return $p } }catch{} }
        if($def.Key -eq 'downloads'){
            try{ $p = (Get-ItemProperty 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\User Shell Folders' -ErrorAction Stop).'{374DE290-123F-4565-9164-39C4925E467B}'; if($p){ $p = [Environment]::ExpandEnvironmentVariables($p); if(Test-Path $p){ return $p } } }catch{}
        }
    }
    foreach($c in @((Join-Path $profile $def.Sub), (Join-Path $profile "OneDrive\$($def.Sub)"))){ if(Test-Path $c){ return $c } }
    return $null
}

# รายการสิ่งที่สำรองได้ของโปรไฟล์ผู้ใช้ (src, dst ภายในโฟลเดอร์สำรอง)
function Get-BackupItems($profile){
    $items = New-Object System.Collections.Generic.List[object]
    foreach($d in $BkFolderDefs){
        $p = Get-ProfileFolder $profile $d
        if($p){ $items.Add(@{ Key=$d.Key; Name=$d.Name; Desc=$p; Pairs=@(,@($p, "Files\$($d.Sub)")); Specs=@("D|$p"); Def=$d.Def; Kind='files' }) }
    }
    $L = Join-Path $profile "AppData\Local"; $R = Join-Path $profile "AppData\Roaming"
    $pairs = @(); $specs = @(); $found = @()
    foreach($b in @(@('Chrome', "$L\Google\Chrome\User Data"), @('Edge', "$L\Microsoft\Edge\User Data"), @('Brave', "$L\BraveSoftware\Brave-Browser\User Data"))){
        if(-not (Test-Path $b[1])){ continue }
        foreach($prof in @(Get-ChildItem $b[1] -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -eq 'Default' -or $_.Name -like 'Profile *' })){
            $bm = Join-Path $prof.FullName 'Bookmarks'
            if(Test-Path $bm){ $pairs += ,@($bm, "Browsers\$($b[0])\$($prof.Name)\Bookmarks"); $specs += "F|$($prof.FullName)|Bookmarks"; $found += "$($b[0]) ($($prof.Name))" }
        }
    }
    if(Test-Path "$R\Mozilla\Firefox\Profiles"){
        foreach($prof in @(Get-ChildItem "$R\Mozilla\Firefox\Profiles" -Directory -ErrorAction SilentlyContinue)){
            $pl = Join-Path $prof.FullName 'places.sqlite'
            if(Test-Path $pl){ $pairs += ,@($pl, "Browsers\Firefox\$($prof.Name)\places.sqlite"); $specs += "F|$($prof.FullName)|places.sqlite"; $found += "Firefox" }
        }
    }
    if($pairs.Count){ $items.Add(@{ Key='browsers'; Name='บุ๊กมาร์กเว็บเบราว์เซอร์'; Desc=(($found | Select-Object -Unique) -join ', ') + ' — (รหัสผ่านที่บันทึกไว้ย้ายไม่ได้ ให้ใช้การ Sync บัญชี Google/Microsoft)'; Pairs=$pairs; Specs=$specs; Def=$true; Kind='files' }) }
    $items.Add(@{ Key='wifi'; Name='รหัส Wi-Fi ที่บันทึกไว้'; Desc='ทุกเครือข่ายที่เครื่องนี้เคยต่อ (เก็บรหัสไว้ในไฟล์สำรอง — เก็บ USB ให้ดี)'; Pairs=@(); Specs=@(); Def=$true; Kind='wifi' })
    $items.Add(@{ Key='apps'; Name='รายการโปรแกรมที่ติดตั้ง'; Desc='บันทึกเป็นไฟล์ข้อความ ไว้ดูว่าต้องลงโปรแกรมอะไรคืนให้ลูกค้า'; Pairs=@(); Specs=@(); Def=$true; Kind='apps' })
    $items.Add(@{ Key='drivers'; Name='ไดรเวอร์ทั้งหมด'; Desc='สำรองด้วย DISM (2-10 นาที) — มีประโยชน์ถ้าเครื่องไม่มีเน็ตหลังลงใหม่'; Pairs=@(); Specs=@(); Def=$false; Kind='drivers' })
    return $items
}

function Init-BackupPage {
    $script:BkLoaded = $true
    $wp = $ui.BkUsers; $wp.Children.Clear()
    $profiles = @(Get-ChildItem "$env:SystemDrive\Users" -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -notin @('Public','Default','Default User','All Users','defaultuser0') -and (Test-Path (Join-Path $_.FullName 'NTUSER.DAT')) })
    foreach($p in $profiles){
        $rb = New-Object System.Windows.Controls.RadioButton
        $rb.Style = $window.FindResource("Seg"); $rb.GroupName = "bkuser"; $rb.Tag = $p.FullName
        $rb.Content = $p.Name + $(if($p.FullName -ieq $env:USERPROFILE){ " (ผู้ใช้ปัจจุบัน)" } else { "" })
        if($p.FullName -ieq $env:USERPROFILE){ $rb.IsChecked = $true }
        $rb.Add_Checked({ Build-BackupItems $this.Tag })
        [void]$wp.Children.Add($rb)
    }
    Build-BackupItems $env:USERPROFILE
}

function Build-BackupItems($profile){
    $script:BkProfile = $profile
    $script:BkItems = Get-BackupItems $profile
    $sp = $ui.BkItems; $sp.Children.Clear()
    $script:BkRows = New-Object System.Collections.Generic.List[object]
    foreach($it in $script:BkItems){
        $card = New-Card "16,10" "0,0,0,8"
        $g = New-Grid @('Auto','*','Auto')
        $cb = New-Object System.Windows.Controls.CheckBox; $cb.Style = $window.FindResource("Toggle"); $cb.IsChecked = $it.Def; $cb.VerticalAlignment = 'Center'
        $cb.Add_Click({ Update-BkTotal })
        Add-ToGrid $g $cb 0
        $st = New-Object System.Windows.Controls.StackPanel; $st.Margin = "16,0,12,0"; $st.VerticalAlignment = 'Center'
        [void]$st.Children.Add((New-Text $it.Name 13.5 $Theme.BodyFg "SemiBold"))
        $d = New-Text $it.Desc 11.5 $Theme.MutedFg; $d.Margin = "0,2,0,0"; [void]$st.Children.Add($d)
        Add-ToGrid $g $st 1
        $sz = New-Text $(if($it.Kind -eq 'files'){ "กำลังคำนวณ..." } else { "" }) 13 $Theme.BodyFg "Bold"; $sz.VerticalAlignment = 'Center'; $sz.MinWidth = 80; $sz.TextAlignment = 'Right'
        Add-ToGrid $g $sz 2
        $card.Child = $g
        [void]$sp.Children.Add($card)
        $script:BkRows.Add(@{ Item=$it; Cb=$cb; SizeTb=$sz; Size=0 })
    }
    $files = @($script:BkRows | Where-Object { $_.Item.Kind -eq 'files' })
    $jag = New-Object 'string[][]' $files.Count
    for($i = 0; $i -lt $files.Count; $i++){ $jag[$i] = [string[]]@($files[$i].Item.Specs) }
    $ui.BkStatus.Text = "กำลังคำนวณขนาด..."
    $null = Watch-Task ([Scp.Cleaner]::Measure($jag)) {
        param($res, $err, $job)
        if($job.State.Profile -ne $script:BkProfile){ return }
        $rows = $job.State.Rows
        for($i = 0; $i -lt $rows.Count; $i++){
            $rows[$i].Size = if($res){ $res[2*$i] } else { 0 }
            $rows[$i].SizeTb.Text = (Fmt-Size $rows[$i].Size); $rows[$i].SizeTb.ToolTip = "{0:N0} ไฟล์" -f $(if($res){ $res[2*$i+1] } else { 0 })
        }
        Update-BkTotal
    } -State @{ Profile=$profile; Rows=$files }
}

function Update-BkTotal {
    $sum = 0; foreach($r in $script:BkRows){ if($r.Cb.IsChecked){ $sum += $r.Size } }
    $script:BkSelBytes = $sum
    if(-not $script:BkBusy){ $ui.BkStatus.Text = "เลือกไว้ประมาณ $(Fmt-Size $sum)" + $(if($ui.BkDest.Text){ "  →  $($ui.BkDest.Text)" } else { "  — เลือกปลายทางก่อนเริ่ม" }) }
    Update-BkDestInfo
}
function Update-BkDestInfo {
    $p = $ui.BkDest.Text
    if(-not $p){ $ui.BkDestInfo.Text = ""; return }
    try{
        $di = New-Object System.IO.DriveInfo([IO.Path]::GetPathRoot($p))
        $ok = $di.AvailableFreeSpace -gt ($script:BkSelBytes * 1.05)
        $ui.BkDestInfo.Text = "ไดรฟ์ $($di.Name) ว่าง $(Fmt-Size $di.AvailableFreeSpace)" + $(if($ok){ "  ✓ พอสำหรับข้อมูลที่เลือก" } else { "  ⚠ พื้นที่ไม่พอ!" })
        $ui.BkDestInfo.Foreground = (NewBrush $(if($ok){ "#22A06B" } else { "#E5484D" }))
    }catch{}
}

$ui.bk_backup.Add_Checked({ $ui.BkBackupPanel.Visibility = 'Visible'; $ui.BkRestorePanel.Visibility = 'Collapsed'; $ui.BtnBkRun.Content = "เริ่มสำรองข้อมูล"; Update-BkTotal })
$ui.bk_restore.Add_Checked({ $ui.BkBackupPanel.Visibility = 'Collapsed'; $ui.BkRestorePanel.Visibility = 'Visible'; $ui.BtnBkRun.Content = "เริ่มกู้คืน"; $ui.BkStatus.Text = "เลือกโฟลเดอร์สำรองก่อน" })
$ui.BtnBkDest.Add_Click({
    $f = Pick-Folder "เลือกไดรฟ์ USB หรือโฟลเดอร์ที่จะเก็บข้อมูลสำรอง" $null
    if($f){ $ui.BkDest.Text = $f; Update-BkTotal }
})
$ui.BtnBkCancel.Add_Click({ if($script:BkCopier){ $script:BkCopier.Cancel = $true; $ui.BkStatus.Text = "กำลังหยุด..." } })
$ui.BtnBkOpen.Add_Click({ if($this.Tag){ Open-Path $this.Tag } })

function Set-BkBusy($busy){
    $script:BkBusy = $busy
    $ui.BtnBkRun.IsEnabled = -not $busy; $ui.BtnBkCancel.Visibility = if($busy){ 'Visible' } else { 'Collapsed' }
    $ui.BkBar.Visibility = if($busy){ 'Visible' } else { 'Collapsed' }
    $ui.bk_backup.IsEnabled = -not $busy; $ui.bk_restore.IsEnabled = -not $busy
}

$ui.BtnBkRun.Add_Click({ if($ui.bk_restore.IsChecked){ Start-Restore } else { Start-Backup } })

# ---------- สำรอง ----------
function Start-Backup {
    $sel = @($script:BkRows | Where-Object { $_.Cb.IsChecked })
    if($sel.Count -eq 0){ Show-Msg "เลือกอย่างน้อย 1 รายการ" "สำรองข้อมูล"; return }
    $dest = $ui.BkDest.Text
    if(-not $dest -or -not (Test-Path $dest)){ Show-Msg "เลือกปลายทางก่อน (แนะนำ USB หรือ External HDD)" "สำรองข้อมูล" "Warning"; return }
    $di = New-Object System.IO.DriveInfo([IO.Path]::GetPathRoot($dest))
    if($di.AvailableFreeSpace -lt $script:BkSelBytes * 1.05){ Show-Msg "พื้นที่ปลายทางไม่พอ (ว่าง $(Fmt-Size $di.AvailableFreeSpace) แต่ต้องใช้ประมาณ $(Fmt-Size $script:BkSelBytes))" "สำรองข้อมูล" "Warning"; return }
    $srcRoot = [IO.Path]::GetPathRoot($script:BkProfile)
    if([IO.Path]::GetPathRoot($dest) -ieq $srcRoot -and -not (Ask-YesNo "ปลายทางอยู่ไดรฟ์เดียวกับข้อมูล ($srcRoot)`nถ้าจะลง Windows ใหม่/ฟอร์แมต ข้อมูลสำรองจะหายด้วย`n`nยืนยันใช้ปลายทางนี้?" "ระวัง" "Warning")){ return }
    $user = Split-Path $script:BkProfile -Leaf
    $root = Join-Path $dest ("SCPclear-Backup-$env:COMPUTERNAME-$user-" + (Get-Date).ToString('yyyyMMdd_HHmm', [Globalization.CultureInfo]::InvariantCulture))
    try{ New-Item -ItemType Directory -Path $root -Force | Out-Null }catch{ Show-Msg "สร้างโฟลเดอร์ปลายทางไม่ได้: $($_.Exception.Message)" "สำรองข้อมูล" "Warning"; return }
    Set-BkBusy $true; $ui.BtnBkOpen.Visibility = 'Collapsed'
    $keys = @($sel | ForEach-Object { $_.Item.Key })
    $log = New-Object System.Collections.Generic.List[string]
    # Wi-Fi และรายการโปรแกรม ทำก่อน (เร็ว)
    if($keys -contains 'wifi'){
        $ui.BkStatus.Text = "กำลังสำรองรหัส Wi-Fi..."; Flush-UI
        $wdir = Join-Path $root "WiFi"; New-Item -ItemType Directory -Path $wdir -Force | Out-Null
        try{ $p = Start-Process netsh.exe -ArgumentList "wlan export profile key=clear folder=`"$wdir`"" -WindowStyle Hidden -PassThru; [void]$p.WaitForExit(20000) }catch{}
        $log.Add("Wi-Fi: " + @(Get-ChildItem $wdir -Filter *.xml -ErrorAction SilentlyContinue).Count + " เครือข่าย")
    }
    if($keys -contains 'apps'){
        $ui.BkStatus.Text = "กำลังบันทึกรายการโปรแกรม..."; Flush-UI
        try{
            $apps = @(Get-InstalledApps $false $false | Sort-Object Name)
            $lines = @("รายการโปรแกรมในเครื่อง $env:COMPUTERNAME  (สำรองเมื่อ $(Get-Date -Format 'dd/MM/yyyy HH:mm'))", "")
            $lines += $apps | ForEach-Object { "{0}   [{1}]   {2}" -f $_.Name, $_.Version, $_.Publisher }
            $lines | Set-Content -Path (Join-Path $root "รายการโปรแกรมที่เคยติดตั้ง.txt") -Encoding UTF8
            $log.Add("รายการโปรแกรม: $($apps.Count) รายการ")
        }catch{}
    }
    $src = New-Object System.Collections.Generic.List[string]; $dst = New-Object System.Collections.Generic.List[string]
    foreach($r in $sel){ foreach($pair in @($r.Item.Pairs)){ if($pair){ $src.Add($pair[0]); $dst.Add((Join-Path $root $pair[1])) } } }
    $total = 0; foreach($r in $sel){ $total += $r.Size }
    $script:BkCopier = New-Object Scp.BackupCopier
    $task = $script:BkCopier.Start($src.ToArray(), $dst.ToArray(), $false)
    $null = Watch-Task $task {
        param($res, $err, $job)
        $c = $script:BkCopier; $st = $job.State
        $manifest = [ordered]@{
            App = "SCPclear $ScriptVersion"; Computer = $env:COMPUTERNAME; User = $st.User; Date = (Get-Date).ToString('dd/MM/yyyy HH:mm')
            Items = $st.Keys; Files = $c.Files; Bytes = $c.CopiedBytes; Failed = $c.Failed; Cancelled = [bool]$c.Cancel
        }
        ($manifest | ConvertTo-Json -Depth 4) | Set-Content -Path (Join-Path $st.Root "manifest.json") -Encoding UTF8
        if($c.Errors.Count){ $c.Errors | Set-Content -Path (Join-Path $st.Root "ไฟล์ที่คัดลอกไม่ได้.txt") -Encoding UTF8 }
        $summary = "คัดลอก {0:N0} ไฟล์ ({1})" -f $c.Files, (Fmt-Size $c.CopiedBytes)
        if($c.Failed){ $summary += " • คัดลอกไม่ได้ {0:N0} ไฟล์ (ดูรายชื่อในไฟล์ 'ไฟล์ที่คัดลอกไม่ได้.txt')" -f $c.Failed }
        $script:BkCopier = $null
        if($st.Keys -contains 'drivers' -and -not $manifest.Cancelled){
            $ui.BkStatus.Text = "$summary • กำลังสำรองไดรเวอร์ (2-10 นาที)..."
            $ddir = Join-Path $st.Root "Drivers"; New-Item -ItemType Directory -Path $ddir -Force | Out-Null
            $pr = New-Object Scp.ProcRun
            $pr.Start((Join-Path $env:SystemRoot "System32\dism.exe"), "/Online /Export-Driver /Destination:`"$ddir`"", $false)
            $null = Watch-Proc $pr { param($code, $e2, $j2) Finish-Backup $j2.State.Root ($j2.State.Summary + " • ไดรเวอร์: " + $(if($code -eq 0){ "สำรองแล้ว" } else { "ไม่สำเร็จ (รหัส $code)" })) } -State @{ Root=$st.Root; Summary=$summary }
        } else { Finish-Backup $st.Root $summary }
    } {
        param($job)
        $c = $script:BkCopier; if(-not $c){ return }
        $pct = if($job.State.Total -gt 0){ [math]::Min(100, $c.CopiedBytes / $job.State.Total * 100) } else { 0 }
        $ui.BkBar.Value = $pct
        $ui.BkStatus.Text = "กำลังคัดลอก {0:0}%  •  {1} / {2}  •  {3}" -f $pct, (Fmt-Size $c.CopiedBytes), (Fmt-Size $job.State.Total), [IO.Path]::GetFileName($c.Current)
    } -State @{ Root=$root; Keys=$keys; User=$user; Total=$total }
}
function Finish-Backup($root, $summary){
    Set-BkBusy $false
    $ui.BkStatus.Text = "✓ สำรองเสร็จ — $summary"
    $ui.BtnBkOpen.Tag = $root; $ui.BtnBkOpen.Visibility = 'Visible'
    Add-HistoryEntry "สำรองข้อมูล" "สำรองไปที่ $root" "สำเร็จ: $summary"
    Show-Msg "สำรองข้อมูลเสร็จแล้ว`n`n$summary`n`nเก็บไว้ที่:`n$root`n`nตรวจดูไฟล์ในโฟลเดอร์ก่อนฟอร์แมตเครื่องทุกครั้ง" "สำรองข้อมูล"
}

# ---------- กู้คืน ----------
$ui.BtnBkSrc.Add_Click({
    $f = Pick-Folder "เลือกโฟลเดอร์ SCPclear-Backup-... ที่สำรองไว้" $null
    if(-not $f){ return }
    $mf = Join-Path $f "manifest.json"
    if(-not (Test-Path $mf)){ Show-Msg "โฟลเดอร์นี้ไม่ใช่ข้อมูลสำรองของ SCPclear (ไม่พบ manifest.json)`nเลือกโฟลเดอร์ที่ชื่อขึ้นต้นด้วย SCPclear-Backup-" "กู้คืนข้อมูล" "Warning"; return }
    $m = Get-Content $mf -Raw -Encoding UTF8 | ConvertFrom-Json
    $ui.BkSrc.Text = $f
    $ui.BkSrcInfo.Text = "สำรองจากเครื่อง $($m.Computer) ผู้ใช้ $($m.User) เมื่อ $($m.Date) • {0:N0} ไฟล์ ({1})" -f $m.Files, (Fmt-Size $m.Bytes)
    Build-RestoreItems $f
})
function Build-RestoreItems($root){
    $sp = $ui.BkRestoreItems; $sp.Children.Clear()
    $script:RsRows = New-Object System.Collections.Generic.List[object]
    $items = New-Object System.Collections.Generic.List[object]
    foreach($d in $BkFolderDefs){
        $p = Join-Path $root "Files\$($d.Sub)"
        if(Test-Path $p){ $t = Get-ProfileFolder $env:USERPROFILE $d; if(-not $t){ $t = Join-Path $env:USERPROFILE $d.Sub }; $items.Add(@{ Key=$d.Key; Name=$d.Name; Desc="→ $t (ไฟล์เดิมที่ใหม่กว่าจะไม่ถูกทับ)"; Src=$p; Dst=$t; Kind='files' }) }
    }
    if(Test-Path (Join-Path $root "Browsers")){ $items.Add(@{ Key='browsers'; Name='บุ๊กมาร์กเว็บเบราว์เซอร์'; Desc='คืนให้ Chrome / Edge / Brave / Firefox ที่ติดตั้งอยู่ (ต้องปิดเบราว์เซอร์ก่อน)'; Kind='browsers' }) }
    if(@(Get-ChildItem (Join-Path $root "WiFi") -Filter *.xml -ErrorAction SilentlyContinue).Count){ $items.Add(@{ Key='wifi'; Name='รหัส Wi-Fi'; Desc='เพิ่มเครือข่าย Wi-Fi ทั้งหมดกลับเข้าเครื่อง (ต่ออัตโนมัติเมื่ออยู่ในระยะ)'; Kind='wifi' }) }
    if(Test-Path (Join-Path $root "Drivers")){ $items.Add(@{ Key='drivers'; Name='ไดรเวอร์'; Desc='ติดตั้งไดรเวอร์ที่สำรองไว้ (Windows เลือกเฉพาะตัวที่ตรงกับอุปกรณ์)'; Kind='drivers' }) }
    $appList = Join-Path $root "รายการโปรแกรมที่เคยติดตั้ง.txt"
    foreach($it in $items){
        $card = New-Card "16,10" "0,0,0,8"
        $g = New-Grid @('Auto','*')
        $cb = New-Object System.Windows.Controls.CheckBox; $cb.Style = $window.FindResource("Toggle"); $cb.IsChecked = $true; $cb.VerticalAlignment = 'Center'
        Add-ToGrid $g $cb 0
        $st = New-Object System.Windows.Controls.StackPanel; $st.Margin = "16,0,0,0"
        [void]$st.Children.Add((New-Text $it.Name 13.5 $Theme.BodyFg "SemiBold"))
        $d2 = New-Text $it.Desc 11.5 $Theme.MutedFg; $d2.Margin = "0,2,0,0"; [void]$st.Children.Add($d2)
        Add-ToGrid $g $st 1
        $card.Child = $g
        [void]$sp.Children.Add($card)
        $script:RsRows.Add(@{ Item=$it; Cb=$cb })
    }
    if(Test-Path $appList){
        $b = New-Object System.Windows.Controls.Button; $b.Style = $window.FindResource("Link"); $b.Content = "เปิดรายการโปรแกรมที่ลูกค้าเคยใช้ (ไว้ลงคืนที่หน้า ลงโปรแกรม)"; $b.Tag = $appList; $b.HorizontalAlignment = 'Left'
        $b.Add_Click({ Start-Process notepad.exe "`"$($this.Tag)`"" })
        [void]$sp.Children.Add($b)
    }
    $ui.BkStatus.Text = "พบ $($items.Count) รายการที่กู้คืนได้"
}
function Start-Restore {
    $root = $ui.BkSrc.Text
    if(-not $root){ Show-Msg "เลือกโฟลเดอร์สำรองก่อน" "กู้คืนข้อมูล"; return }
    $sel = @($script:RsRows | Where-Object { $_.Cb.IsChecked } | ForEach-Object { $_.Item })
    if($sel.Count -eq 0){ Show-Msg "เลือกอย่างน้อย 1 รายการ" "กู้คืนข้อมูล"; return }
    $keys = @($sel | ForEach-Object { $_.Key })
    if($keys -contains 'browsers'){
        $running = @(Get-Process chrome, msedge, brave, firefox -ErrorAction SilentlyContinue)
        if($running.Count -and -not (Ask-YesNo "เบราว์เซอร์ยังเปิดอยู่ — ต้องปิดก่อนกู้คืนบุ๊กมาร์ก`n`nให้ SCPclear ปิดเบราว์เซอร์ให้เลยไหม?" "กู้คืนข้อมูล" "Warning")){ return }
        $running | Stop-Process -Force -ErrorAction SilentlyContinue; Start-Sleep -Milliseconds 800
    }
    if(-not (Ask-YesNo "กู้คืน $($sel.Count) รายการให้ผู้ใช้ $env:USERNAME ?`n`nไฟล์ที่มีอยู่แล้วและใหม่กว่าจะไม่ถูกเขียนทับ" "กู้คืนข้อมูล")){ return }
    Set-BkBusy $true; $ui.BtnBkOpen.Visibility = 'Collapsed'
    $notes = New-Object System.Collections.Generic.List[string]
    $src = New-Object System.Collections.Generic.List[string]; $dst = New-Object System.Collections.Generic.List[string]
    foreach($it in $sel | Where-Object { $_.Kind -eq 'files' }){ $src.Add($it.Src); $dst.Add($it.Dst) }
    if($keys -contains 'browsers'){
        $L = $env:LOCALAPPDATA; $R = $env:APPDATA
        $map = @{ Chrome = "$L\Google\Chrome\User Data"; Edge = "$L\Microsoft\Edge\User Data"; Brave = "$L\BraveSoftware\Brave-Browser\User Data" }
        foreach($bm in @(Get-ChildItem (Join-Path $root "Browsers") -Recurse -Filter Bookmarks -ErrorAction SilentlyContinue)){
            $browser = $bm.Directory.Parent.Name; $prof = $bm.Directory.Name
            if(-not $map.ContainsKey($browser) -or -not (Test-Path $map[$browser])){ continue }
            $t = Join-Path (Join-Path $map[$browser] $prof) "Bookmarks"
            if(Test-Path $t){ Copy-Item $t "$t.scpclear-bak" -Force -ErrorAction SilentlyContinue }
            $src.Add($bm.FullName); $dst.Add($t); $notes.Add("บุ๊กมาร์ก $browser")
        }
        $ff = Get-ChildItem "$R\Mozilla\Firefox\Profiles" -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -like '*default-release*' } | Select-Object -First 1
        $fsrc = Get-ChildItem (Join-Path $root "Browsers\Firefox") -Recurse -Filter places.sqlite -ErrorAction SilentlyContinue | Select-Object -First 1
        if($ff -and $fsrc){ $t = Join-Path $ff.FullName "places.sqlite"; if(Test-Path $t){ Copy-Item $t "$t.scpclear-bak" -Force -ErrorAction SilentlyContinue }; $src.Add($fsrc.FullName); $dst.Add($t); $notes.Add("บุ๊กมาร์ก Firefox") }
    }
    if($keys -contains 'wifi'){
        $n = 0
        foreach($x in @(Get-ChildItem (Join-Path $root "WiFi") -Filter *.xml -ErrorAction SilentlyContinue)){
            try{ $p = Start-Process netsh.exe -ArgumentList "wlan add profile filename=`"$($x.FullName)`" user=all" -WindowStyle Hidden -PassThru; [void]$p.WaitForExit(10000); if($p.ExitCode -eq 0){ $n++ } }catch{}
        }
        $notes.Add("Wi-Fi $n เครือข่าย")
    }
    $script:BkCopier = New-Object Scp.BackupCopier
    $task = $script:BkCopier.Start($src.ToArray(), $dst.ToArray(), $true)
    $null = Watch-Task $task {
        param($res, $err, $job)
        $c = $script:BkCopier; $script:BkCopier = $null
        $summary = "คืนไฟล์ {0:N0} ไฟล์ ({1})" -f $c.Files, (Fmt-Size $c.CopiedBytes)
        if($c.Failed){ $summary += " • คืนไม่ได้ $($c.Failed) ไฟล์" }
        if($job.State.Notes.Count){ $summary += " • " + ($job.State.Notes -join ", ") }
        if($job.State.Keys -contains 'drivers'){
            $ui.BkStatus.Text = "$summary • กำลังติดตั้งไดรเวอร์..."
            $pr = New-Object Scp.ProcRun
            $pr.Start((Join-Path $env:SystemRoot "System32\pnputil.exe"), "/add-driver `"$(Join-Path $job.State.Root 'Drivers')\*.inf`" /subdirs /install", $false)
            $null = Watch-Proc $pr { param($code, $e2, $j2) Finish-Restore ($j2.State + " • ไดรเวอร์: ติดตั้งแล้ว (อาจต้องรีสตาร์ท)") } -State $summary
        } else { Finish-Restore $summary }
    } {
        param($job)
        $c = $script:BkCopier; if(-not $c){ return }
        $ui.BkBar.IsIndeterminate = $false
        $ui.BkStatus.Text = "กำลังคืนไฟล์... {0:N0} ไฟล์ ({1})  •  {2}" -f $c.Files, (Fmt-Size $c.CopiedBytes), [IO.Path]::GetFileName($c.Current)
    } -State @{ Root=$root; Keys=$keys; Notes=$notes }
}
function Finish-Restore($summary){
    Set-BkBusy $false
    $ui.BkStatus.Text = "✓ กู้คืนเสร็จ — $summary"
    Add-HistoryEntry "กู้คืนข้อมูล" "กู้คืนจาก $($ui.BkSrc.Text)" "สำเร็จ: $summary"
    Show-Msg "กู้คืนข้อมูลเสร็จแล้ว`n`n$summary" "กู้คืนข้อมูล"
}


