# ชื่อในรายการโปรแกรมของ Windows (ใช้ตรวจว่าติดตั้งแล้ว เพราะ winget บางครั้งไม่รู้จักโปรแกรมที่ลงเอง)
$InsMatch = @{
    "Google.Chrome"='^Google Chrome$'; "Mozilla.Firefox"='^Mozilla Firefox'; "LINE.LINE"='^LINE$'; "Zoom.Zoom"='^Zoom'; "Microsoft.Teams"='^Microsoft Teams( \(|$)'
    "Telegram.TelegramDesktop"='^Telegram Desktop'; "Discord.Discord"='^Discord'; "AnyDeskSoftwareGmbH.AnyDesk"='^AnyDesk'; "TeamViewer.TeamViewer"='^TeamViewer'
    "Adobe.Acrobat.Reader.64-bit"='^Adobe Acrobat'; "Foxit.FoxitReader"='^Foxit (PDF )?Reader'; "TheDocumentFoundation.LibreOffice"='^LibreOffice'; "Notepad++.Notepad++"='^Notepad\+\+'
    "7zip.7zip"='^7-Zip'; "RARLab.WinRAR"='^WinRAR'; "voidtools.Everything"='^Everything'; "Microsoft.PowerToys"='^PowerToys'; "VideoLAN.VLC"='^VLC media player'
    "CodecGuide.K-LiteCodecPack.Standard"='^K-Lite'; "Spotify.Spotify"='^Spotify'; "Microsoft.VCRedist.2015+.x64"='Visual C\+\+ 2015-20\d\d .*x64'
    "Microsoft.DotNet.DesktopRuntime.8"='Desktop Runtime - 8\.'; "Oracle.JavaRuntimeEnvironment"='^Java( \d| SE)'; "Google.Drive"='^Google Drive'; "Microsoft.OneDrive"='^Microsoft OneDrive'
    "CPUID.CPU-Z"="CPU-Z"; "REALiX.HWiNFO"="^HWiNFO"; "CrystalDewWorld.CrystalDiskInfo"="^CrystalDiskInfo"; "CrystalDewWorld.CrystalDiskMark"="^CrystalDiskMark"
}

function Get-WingetPath {
    $c = Get-Command winget.exe -ErrorAction SilentlyContinue
    if($c){ return $c.Source }
    $p = Join-Path $env:LOCALAPPDATA "Microsoft\WindowsApps\winget.exe"
    if(Test-Path $p){ return $p }
    return $null
}

function Init-InstallPage {
    $script:InsLoaded = $true
    $script:Winget = Get-WingetPath
    $sp = $ui.InsGroups; $sp.Children.Clear()
    $script:InsRows = New-Object System.Collections.Generic.List[object]
    if(-not $script:Winget){
        $w = New-Text "ไม่พบ winget ในเครื่องนี้ — ติดตั้ง 'App Installer' จาก Microsoft Store (หรืออัปเดต Windows) แล้วเปิดหน้านี้ใหม่" 13 "#E5484D" "SemiBold"
        [void]$sp.Children.Add($w)
        foreach($n in @('BtnInsRun','BtnInsUpgrade','BtnInsCheck')){ $ui[$n].IsEnabled = $false }
        $ui.InsStatus.Text = "ไม่พบ winget"
        return
    }
    foreach($grp in ($InsCatalog | ForEach-Object { $_.G } | Select-Object -Unique)){
        $h = New-Text $grp 11.5 $Theme.SectionFg "Bold"; $h.Margin = "2,10,0,8"
        [void]$sp.Children.Add($h)
        $ug = New-Object System.Windows.Controls.Primitives.UniformGrid; $ug.Columns = 3
        foreach($a in ($InsCatalog | Where-Object { $_.G -eq $grp })){
            $card = New-Card "12,9" "0,0,8,8"
            $g = New-Grid @('Auto','*')
            $cb = New-Object System.Windows.Controls.CheckBox; $cb.Style = $window.FindResource("Toggle"); $cb.VerticalAlignment = 'Center'
            $cb.Add_Click({ Update-InsCount })
            Add-ToGrid $g $cb 0
            $st = New-Object System.Windows.Controls.StackPanel; $st.Margin = "12,0,0,0"; $st.VerticalAlignment = 'Center'
            [void]$st.Children.Add((New-Text $a.N 13 $Theme.BodyFg "SemiBold"))
            $dt = New-Text $a.D 11 $Theme.MutedFg; $dt.TextTrimming = 'CharacterEllipsis'; $dt.TextWrapping = 'NoWrap'; $dt.ToolTip = "$($a.D)`nwinget id: $($a.Id)"
            [void]$st.Children.Add($dt)
            $stt = New-Text "" 11 "#22A06B" "SemiBold"; [void]$st.Children.Add($stt)
            Add-ToGrid $g $st 1
            $card.Child = $g
            [void]$ug.Children.Add($card)
            $script:InsRows.Add(@{ App=$a; Cb=$cb; StatusTb=$stt; Installed=$false })
        }
        [void]$sp.Children.Add($ug)
    }
    Update-InsCount
    Check-InstalledApps
}

function Update-InsCount {
    $n = @($script:InsRows | Where-Object { $_.Cb.IsChecked }).Count
    $ui.BtnInsRun.Content = if($n){ "ติดตั้งที่เลือก ($n)" } else { "ติดตั้งที่เลือก" }
}

function Check-InstalledApps {
    if(-not $script:Winget -or $script:InsBusy){ return }
    $ui.InsStatus.Text = "กำลังตรวจว่าโปรแกรมไหนติดตั้งไว้แล้ว..."; $ui.BtnInsCheck.IsEnabled = $false
    $tmp = Join-Path $TempRoot ("wg_" + [guid]::NewGuid().ToString('N') + ".json")
    $null = Start-BgWork -Work {
        param($Sync, $Wg, $Out)
        New-Item -ItemType Directory -Path (Split-Path $Out) -Force | Out-Null
        $p = Start-Process -FilePath $Wg -ArgumentList "export -o `"$Out`" --accept-source-agreements --disable-interactivity" -WindowStyle Hidden -PassThru
        [void]$p.WaitForExit(120000)
        $ids = @()
        if(Test-Path $Out){ $j = Get-Content $Out -Raw -Encoding UTF8 | ConvertFrom-Json; $ids = @($j.Sources | ForEach-Object { $_.Packages } | ForEach-Object { $_.PackageIdentifier }); Remove-Item $Out -Force -ErrorAction SilentlyContinue }
        $names = @(Get-InstalledApps $true $false | ForEach-Object { $_.Name })
        @{ Ids = $ids; Names = $names }
    } -ArgList @($script:Winget, $tmp) -Functions @('Get-InstalledApps') -OnDone {
        param($res, $err)
        $ui.BtnInsCheck.IsEnabled = $true
        if($err){ $ui.InsStatus.Text = "ตรวจไม่สำเร็จ: $err"; return }
        $d = @($res)[0]; $ids = @($d.Ids); $names = @($d.Names)
        $n = 0
        foreach($r in $script:InsRows){
            $id = $r.App.Id
            $hit = $ids | Where-Object { $_ -ieq $id -or $_ -like "$id.*" } | Select-Object -First 1
            if(-not $hit -and $InsMatch.ContainsKey($id)){ $rx = $InsMatch[$id]; $hit = $names | Where-Object { $_ -match $rx } | Select-Object -First 1 }
            $r.Installed = [bool]$hit
            $r.StatusTb.Text = if($hit){ "✓ ติดตั้งแล้ว" } else { "" }
            if($hit){ $n++; $r.Cb.IsChecked = $false }
        }
        Update-InsCount
        $ui.InsStatus.Text = "มีโปรแกรมในรายการนี้ติดตั้งอยู่แล้ว $n ตัว • winget รู้จักโปรแกรมในเครื่องทั้งหมด $($ids.Count) ตัว"
    }
}

$ui.BtnInsBasic.Add_Click({ foreach($r in $script:InsRows){ $r.Cb.IsChecked = ($r.App.B -and -not $r.Installed) }; Update-InsCount })
$ui.BtnInsNone.Add_Click({ foreach($r in $script:InsRows){ $r.Cb.IsChecked = $false }; Update-InsCount })
$ui.BtnInsCheck.Add_Click({ Check-InstalledApps })
$ui.BtnInsStop.Add_Click({ $script:InsStopAfter = $true; $ui.BtnInsStop.IsEnabled = $false; $ui.BtnInsStop.Content = "จะหยุดหลังตัวนี้" })

function Set-InsBusy($b){
    $script:InsBusy = $b
    foreach($n in @('BtnInsRun','BtnInsUpgrade','BtnInsCheck','BtnInsBasic','BtnInsNone')){ $ui[$n].IsEnabled = -not $b }
    $ui.BtnInsStop.Visibility = if($b){ 'Visible' } else { 'Collapsed' }
    $ui.BtnInsStop.IsEnabled = $true; $ui.BtnInsStop.Content = "หยุดหลังตัวนี้"
}

function Run-WingetQueue {
    if($script:InsQueue.Count -eq 0 -or $script:InsStopAfter){
        Set-InsBusy $false
        $ok = @($script:InsResults | Where-Object { $_.Ok }).Count; $bad = @($script:InsResults | Where-Object { -not $_.Ok })
        $msg = "เสร็จแล้ว: สำเร็จ $ok รายการ" + $(if($bad.Count){ " • ไม่สำเร็จ $($bad.Count): " + (($bad | ForEach-Object { $_.Name }) -join ', ') } else { "" })
        if($script:InsStopAfter -and $script:InsQueue.Count){ $msg += " • หยุดก่อน ยังเหลือ $($script:InsQueue.Count) รายการ" }
        $ui.InsStatus.Text = $msg
        Add-HistoryEntry "ลงโปรแกรม" (($script:InsResults | ForEach-Object { $_.Name }) -join ', ') "สำเร็จ: $msg"
        if($script:InsResults.Count){ Show-Msg $msg "ลงโปรแกรม" }
        Check-InstalledApps
        return
    }
    $job = $script:InsQueue[0]; $script:InsQueue.RemoveAt(0)
    $idx = $script:InsTotal - $script:InsQueue.Count
    $ui.InsStatus.Text = "($idx/$($script:InsTotal)) $($job.Label) ..."
    $script:InsPrefix = $ui.InsOut.Text + "===== $($job.Label) =====`r`n"
    $p = New-Object Scp.ProcRun
    try{ $p.StartCp($script:Winget, $job.Args, 65001) }catch{ $script:InsResults.Add(@{ Name=$job.Name; Ok=$false }); Run-WingetQueue; return }
    $null = Watch-Proc $p {
        param($code, $err, $j)
        $ui.InsOut.Text = $script:InsPrefix + $j.Proc.Text + "`r`n"; $ui.InsOut.ScrollToEnd()
        # 0 = สำเร็จ, 0x8A15002B = ไม่มีอัปเดต/ติดตั้งแล้ว, 0x8A150061 = ติดตั้งอยู่แล้ว
        $ok = ($code -eq 0 -or $code -eq -1978335189 -or $code -eq -1978335135)
        $script:InsResults.Add(@{ Name=$j.State.Name; Ok=$ok })
        $row = $script:InsRows | Where-Object { $_.App.Id -eq $j.State.Id } | Select-Object -First 1
        if($row){ $row.StatusTb.Text = if($ok){ "✓ ติดตั้งแล้ว" } else { "✗ ไม่สำเร็จ (รหัส $code)" }; $row.StatusTb.Foreground = (NewBrush $(if($ok){ "#22A06B" } else { "#E5484D" })); if($ok){ $row.Cb.IsChecked = $false } }
        Update-InsCount
        Run-WingetQueue
    } {
        param($j)
        $ui.InsOut.Text = $script:InsPrefix + $j.Proc.Text; $ui.InsOut.ScrollToEnd()
    } -State $job
}

$ui.BtnInsRun.Add_Click({
    $sel = @($script:InsRows | Where-Object { $_.Cb.IsChecked })
    if($sel.Count -eq 0){ Show-Msg "ติ๊กเลือกโปรแกรมที่จะติดตั้งก่อน (หรือกด เลือกชุดพื้นฐาน)" "ลงโปรแกรม"; return }
    if(-not (Ask-YesNo ("ติดตั้ง $($sel.Count) โปรแกรม?`n`n" + (($sel | ForEach-Object { "•  " + $_.App.N }) -join "`n") + "`n`nดาวน์โหลดจากแหล่งทางการ ใช้เวลาตามความเร็วอินเทอร์เน็ต") "ลงโปรแกรม")){ return }
    $script:InsQueue = New-Object System.Collections.ArrayList
    foreach($r in $sel){ [void]$script:InsQueue.Add(@{ Id=$r.App.Id; Name=$r.App.N; Label="ติดตั้ง $($r.App.N)"; Args="install --id $($r.App.Id) -e --source winget --silent --accept-package-agreements --accept-source-agreements --disable-interactivity" }) }
    $script:InsTotal = $script:InsQueue.Count
    $script:InsResults = New-Object System.Collections.Generic.List[object]
    $script:InsStopAfter = $false
    $ui.InsOut.Text = ""
    Set-InsBusy $true
    Run-WingetQueue
})
$ui.BtnInsUpgrade.Add_Click({
    if(-not (Ask-YesNo "อัปเดตโปรแกรมทั้งหมดในเครื่องที่ winget รู้จักเป็นเวอร์ชันล่าสุด?`n`nอาจใช้เวลานาน และโปรแกรมที่เปิดอยู่อาจถูกปิดระหว่างอัปเดต" "อัปเดตโปรแกรม")){ return }
    $script:InsQueue = New-Object System.Collections.ArrayList
    [void]$script:InsQueue.Add(@{ Id=''; Name='อัปเดตทั้งหมด'; Label="อัปเดตโปรแกรมทั้งหมด"; Args="upgrade --all --silent --accept-package-agreements --accept-source-agreements --disable-interactivity" })
    $script:InsTotal = 1
    $script:InsResults = New-Object System.Collections.Generic.List[object]
    $script:InsStopAfter = $false
    $ui.InsOut.Text = ""
    Set-InsBusy $true
    Run-WingetQueue
})


# ============================================================
#   Windows Tools (งานช่าง): ลิขสิทธิ์ / ซ่อมด่วน / รีสตาร์ทโหมดพิเศษ
# ============================================================
# ถอดรหัส Product Key จาก DigitalProductId (Windows 8 ขึ้นไป)
function Get-InstalledProductKey {
    try{
        $id = (Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction Stop).DigitalProductId
        if(-not $id -or $id.Length -lt 67){ return $null }
        $k = [byte[]]$id.Clone()
        $off = 52
        $isWin8 = ([math]::Truncate($k[66] / 6)) -band 1
        $k[66] = ($k[66] -band 0xF7) -bor (($isWin8 -band 2) * 4)
        $chars = "BCDFGHJKMPQRTVWXY2346789"
        $out = ""; $last = 0
        for($i = 24; $i -ge 0; $i--){
            $cur = 0
            for($x = 14; $x -ge 0; $x--){
                $cur = $cur * 256 + $k[$x + $off]
                $k[$x + $off] = [byte][math]::Floor($cur / 24)
                $cur = $cur % 24
            }
            $out = $chars.Substring($cur, 1) + $out
            $last = $cur
        }
        $p1 = $out.Substring(1, $last); $p2 = $out.Substring(1, $out.Length - 1)
        $out = if($last -eq 0){ "N" + $p2 } else { $p2.Insert($p2.IndexOf($p1) + $p1.Length, "N") }
        return ($out.Substring(0,5), $out.Substring(5,5), $out.Substring(10,5), $out.Substring(15,5), $out.Substring(20,5)) -join '-'
    }catch{ return $null }
}

function Load-LicenseInfo {
    $script:WinKey = $null
    try{
        $lic = Get-CimInstance SoftwareLicensingProduct -Filter "PartialProductKey IS NOT NULL AND ApplicationID='55c92734-d682-4d71-983e-d6ec3f16059f'" -ErrorAction Stop | Select-Object -First 1
        $svc = Get-CimInstance SoftwareLicensingService -ErrorAction SilentlyContinue
        $os = Get-CimInstance Win32_OperatingSystem
        $channel = if($lic.Description -match 'RETAIL'){ "Retail (ซื้อแยก ย้ายเครื่องได้)" } elseif($lic.Description -match 'OEM'){ "OEM (มากับเครื่อง)" } elseif($lic.Description -match 'VOLUME'){ "Volume (องค์กร)" } else { [string]$lic.Description }
        $status = if($lic.LicenseStatus -eq 1){ "✓ Activate แล้ว" } else { "⚠ ยังไม่ได้ Activate" }
        $oem = [string]$svc.OA3xOriginalProductKey
        $inst = Get-InstalledProductKey
        $note = ""
        if($inst -and $lic.PartialProductKey -and -not $inst.EndsWith($lic.PartialProductKey)){ $inst = $null; $note = "ถอดรหัสคีย์ไม่ได้ (คีย์แบบองค์กร/ดิจิทัล) — 5 ตัวท้ายคือ $($lic.PartialProductKey)" }
        $script:WinKey = if($inst){ $inst } elseif($oem){ $oem } else { $null }
        $txt = "$($os.Caption -replace '^Microsoft\s+','')`n$status  •  $channel"
        if($oem){ $txt += "`nมีคีย์ OEM ฝังใน BIOS (ลงใหม่ Activate อัตโนมัติ)" }
        $ui.WtLicInfo.Text = $txt
        if($script:WinKey){
            $src = if($inst){ "คีย์ที่ใช้อยู่" } else { "คีย์ OEM จาก BIOS" }
            $ui.WtKeyNote.Text = "$src — ถ้าเป็น Digital License คีย์ที่ได้อาจเป็นคีย์ทั่วไป แต่ลงใหม่ด้วยบัญชี Microsoft เดิมก็ Activate ได้"
        } else {
            $ui.WtKey.Text = $(if($lic.PartialProductKey){ "•••••-•••••-•••••-•••••-$($lic.PartialProductKey)" } else { "ไม่พบ" })
            $ui.WtKeyNote.Text = $(if($note){ $note } else { "ไม่พบคีย์ที่อ่านได้" })
            $ui.BtnKeyShow.IsEnabled = $false; $ui.BtnKeyCopy.IsEnabled = $false
        }
    }catch{ $ui.WtLicInfo.Text = "อ่านข้อมูลลิขสิทธิ์ไม่ได้" }
}
$ui.BtnKeyShow.Add_Click({
    if(-not $script:WinKey){ return }
    if($ui.WtKey.Text -eq $script:WinKey){ $ui.WtKey.Text = "•••••-•••••-•••••-•••••-" + $script:WinKey.Substring(24); $this.Content = "แสดง" }
    else { $ui.WtKey.Text = $script:WinKey; $this.Content = "ซ่อน" }
})
$ui.BtnKeyCopy.Add_Click({ if($script:WinKey){ try{ [System.Windows.Clipboard]::SetText($script:WinKey); $this.Content = "คัดลอกแล้ว ✓" }catch{} } })

# ---------- ซ่อม Windows ด่วน ----------
$ui.BtnFixWU.Add_Click({
    if(-not (Ask-YesNo "รีเซ็ต Windows Update?`n`nหยุดบริการอัปเดต ล้างแคช (SoftwareDistribution, catroot2) แล้วเริ่มใหม่ — แก้อาการอัปเดตค้าง/ล้มเหลวซ้ำ")){ return }
    Wt-Log "กำลังรีเซ็ต Windows Update..."; Flush-UI
    $r = Invoke-HealthFix 'wu_reset'; Wt-Log $r.Message
    Add-HistoryEntry "ซ่อม Windows" "รีเซ็ต Windows Update" $(if($r.Success){ "สำเร็จ: $($r.Message)" } else { "ล้มเหลว: $($r.Message)" })
})
$ui.BtnFixStore.Add_Click({
    try{ Start-Process wsreset.exe; Wt-Log "รีเซ็ต Microsoft Store แล้ว — Store จะเปิดขึ้นมาเองเมื่อเสร็จ" }catch{ Wt-Log "รีเซ็ต Store ไม่สำเร็จ: $($_.Exception.Message)" }
})
$ui.BtnFixSearch.Add_Click({
    if(-not (Ask-YesNo "ซ่อมการค้นหาของ Windows?`n`nจะสร้างดัชนีค้นหาใหม่ทั้งหมด ระหว่างนี้ผลค้นหาอาจไม่ครบสักพัก")){ return }
    try{
        Stop-Service WSearch -Force -ErrorAction SilentlyContinue
        Set-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows Search' -Name SetupCompletedSuccessfully -Value 0 -Type DWord -ErrorAction Stop
        Start-Service WSearch -ErrorAction SilentlyContinue
        Wt-Log "✓ เริ่มสร้างดัชนีค้นหาใหม่แล้ว (ใช้เวลาสักพักตามจำนวนไฟล์)"
        Add-HistoryEntry "ซ่อม Windows" "สร้างดัชนี Windows Search ใหม่" "สำเร็จ"
    }catch{ Wt-Log "ซ่อม Search ไม่สำเร็จ: $($_.Exception.Message)" }
})
$ui.BtnFixStart.Add_Click({
    if(-not (Ask-YesNo "ซ่อมเมนู Start / Taskbar?`n`nลงทะเบียนส่วนประกอบเมนู Start ใหม่ แล้วรีสตาร์ท Explorer (หน้าจอจะกระพริบ)")){ return }
    $n = 0
    foreach($name in @('Microsoft.Windows.StartMenuExperienceHost','Microsoft.Windows.ShellExperienceHost','MicrosoftWindows.Client.CBS','Microsoft.Windows.Search')){
        foreach($pkg in @(Get-AppxPackage -Name $name -ErrorAction SilentlyContinue)){
            try{ Add-AppxPackage -DisableDevelopmentMode -Register (Join-Path $pkg.InstallLocation 'AppXManifest.xml') -ErrorAction Stop; $n++ }catch{}
        }
    }
    try{ Stop-Process -Name StartMenuExperienceHost, ShellExperienceHost -Force -ErrorAction SilentlyContinue; Stop-Process -Name explorer -Force -ErrorAction SilentlyContinue; Start-Sleep -Milliseconds 800; if(-not (Get-Process explorer -ErrorAction SilentlyContinue)){ Start-Process explorer.exe } }catch{}
    Wt-Log "✓ ลงทะเบียนเมนู Start ใหม่ $n ส่วน และรีสตาร์ท Explorer แล้ว — ถ้ายังไม่หาย ให้รีสตาร์ทเครื่อง"
    Add-HistoryEntry "ซ่อม Windows" "ซ่อมเมนู Start" "สำเร็จ: ลงทะเบียน $n ส่วน"
})
$ui.BtnFixIcon.Add_Click({
    if(-not (Ask-YesNo "ล้าง Icon cache?`n`nExplorer จะปิดชั่วคราวแล้วเปิดใหม่ (หน้าจอจะกระพริบ)")){ return }
    try{
        Stop-Process -Name explorer -Force -ErrorAction SilentlyContinue; Start-Sleep -Milliseconds 800
        Remove-Item "$env:LOCALAPPDATA\IconCache.db" -Force -ErrorAction SilentlyContinue
        Remove-Item "$env:LOCALAPPDATA\Microsoft\Windows\Explorer\iconcache_*.db" -Force -ErrorAction SilentlyContinue
        Start-Process explorer.exe
        Wt-Log "✓ ล้าง Icon cache แล้ว"
    }catch{ Wt-Log "ล้าง Icon cache ไม่สำเร็จ: $($_.Exception.Message)"; if(-not (Get-Process explorer -ErrorAction SilentlyContinue)){ Start-Process explorer.exe } }
})

# ---------- รีสตาร์ทเข้าโหมดพิเศษ ----------
function Test-SafeBootPending {
    try{ return [bool]((& bcdedit.exe /enum '{current}' 2>$null) -match '^\s*safeboot\s') }catch{ return $false }
}
function Update-SafeBootUi { $ui.BtnBootNormal.Visibility = if(Test-SafeBootPending){ 'Visible' } else { 'Collapsed' } }
function Restart-Special($args2, $what){
    if(-not (Ask-YesNo "รีสตาร์ทเครื่องเข้า $what ?`n`nบันทึกงานและปิดโปรแกรมอื่นก่อน — เครื่องจะรีสตาร์ทใน 5 วินาที" "รีสตาร์ท" "Warning")){ return $false }
    try{
        $p = Start-Process shutdown.exe -ArgumentList $args2 -WindowStyle Hidden -PassThru -Wait
        if($p.ExitCode -ne 0){ Show-Msg "สั่งรีสตาร์ทไม่สำเร็จ (รหัส $($p.ExitCode))" "รีสตาร์ท" "Warning"; return $false }
        return $true
    }catch{ Show-Msg "สั่งรีสตาร์ทไม่สำเร็จ: $($_.Exception.Message)" "รีสตาร์ท" "Warning"; return $false }
}
$ui.BtnBootBios.Add_Click({
    if($env:firmware_type -ne 'UEFI'){ Show-Msg "เครื่องนี้ใช้ BIOS แบบเก่า (Legacy) — สั่งเข้า BIOS จาก Windows ไม่ได้`nให้รีสตาร์ทแล้วกดปุ่ม Del / F2 / F10 ค้างตอนเปิดเครื่อง" "เข้า BIOS"; return }
    [void](Restart-Special "/r /fw /t 5" "BIOS / UEFI")
})
$ui.BtnBootAdv.Add_Click({ [void](Restart-Special "/r /o /t 5" "Advanced Startup (เมนูซ่อม Windows)") })
function Set-SafeBoot($mode){
    $label = if($mode -eq 'network'){ "Safe Mode + อินเทอร์เน็ต" } else { "Safe Mode" }
    if(-not (Ask-YesNo "ตั้งให้รีสตาร์ทเข้า $label ครั้งเดียว?`n`nพอเข้า Windows ใน Safe Mode ระบบจะยกเลิกให้เอง ครั้งต่อไปบูตปกติ`n(ถ้ายังติด Safe Mode ให้เปิด SCPclear แล้วกด 'ยกเลิก Safe Mode')" "Safe Mode")){ return }
    $r = Start-Process bcdedit.exe -ArgumentList "/set {current} safeboot $mode" -WindowStyle Hidden -PassThru -Wait
    if($r.ExitCode -ne 0){ Show-Msg "ตั้งค่า Safe Mode ไม่สำเร็จ (รหัส $($r.ExitCode))" "Safe Mode" "Warning"; return }
    # RunOnce ที่ขึ้นต้นด้วย * จะทำงานแม้อยู่ใน Safe Mode -> ยกเลิก safeboot ให้อัตโนมัติ
    try{ Set-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce' -Name '*SCPclearExitSafeMode' -Value 'bcdedit.exe /deletevalue {current} safeboot' -ErrorAction Stop }catch{}
    Update-SafeBootUi
    Wt-Log "ตั้งค่าเข้า $label ครั้งถัดไปแล้ว"
    if(-not (Restart-Special "/r /t 5" $label)){ Wt-Log "ยังไม่รีสตาร์ท — ถ้าไม่ต้องการ Safe Mode แล้ว กด 'ยกเลิก Safe Mode'" }
}
$ui.BtnBootSafe.Add_Click({ Set-SafeBoot 'minimal' })
$ui.BtnBootSafeNet.Add_Click({ Set-SafeBoot 'network' })
$ui.BtnBootNormal.Add_Click({
    $r = Start-Process bcdedit.exe -ArgumentList "/deletevalue {current} safeboot" -WindowStyle Hidden -PassThru -Wait
    Remove-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce' -Name '*SCPclearExitSafeMode' -ErrorAction SilentlyContinue
    Update-SafeBootUi
    Wt-Log $(if($r.ExitCode -eq 0){ "✓ ยกเลิก Safe Mode แล้ว — ครั้งต่อไปบูตปกติ" } else { "ยกเลิก Safe Mode ไม่สำเร็จ (รหัส $($r.ExitCode))" })
})

# ============================================================
#   เครือข่าย: สแกนอุปกรณ์ในวง LAN
# ============================================================
function Load-LanNets {
    $wp = $ui.LanNets; $wp.Children.Clear()
    $nets = @()
    foreach($c in @(Get-NetIPConfiguration -ErrorAction SilentlyContinue | Where-Object { $_.NetAdapter.Status -eq 'Up' })){
        $gw = @($c.IPv4DefaultGateway | ForEach-Object { $_.NextHop })
        foreach($a in @($c.IPv4Address)){
            $ip = [string]$a.IPAddress
            if($ip -like '169.254.*' -or $ip -like '127.*'){ continue }
            $pre = ($ip -split '\.')[0..2] -join '.'
            $g = $gw | Where-Object { $_ -like "$pre.*" } | Select-Object -First 1
            $nets += [pscustomobject]@{ Prefix=$pre; IP=$ip; Gateway=[string]$g; MAC=[string]$c.NetAdapter.MacAddress; Adapter=$c.InterfaceAlias; Alive=$false }
        }
    }
    foreach($n in $nets){ if($n.Gateway){ try{ $n.Alive = (New-Object System.Net.NetworkInformation.Ping).Send($n.Gateway, 400).Status -eq 'Success' }catch{} } }
    $first = $true
    foreach($n in ($nets | Sort-Object @{ e = { -not $_.Alive } }, @{ e = { -not $_.Gateway } })){
        $rb = New-Object System.Windows.Controls.RadioButton
        $rb.Style = $window.FindResource("Seg"); $rb.GroupName = "lannet"; $rb.Tag = $n
        $rb.Content = "$($n.Prefix).0/24  ($($n.Adapter))" + $(if($n.Alive){ " ✓" } elseif($n.Gateway){ " • Gateway ไม่ตอบ" } else { "" })
        if($first){ $rb.IsChecked = $true; $first = $false }
        [void]$wp.Children.Add($rb)
    }
    if($nets.Count -eq 0){ $ui.LanStatus.Text = "ไม่พบเครือข่ายที่เชื่อมต่ออยู่"; $ui.BtnLanScan.IsEnabled = $false }
}
$script:LanItems = New-Object 'System.Collections.ObjectModel.ObservableCollection[Scp.LanHost]'
$ui.LanGrid.ItemsSource = $script:LanItems
$ui.BtnLanScan.Add_Click({
    if($script:Lan){ $script:Lan.Cancel = $true; $ui.LanStatus.Text = "กำลังหยุด..."; return }
    $n = $null; foreach($rb in $ui.LanNets.Children){ if($rb.IsChecked){ $n = $rb.Tag } }
    if(-not $n){ return }
    $script:LanItems.Clear()
    $script:Lan = New-Object Scp.LanScan
    $task = $script:Lan.Start($n.Prefix, $n.IP, $n.Gateway, ($n.MAC -replace ':', '-'))
    $ui.BtnLanScan.Content = "หยุด"
    $null = Watch-Task $task {
        param($res, $err, $job)
        $l = $script:Lan; $script:Lan = $null; $ui.BtnLanScan.Content = "สแกนวง LAN"
        if($err){ $ui.LanStatus.Text = "สแกนไม่สำเร็จ: $err"; return }
        foreach($h in $l.Results){ $script:LanItems.Add($h) }
        $kinds = $l.Results | Group-Object Kind | Sort-Object Count -Descending | ForEach-Object { "$($_.Name) $($_.Count)" }
        $ui.LanStatus.Text = "พบ $($l.Results.Count) อุปกรณ์ในวง $($job.State).0/24" + $(if($kinds){ "  •  " + ($kinds -join ', ') } else { "" }) + $(if($l.Cancel){ " (หยุดก่อนเสร็จ)" } else { "" })
    } {
        param($job)
        $l = $script:Lan; if(-not $l){ return }
        $ph = switch($l.Phase){ 'ping' { "กำลัง Ping ทั้งวง" } 'arp' { "กำลังอ่านตาราง ARP" } 'probe' { "กำลังตรวจพอร์ตและชื่อเครื่อง" } default { "กำลังเตรียม" } }
        $ui.LanStatus.Text = "$ph... $($l.Done)/$($l.Total)"
    } -State $n.Prefix
})
$ui.LanGrid.Add_SelectionChanged({ $on = [bool]$ui.LanGrid.SelectedItem; foreach($b in @($ui.BtnLanWeb, $ui.BtnLanCopy, $ui.BtnLanPing)){ $b.IsEnabled = $on } })
$ui.BtnLanWeb.Add_Click({
    $h = $ui.LanGrid.SelectedItem; if(-not $h){ return }
    $scheme = if((",$($h.Ports -replace ' ','')," -match ',443,') -and -not (",$($h.Ports -replace ' ','')," -match ',80,')){ 'https' } else { 'http' }
    Start-Process "$scheme`://$($h.IP)/"
})
$ui.BtnLanCopy.Add_Click({ $h = $ui.LanGrid.SelectedItem; if($h){ try{ [System.Windows.Clipboard]::SetText($h.IP) }catch{} } })
$ui.BtnLanPing.Add_Click({ $h = $ui.LanGrid.SelectedItem; if($h){ Start-Ping $h.IP } })
$ui.LanGrid.Add_MouseDoubleClick({ $h = $ui.LanGrid.SelectedItem; if($h){ Start-Ping $h.IP } })


# ============================================================
#   เริ่มโปรแกรม
# ============================================================
$WarningPreference = 'SilentlyContinue'
$window.Add_Closing({
    Save-Settings
    foreach($j in @($script:Jobs)){ try{ if($j.Kind -eq 'proc'){ $j.Proc.Kill() } elseif($j.Kind -eq 'ps'){ $j.Sync.Cancel = $true } }catch{} }
    if($script:Stor){ $script:Stor.Cancel = $true }
    if($script:Lf){ $script:Lf.Cancel = $true }
    try{ Get-ChildItem $TempRoot -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -ne "update" } | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue }catch{}
})
$window.Add_ContentRendered({
    Show-Page 'dash'
    try{
        if((Get-CimInstance Win32_ComputerSystem).BootupState -notmatch 'Normal'){
            if(Ask-YesNo "ตอนนี้เครื่องอยู่ใน Safe Mode`n`nต้องการยกเลิก Safe Mode ให้ครั้งต่อไปบูตปกติไหม?" "Safe Mode"){ Start-Process bcdedit.exe -ArgumentList "/deletevalue {current} safeboot" -WindowStyle Hidden -Wait; Show-Msg "ยกเลิกแล้ว — รีสตาร์ทครั้งต่อไปจะเข้า Windows ตามปกติ" "Safe Mode" }
        }
    }catch{}
})
$window.ShowDialog() | Out-Null

}
catch {
    Add-Type -AssemblyName PresentationFramework -ErrorAction SilentlyContinue
    [System.Windows.MessageBox]::Show("เกิดข้อผิดพลาด:`n`n$($_.Exception.Message)`n`n(บรรทัด $($_.InvocationInfo.ScriptLineNumber))","SCPclear - Error") | Out-Null
}
